typedef struct Value Value;
typedef struct Dict Dict;

typedef struct {
    Value *items;
    size_t count;
    size_t capacity;
} List;

struct Value {
    ValueKind kind;
    double number;
    size_t string_offset;
    size_t string_length;
    char *owned_string;
    const char *string_source;
    List *list;
    Dict *dict;
};

typedef struct {
    char *key;
    size_t key_length;
    Value value;
} DictEntry;

struct Dict {
    DictEntry *entries;
    size_t count;
    size_t capacity;
};

typedef struct {
    char **items;
    size_t count;
    size_t capacity;
    List **lists;
    size_t list_count;
    size_t list_capacity;
    Dict **dicts;
    size_t dict_count;
    size_t dict_capacity;
} StringStorage;

typedef struct {
    char *name;
    size_t name_length;
    Value value;
    int is_constant;
} Variable;

typedef struct Environment {
    Variable *variables;
    size_t variable_count;
    size_t variable_capacity;
    struct Environment *parent;
} Environment;

typedef struct {
    char *name;
    size_t name_length;
    size_t declaration_offset;
    const char *source;
    const char *filename;
    Token *parameters;
    size_t parameter_count;
    Token body_open;
} Function;

typedef struct {
    Function *items;
    size_t count;
    size_t capacity;
} FunctionTable;

typedef struct {
    char *name;
    size_t name_length;
    char *parent_name;
    size_t parent_length;
    FunctionTable methods;
    Function *constructor;
} Class;

typedef struct {
    Class *items;
    size_t count;
    size_t capacity;
} ClassTable;

typedef struct {
    char *path;
    char *source;
    int loading;
} Module;

typedef struct {
    Module *items;
    size_t count;
    size_t capacity;
} ModuleStorage;

typedef struct {
    const char *source;
    size_t offset;
    size_t line;
    size_t column;
    const char *filename;
    Language language;
    Environment *environment;
    Environment *globals;
    FunctionTable *function_table;
    ClassTable *class_table;
    StringStorage *string_storage;
    ModuleStorage *modules;
    Token current;
    int failed;
    int in_function;
    int returned;
    Value return_value;
    int loop_depth;
    int loop_broken;
    int loop_continued;
    int in_try;
    int error_caught;
    char *last_error_message;
} Parser;

static int import_module(Parser *parser, Token keyword, Value path_value);
static int interpret_program(Parser *parser);
static int append_list_item(Parser *parser, List *list, Value value,
                            Token token);
static int insert_list_item(Parser *parser, List *list, size_t index,
                            Value value, Token token);

static void write_source_context(Parser *parser, size_t line, size_t column)
{
    const char *line_start = parser->source;
    const char *line_end;
    size_t current_line = 1;
    size_t visible_column = 1;
    const char *cursor;

    if (line == 0 || column == 0) {
        return;
    }
    while (current_line < line && *line_start != '\0') {
        if (*line_start++ == '\n') {
            current_line++;
        }
    }
    if (current_line != line) {
        return;
    }
    line_end = line_start;
    while (*line_end != '\0' && *line_end != '\n') {
        line_end++;
    }
    if (line_end > line_start && line_end[-1] == '\r') {
        line_end--;
    }
    fputs("  ", stderr);
    fwrite(line_start, 1, (size_t)(line_end - line_start), stderr);
    fputc('\n', stderr);
    fputs("  ", stderr);
    cursor = line_start;
    while (cursor < line_end && visible_column < column) {
        unsigned char byte = (unsigned char)*cursor;
        if (byte == '\t') {
            fputc('\t', stderr);
        } else if ((byte & 0xC0) != 0x80) {
            fputc(' ', stderr);
        }
        cursor++;
        while (cursor < line_end &&
               ((unsigned char)*cursor & 0xC0) == 0x80) {
            cursor++;
        }
        visible_column++;
    }
    fputs("^\n", stderr);
}

