static int store_input_string(Parser *parser, Token name, char *input)
{
    StringStorage *storage = parser->string_storage;
    if (storage->count == storage->capacity) {
        size_t capacity = storage->capacity == 0 ? 4 : storage->capacity * 2;
        char **items;
        if (capacity < storage->capacity ||
            capacity > (size_t)-1 / sizeof(*storage->items)) {
            free(input);
            report_error(parser, name.line, name.column,
                         MESSAGE_OUT_OF_MEMORY_FOR_INPUT);
            return 0;
        }
        items = (char **)realloc(storage->items, capacity * sizeof(*items));
        if (items == NULL) {
            free(input);
            report_error(parser, name.line, name.column,
                         MESSAGE_OUT_OF_MEMORY_FOR_INPUT);
            return 0;
        }
        storage->items = items;
        storage->capacity = capacity;
    }
    storage->items[storage->count++] = input;
    return 1;
}

static int store_owned_string(Parser *parser, Token operation, char *string)
{
    StringStorage *storage = parser->string_storage;
    if (storage->count == storage->capacity) {
        size_t capacity = storage->capacity == 0 ? 4 : storage->capacity * 2;
        char **items;
        if (capacity < storage->capacity ||
            capacity > (size_t)-1 / sizeof(*storage->items)) {
            free(string);
            report_error(parser, operation.line, operation.column,
                         MESSAGE_OUT_OF_MEMORY_FOR_STRING);
            return 0;
        }
        items = (char **)realloc(storage->items, capacity * sizeof(*items));
        if (items == NULL) {
            free(string);
            report_error(parser, operation.line, operation.column,
                         MESSAGE_OUT_OF_MEMORY_FOR_STRING);
            return 0;
        }
        storage->items = items;
        storage->capacity = capacity;
    }
    storage->items[storage->count++] = string;
    return 1;
}

static size_t decoded_string_length(Parser *parser, Value value)
{
    size_t index;
    size_t length = 0;
    const char *source = value.string_source == NULL ?
                         parser->source : value.string_source;
    if (value.owned_string != NULL) {
        return value.string_length;
    }
    for (index = 0; index < value.string_length; index++) {
        if (source[value.string_offset + index] == '\\') {
            index++;
        }
        length++;
    }
    return length;
}

static size_t copy_value_string(Parser *parser, Value value, char *output)
{
    size_t index;
    size_t length = 0;
    const char *source = value.string_source == NULL ?
                         parser->source : value.string_source;
    if (value.owned_string != NULL) {
        memcpy(output, value.owned_string, value.string_length);
        return value.string_length;
    }
    for (index = 0; index < value.string_length; index++) {
        char character = source[value.string_offset + index];
        if (character == '\\' && index + 1 < value.string_length) {
            index++;
            switch (source[value.string_offset + index]) {
            case '"': character = '"'; break;
            case '\\': character = '\\'; break;
            case 'n': character = '\n'; break;
            case 'r': character = '\r'; break;
            case 't': character = '\t'; break;
            default: break;
            }
        }
        output[length++] = character;
    }
    return length;
}

static char *value_to_c_string(Parser *parser, Value value)
{
    size_t len = decoded_string_length(parser, value);
    char *buf = (char *)malloc(len + 1);
    if (buf == NULL) {
        return NULL;
    }
    copy_value_string(parser, value, buf);
    buf[len] = '\0';
    return buf;
}

static Dict *create_dict(Parser *parser, Token token)
{
    StringStorage *storage = parser->string_storage;
    Dict *dict;

    if (storage->dict_count == storage->dict_capacity) {
        size_t capacity = storage->dict_capacity == 0 ? 4 :
                          storage->dict_capacity * 2;
        Dict **dicts;
        if (capacity < storage->dict_capacity ||
            capacity > (size_t)-1 / sizeof(*storage->dicts)) {
            report_error(parser, token.line, token.column,
                         MESSAGE_OUT_OF_MEMORY);
            return NULL;
        }
        dicts = (Dict **)realloc(storage->dicts,
                                 capacity * sizeof(*dicts));
        if (dicts == NULL) {
            report_error(parser, token.line, token.column,
                         MESSAGE_OUT_OF_MEMORY);
            return NULL;
        }
        storage->dicts = dicts;
        storage->dict_capacity = capacity;
    }
    dict = (Dict *)calloc(1, sizeof(*dict));
    if (dict == NULL) {
        report_error(parser, token.line, token.column,
                     MESSAGE_OUT_OF_MEMORY);
        return NULL;
    }
    storage->dicts[storage->dict_count++] = dict;
    return dict;
}

static Value *dict_get(Dict *dict, const char *key, size_t key_len)
{
    if (dict == NULL) return NULL;
    for (size_t i = 0; i < dict->count; i++) {
        if (dict->entries[i].key_length == key_len &&
            memcmp(dict->entries[i].key, key, key_len) == 0) {
            return &dict->entries[i].value;
        }
    }
    return NULL;
}

static int dict_set(Parser *parser, Dict *dict, const char *key, size_t key_len,
                    Value val, Token token)
{
    if (dict == NULL) return 0;
    Value *existing = dict_get(dict, key, key_len);
    if (existing != NULL) {
        *existing = val;
        return 1;
    }
    if (dict->count == dict->capacity) {
        size_t new_cap = dict->capacity == 0 ? 4 : dict->capacity * 2;
        DictEntry *new_entries = (DictEntry *)realloc(dict->entries,
                                                      new_cap * sizeof(DictEntry));
        if (new_entries == NULL) {
            report_error(parser, token.line, token.column, MESSAGE_OUT_OF_MEMORY);
            return 0;
        }
        dict->entries = new_entries;
        dict->capacity = new_cap;
    }
    char *k_copy = (char *)malloc(key_len + 1);
    if (k_copy == NULL) {
        report_error(parser, token.line, token.column, MESSAGE_OUT_OF_MEMORY);
        return 0;
    }
    memcpy(k_copy, key, key_len);
    k_copy[key_len] = '\0';
    dict->entries[dict->count].key = k_copy;
    dict->entries[dict->count].key_length = key_len;
    dict->entries[dict->count].value = val;
    dict->count++;
    return 1;
}

static int dict_delete(Dict *dict, const char *key, size_t key_len)
{
    if (dict == NULL) return 0;
    for (size_t i = 0; i < dict->count; i++) {
        if (dict->entries[i].key_length == key_len &&
            memcmp(dict->entries[i].key, key, key_len) == 0) {
            free(dict->entries[i].key);
            for (size_t j = i; j + 1 < dict->count; j++) {
                dict->entries[j] = dict->entries[j + 1];
            }
            dict->count--;
            return 1;
        }
    }
    return 0;
}

static int next_string_byte(Parser *parser, Value value, size_t *index)
{
    int character;
    const char *source = value.string_source == NULL ?
                         parser->source : value.string_source;
    if (value.owned_string != NULL) {
        return (unsigned char)value.owned_string[(*index)++];
    }
    character = (unsigned char)source[value.string_offset + *index];
    (*index)++;
    if (character == '\\' && *index < value.string_length) {
        switch (source[value.string_offset + *index]) {
        case '"': character = '"'; break;
        case '\\': character = '\\'; break;
        case 'n': character = '\n'; break;
        case 'r': character = '\r'; break;
        case 't': character = '\t'; break;
        default: break;
        }
        (*index)++;
    }
    return character;
}

static int string_values_equal(Parser *parser, Value left, Value right)
{
    size_t left_index = 0;
    size_t right_index = 0;
    size_t left_length = decoded_string_length(parser, left);
    size_t right_length = decoded_string_length(parser, right);

    if (left_length != right_length) {
        return 0;
    }
    while (left_index < left_length) {
        if (next_string_byte(parser, left, &left_index) !=
            next_string_byte(parser, right, &right_index)) {
            return 0;
        }
    }
    return 1;
}

static size_t string_codepoint_length(Parser *parser, Value value)
{
    size_t index = 0;
    size_t count = 0;
    while (index < value.string_length) {
        int character = next_string_byte(parser, value, &index);
        if (((unsigned char)character & 0xC0) != 0x80) {
            count++;
        }
    }
    return count;
}

static size_t utf8_total_codepoints(const char *str, size_t str_len)
{
    size_t count = 0;
    size_t i;
    for (i = 0; i < str_len; i++) {
        if (((unsigned char)str[i] & 0xC0) != 0x80) {
            count++;
        }
    }
    return count;
}

static unsigned int utf8_decode_codepoint(const char *bytes, size_t len)
{
    if (len == 0) return 0;
    unsigned char b0 = (unsigned char)bytes[0];
    if (b0 < 0x80) {
        return b0;
    } else if ((b0 & 0xE0) == 0xC0 && len >= 2) {
        return ((b0 & 0x1F) << 6) | ((unsigned char)bytes[1] & 0x3F);
    } else if ((b0 & 0xF0) == 0xE0 && len >= 3) {
        return ((b0 & 0x0F) << 12) | (((unsigned char)bytes[1] & 0x3F) << 6) | ((unsigned char)bytes[2] & 0x3F);
    } else if ((b0 & 0xF8) == 0xF0 && len >= 4) {
        return ((b0 & 0x07) << 18) | (((unsigned char)bytes[1] & 0x3F) << 12) | (((unsigned char)bytes[2] & 0x3F) << 6) | ((unsigned char)bytes[3] & 0x3F);
    }
    return b0;
}

static size_t utf8_encode_codepoint(unsigned int cp, char *out_bytes)
{
    if (cp <= 0x7F) {
        out_bytes[0] = (char)cp;
        return 1;
    } else if (cp <= 0x7FF) {
        out_bytes[0] = (char)(0xC0 | ((cp >> 6) & 0x1F));
        out_bytes[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    } else if (cp <= 0xFFFF) {
        out_bytes[0] = (char)(0xE0 | ((cp >> 12) & 0x0F));
        out_bytes[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out_bytes[2] = (char)(0x80 | (cp & 0x3F));
        return 3;
    } else {
        out_bytes[0] = (char)(0xF0 | ((cp >> 18) & 0x07));
        out_bytes[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        out_bytes[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out_bytes[3] = (char)(0x80 | (cp & 0x3F));
        return 4;
    }
}
static size_t utf8_codepoint_to_byte_offset(const char *str, size_t str_len, size_t target_cp)
{
    size_t cp = 0;
    size_t i = 0;
    while (i < str_len && cp < target_cp) {
        i++;
        while (i < str_len && ((unsigned char)str[i] & 0xC0) == 0x80) {
            i++;
        }
        cp++;
    }
    return i;
}

static int concatenate_strings(Parser *parser, Token operation,
                               Value left, Value right, Value *result)
{
    size_t left_length = decoded_string_length(parser, left);
    size_t right_length = decoded_string_length(parser, right);
    size_t total_length;
    char *string;

    if (left_length == (size_t)-1 ||
        right_length > (size_t)-1 - left_length - 1) {
        report_error(parser, operation.line, operation.column,
                     MESSAGE_OUT_OF_MEMORY_FOR_STRING);
        return 0;
    }
    total_length = left_length + right_length;
    string = (char *)malloc(total_length + 1);
    if (string == NULL) {
        report_error(parser, operation.line, operation.column,
                     MESSAGE_OUT_OF_MEMORY_FOR_STRING);
        return 0;
    }
    left_length = copy_value_string(parser, left, string);
    right_length = copy_value_string(parser, right, string + left_length);
    string[left_length + right_length] = '\0';
    if (!store_owned_string(parser, operation, string)) {
        return 0;
    }

    *result = number_value(0.0);
    result->kind = VALUE_STRING;
    result->string_length = left_length + right_length;
    result->owned_string = string;
    return 1;
}

static int read_input_line(Parser *parser, Token name, Value prompt,
                           Value *result)
{
    size_t capacity = 64;
    size_t length = 0;
    int received_character = 0;
    char *input = (char *)malloc(capacity);
    int character;

    if (input == NULL) {
        report_error(parser, name.line, name.column,
                     MESSAGE_OUT_OF_MEMORY_FOR_INPUT);
        return 0;
    }
    if (prompt.owned_string != NULL) {
        if (fwrite(prompt.owned_string, 1, prompt.string_length, stdout) !=
                prompt.string_length ||
            fflush(stdout) == EOF) {
            free(input);
            report_error(parser, name.line, name.column, MESSAGE_WRITE_OUTPUT);
            return 0;
        }
    } else if (!write_string(parser, stdout,
                             prompt.string_source == NULL ?
                                 parser->source : prompt.string_source,
                             prompt.string_offset,
                             prompt.string_length) ||
               fflush(stdout) == EOF) {
        free(input);
        report_error(parser, name.line, name.column, MESSAGE_WRITE_OUTPUT);
        return 0;
    }

    while ((character = fgetc(stdin)) != EOF && character != '\n') {
        received_character = 1;
        if (character == '\0') {
            free(input);
            report_error(parser, name.line, name.column,
                         MESSAGE_COULD_NOT_READ_INPUT);
            return 0;
        }
        if (length + 1 >= capacity) {
            size_t new_capacity;
            char *new_input;
            if (capacity > (size_t)-1 / 2) {
                free(input);
                report_error(parser, name.line, name.column,
                             MESSAGE_OUT_OF_MEMORY_FOR_INPUT);
                return 0;
            }
            new_capacity = capacity * 2;
            new_input = (char *)realloc(input, new_capacity);
            if (new_input == NULL) {
                free(input);
                report_error(parser, name.line, name.column,
                             MESSAGE_OUT_OF_MEMORY_FOR_INPUT);
                return 0;
            }
            input = new_input;
            capacity = new_capacity;
        }
        input[length++] = (char)character;
    }
    if (ferror(stdin) || (character == EOF && !received_character)) {
        free(input);
        report_error(parser, name.line, name.column,
                     MESSAGE_COULD_NOT_READ_INPUT);
        return 0;
    }
    if (length > 0 && input[length - 1] == '\r') {
        length--;
    }
    input[length] = '\0';
    if (!store_input_string(parser, name, input)) {
        return 0;
    }

    *result = number_value(0.0);
    result->kind = VALUE_STRING;
    result->string_length = length;
    result->owned_string = input;
    return 1;
}

static Value call_function(Parser *parser, Function function,
                           const Value *arguments)
{
    Environment local_environment;
    Parser callee = *parser;
    size_t index;
    Value result = null_value();

    memset(&local_environment, 0, sizeof(local_environment));
    local_environment.parent = parser->globals;
    callee.environment = &local_environment;
    callee.source = function.source;
    callee.filename = function.filename;
    callee.in_function = 1;
    callee.returned = 0;
    callee.return_value = null_value();
    callee.failed = 0;
    callee.offset = function.body_open.source_offset;
    callee.line = function.body_open.line;
    callee.column = function.body_open.column;
    callee.current = make_token(TOKEN_EOF, callee.line, callee.column);
    advance_token(&callee);

    for (index = 0; index < function.parameter_count; index++) {
        if (!declare_variable(&callee, function.parameters[index],
                              arguments[index])) {
            break;
        }
    }
    if (!callee.failed) {
        parse_block(&callee, 1);
    }
    if (callee.failed) {
        parser->failed = 1;
    } else if (callee.returned) {
        result = callee.return_value;
    }
    while (local_environment.variable_count > 0) {
        free(local_environment.variables[
            --local_environment.variable_count].name);
    }
    free(local_environment.variables);
    return result;
}

static Value call_method(Parser *parser, Function function, Value instance,
                         const Value *arguments, size_t argument_count, Token call_token)
{
    Environment local_environment;
    Parser callee = *parser;
    size_t index;
    Value result = null_value();

    if (function.parameter_count != argument_count) {
        report_error(parser, call_token.line, call_token.column,
                     MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }

    memset(&local_environment, 0, sizeof(local_environment));
    local_environment.parent = parser->globals;
    callee.environment = &local_environment;
    callee.source = function.source;
    callee.filename = function.filename;
    callee.in_function = 1;
    callee.returned = 0;
    callee.return_value = null_value();
    callee.failed = 0;
    callee.offset = function.body_open.source_offset;
    callee.line = function.body_open.line;
    callee.column = function.body_open.column;
    callee.current = make_token(TOKEN_EOF, callee.line, callee.column);
    advance_token(&callee);

    declare_variable_raw(&callee, "a_pote", 6, instance);
    declare_variable_raw(&callee, "આ_પોતે", strlen("આ_પોતે"), instance);
    declare_variable_raw(&callee, "this", 4, instance);
    declare_variable_raw(&callee, "self", 4, instance);

    for (index = 0; index < function.parameter_count; index++) {
        if (!declare_variable(&callee, function.parameters[index], arguments[index])) {
            break;
        }
    }
    if (!callee.failed) {
        parse_block(&callee, 1);
    }
    if (callee.failed) {
        parser->failed = 1;
        parser->error_caught = callee.error_caught;
        if (callee.last_error_message && !parser->last_error_message) {
            parser->last_error_message = copy_string(callee.last_error_message);
        }
    } else if (callee.returned) {
        result = callee.return_value;
    }
    while (local_environment.variable_count > 0) {
        free(local_environment.variables[--local_environment.variable_count].name);
    }
    free(local_environment.variables);
    return result;
}

typedef struct {
    char *data;
    size_t length;
    size_t capacity;
    int failed;
} StringBuffer;

static void sb_init(StringBuffer *sb)
{
    sb->capacity = 64;
    sb->length = 0;
    sb->failed = 0;
    sb->data = (char *)malloc(sb->capacity);
    if (sb->data == NULL) {
        sb->failed = 1;
    } else {
        sb->data[0] = '\0';
    }
}

static void sb_append(StringBuffer *sb, const char *str, size_t len)
{
    if (sb->failed || len == 0) {
        return;
    }
    if (sb->length + len + 1 > sb->capacity) {
        size_t new_cap = sb->capacity * 2;
        char *new_data;
        if (new_cap < sb->length + len + 1) {
            new_cap = sb->length + len + 16;
        }
        new_data = (char *)realloc(sb->data, new_cap);
        if (new_data == NULL) {
            sb->failed = 1;
            return;
        }
        sb->data = new_data;
        sb->capacity = new_cap;
    }
    memcpy(sb->data + sb->length, str, len);
    sb->length += len;
    sb->data[sb->length] = '\0';
}

static void sb_free(StringBuffer *sb)
{
    if (sb != NULL && sb->data != NULL) {
        free(sb->data);
        sb->data = NULL;
    }
    if (sb != NULL) {
        sb->length = 0;
        sb->capacity = 0;
    }
}

static void format_value_to_buffer(Parser *parser, Value value,
                                   StringBuffer *sb, List **ancestors,
                                   size_t depth)
{
    size_t index;
    if (sb->failed) {
        return;
    }
    if (value.kind == VALUE_STRING) {
        if (value.owned_string != NULL) {
            sb_append(sb, value.owned_string, value.string_length);
        } else {
            size_t len = decoded_string_length(parser, value);
            char *temp = (char *)malloc(len + 1);
            if (temp == NULL) {
                sb->failed = 1;
                return;
            }
            copy_value_string(parser, value, temp);
            sb_append(sb, temp, len);
            free(temp);
        }
        return;
    }
    if (value.kind == VALUE_LIST) {
        if (depth >= 256) {
            sb_append(sb, "[...]", 5);
            return;
        }
        for (index = 0; index < depth; index++) {
            if (ancestors[index] == value.list) {
                sb_append(sb, "<cycle>", 7);
                return;
            }
        }
        ancestors[depth] = value.list;
        sb_append(sb, "[", 1);
        for (index = 0; index < value.list->count; index++) {
            if (index > 0) {
                sb_append(sb, ", ", 2);
            }
            format_value_to_buffer(parser, value.list->items[index], sb,
                                   ancestors, depth + 1);
        }
        sb_append(sb, "]", 1);
        return;
    }
    if (value.kind == VALUE_DICT) {
        if (depth >= 256) {
            sb_append(sb, "{...}", 5);
            return;
        }
        sb_append(sb, "{", 1);
        for (index = 0; index < value.dict->count; index++) {
            if (index > 0) {
                sb_append(sb, ", ", 2);
            }
            sb_append(sb, value.dict->entries[index].key,
                      value.dict->entries[index].key_length);
            sb_append(sb, ": ", 2);
            format_value_to_buffer(parser, value.dict->entries[index].value,
                                   sb, ancestors, depth + 1);
        }
        sb_append(sb, "}", 1);
        return;
    }
    if (value.kind == VALUE_NULL) {
        sb_append(sb, "\xE0\xAA\xA8\xE0\xAA\x95\xE0\xAA\xBE\xE0\xAA\xAE\xE0\xAB\x8B", 15);
        return;
    }
    {
        char num_buf[64];
        snprintf(num_buf, sizeof(num_buf), "%.15g", value.number);
        sb_append(sb, num_buf, strlen(num_buf));
    }
}

static int format_value_as_string(Parser *parser, Token name, Value value,
                                  Value *result)
{
    List *ancestors[256];
    StringBuffer sb;
    sb_init(&sb);
    if (sb.failed) {
        report_error(parser, name.line, name.column,
                     MESSAGE_OUT_OF_MEMORY_FOR_STRING);
        return 0;
    }
    format_value_to_buffer(parser, value, &sb, ancestors, 0);
    if (sb.failed) {
        free(sb.data);
        report_error(parser, name.line, name.column,
                     MESSAGE_OUT_OF_MEMORY_FOR_STRING);
        return 0;
    }
    if (!store_owned_string(parser, name, sb.data)) {
        return 0;
    }
    *result = number_value(0.0);
    result->kind = VALUE_STRING;
    result->string_length = sb.length;
    result->owned_string = sb.data;
    return 1;
}

static int values_are_equal(Parser *parser, Value a, Value b)
{
    if (a.kind != b.kind) {
        return 0;
    }
    if (a.kind == VALUE_NUMBER) {
        return a.number == b.number;
    }
    if (a.kind == VALUE_STRING) {
        return string_values_equal(parser, a, b);
    }
    if (a.kind == VALUE_NULL) {
        return 1;
    }
    if (a.kind == VALUE_LIST) {
        return a.list == b.list;
    }
    if (a.kind == VALUE_DICT) {
        return a.dict == b.dict;
    }
    return 0;
}

static int compare_sort_values(Parser *parser, Value a, Value b)
{
    if (a.kind != b.kind) {
        return a.kind < b.kind ? -1 : 1;
    }
    if (a.kind == VALUE_NUMBER) {
        if (a.number < b.number) return -1;
        if (a.number > b.number) return 1;
        return 0;
    }
    if (a.kind == VALUE_STRING) {
        size_t a_len = decoded_string_length(parser, a);
        size_t b_len = decoded_string_length(parser, b);
        size_t min_len = a_len < b_len ? a_len : b_len;
        size_t a_idx = 0;
        size_t b_idx = 0;
        size_t i;
        for (i = 0; i < min_len; i++) {
            unsigned char cb_a = (unsigned char)next_string_byte(parser, a, &a_idx);
            unsigned char cb_b = (unsigned char)next_string_byte(parser, b, &b_idx);
            if (cb_a < cb_b) return -1;
            if (cb_a > cb_b) return 1;
        }
        if (a_len < b_len) return -1;
        if (a_len > b_len) return 1;
        return 0;
    }
    return 0;
}

static Value pad_string_value(Parser *parser, Token name, Value str_val,
                              Value width_val, Value *opt_pad_val, int is_left)
{
    Value result = str_val;
    size_t target_width = (size_t)width_val.number;
    size_t str_cp = string_codepoint_length(parser, str_val);
    size_t pad_cp;
    size_t needed_cp;
    size_t str_bytes;
    size_t pad_bytes;
    size_t full_repeats;
    size_t rem_cp;
    size_t rem_bytes;
    size_t pad_total_bytes;
    size_t total_bytes;
    char *str_buf;
    char *pad_buf;
    char *out_buf;
    size_t r;

    if (str_cp >= target_width) {
        return str_val;
    }

    if (opt_pad_val != NULL) {
        pad_cp = string_codepoint_length(parser, *opt_pad_val);
        if (pad_cp == 0) {
            return str_val;
        }
        pad_bytes = decoded_string_length(parser, *opt_pad_val);
        pad_buf = (char *)malloc(pad_bytes + 1);
        if (pad_buf == NULL) {
            report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
            return result;
        }
        copy_value_string(parser, *opt_pad_val, pad_buf);
        pad_buf[pad_bytes] = '\0';
    } else {
        pad_cp = 1;
        pad_bytes = 1;
        pad_buf = (char *)malloc(2);
        if (pad_buf == NULL) {
            report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
            return result;
        }
        pad_buf[0] = ' ';
        pad_buf[1] = '\0';
    }

    needed_cp = target_width - str_cp;
    str_bytes = decoded_string_length(parser, str_val);
    str_buf = (char *)malloc(str_bytes + 1);
    if (str_buf == NULL) {
        free(pad_buf);
        report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
        return result;
    }
    copy_value_string(parser, str_val, str_buf);
    str_buf[str_bytes] = '\0';

    full_repeats = needed_cp / pad_cp;
    rem_cp = needed_cp % pad_cp;
    rem_bytes = utf8_codepoint_to_byte_offset(pad_buf, pad_bytes, rem_cp);

    if (full_repeats > 0 && pad_bytes > (size_t)-1 / full_repeats) {
        free(str_buf);
        free(pad_buf);
        report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
        return result;
    }
    pad_total_bytes = full_repeats * pad_bytes + rem_bytes;
    if (str_bytes > (size_t)-1 - pad_total_bytes) {
        free(str_buf);
        free(pad_buf);
        report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
        return result;
    }
    total_bytes = str_bytes + pad_total_bytes;

    out_buf = (char *)malloc(total_bytes + 1);
    if (out_buf == NULL) {
        free(str_buf);
        free(pad_buf);
        report_error(parser, name.line, name.column, MESSAGE_OUT_OF_MEMORY);
        return result;
    }

    if (is_left) {
        char *ptr = out_buf;
        for (r = 0; r < full_repeats; r++) {
            memcpy(ptr, pad_buf, pad_bytes);
            ptr += pad_bytes;
        }
        if (rem_bytes > 0) {
            memcpy(ptr, pad_buf, rem_bytes);
            ptr += rem_bytes;
        }
        memcpy(ptr, str_buf, str_bytes);
    } else {
        char *ptr = out_buf;
        memcpy(ptr, str_buf, str_bytes);
        ptr += str_bytes;
        for (r = 0; r < full_repeats; r++) {
            memcpy(ptr, pad_buf, pad_bytes);
            ptr += pad_bytes;
        }
        if (rem_bytes > 0) {
            memcpy(ptr, pad_buf, rem_bytes);
            ptr += rem_bytes;
        }
    }
    out_buf[total_bytes] = '\0';
    free(str_buf);
    free(pad_buf);

    if (store_owned_string(parser, name, out_buf)) {
        result = number_value(0.0);
        result.kind = VALUE_STRING;
        result.string_length = total_bytes;
        result.owned_string = out_buf;
    }
    return result;
}

static int g_script_argc = 0;
static char **g_script_argv = NULL;

static Value make_owned_string_value(Parser *parser, Token name, char *data, size_t length)
{
    Value result = number_value(0.0);
    if (!store_owned_string(parser, name, data)) {
        return null_value();
    }
    result.kind = VALUE_STRING;
    result.string_length = length;
    result.owned_string = data;
    return result;
}

/* --- SHA-256 Implementation --- */
typedef struct {
    uint8_t data[64];
    uint32_t datalen;
    unsigned long long bitlen;
    uint32_t state[8];
} SHA256Context;

#define SHA256_ROTR(a,b) (((a) >> (b)) | ((a) << (32-(b))))
#define SHA256_CH(x,y,z) (((x) & (y)) ^ (~(x) & (z)))
#define SHA256_MAJ(x,y,z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))
#define SHA256_EP0(x) (SHA256_ROTR(x,2) ^ SHA256_ROTR(x,13) ^ SHA256_ROTR(x,22))
#define SHA256_EP1(x) (SHA256_ROTR(x,6) ^ SHA256_ROTR(x,11) ^ SHA256_ROTR(x,25))
#define SHA256_SIG0(x) (SHA256_ROTR(x,7) ^ SHA256_ROTR(x,18) ^ ((x) >> 3))
#define SHA256_SIG1(x) (SHA256_ROTR(x,17) ^ SHA256_ROTR(x,19) ^ ((x) >> 10))

static const uint32_t sha256_k[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static void sha256_transform(SHA256Context *ctx, const uint8_t data[])
{
    uint32_t a, b, c, d, e, f, g, h, i, j, t1, t2, m[64];
    for (i = 0, j = 0; i < 16; ++i, j += 4)
        m[i] = ((uint32_t)data[j] << 24) | ((uint32_t)data[j + 1] << 16) | ((uint32_t)data[j + 2] << 8) | ((uint32_t)data[j + 3]);
    for (; i < 64; ++i)
        m[i] = SHA256_SIG1(m[i - 2]) + m[i - 7] + SHA256_SIG0(m[i - 15]) + m[i - 16];
    a = ctx->state[0]; b = ctx->state[1]; c = ctx->state[2]; d = ctx->state[3];
    e = ctx->state[4]; f = ctx->state[5]; g = ctx->state[6]; h = ctx->state[7];
    for (i = 0; i < 64; ++i) {
        t1 = h + SHA256_EP1(e) + SHA256_CH(e, f, g) + sha256_k[i] + m[i];
        t2 = SHA256_EP0(a) + SHA256_MAJ(a, b, c);
        h = g; g = f; f = e; e = d + t1;
        d = c; c = b; b = a; a = t1 + t2;
    }
    ctx->state[0] += a; ctx->state[1] += b; ctx->state[2] += c; ctx->state[3] += d;
    ctx->state[4] += e; ctx->state[5] += f; ctx->state[6] += g; ctx->state[7] += h;
}

static void sha256_init(SHA256Context *ctx)
{
    ctx->datalen = 0;
    ctx->bitlen = 0;
    ctx->state[0] = 0x6a09e667;
    ctx->state[1] = 0xbb67ae85;
    ctx->state[2] = 0x3c6ef372;
    ctx->state[3] = 0xa54ff53a;
    ctx->state[4] = 0x510e527f;
    ctx->state[5] = 0x9b05688c;
    ctx->state[6] = 0x1f83d9ab;
    ctx->state[7] = 0x5be0cd19;
}

static void sha256_update(SHA256Context *ctx, const uint8_t data[], size_t len)
{
    size_t i;
    for (i = 0; i < len; ++i) {
        ctx->data[ctx->datalen] = data[i];
        ctx->datalen++;
        if (ctx->datalen == 64) {
            sha256_transform(ctx, ctx->data);
            ctx->bitlen += 512;
            ctx->datalen = 0;
        }
    }
}

static void sha256_final(SHA256Context *ctx, uint8_t hash[])
{
    uint32_t i = ctx->datalen;
    if (ctx->datalen < 56) {
        ctx->data[i++] = 0x80;
        while (i < 56) ctx->data[i++] = 0x00;
    } else {
        ctx->data[i++] = 0x80;
        while (i < 64) ctx->data[i++] = 0x00;
        sha256_transform(ctx, ctx->data);
        memset(ctx->data, 0, 56);
    }
    ctx->bitlen += (unsigned long long)ctx->datalen * 8;
    ctx->data[63] = (uint8_t)(ctx->bitlen);
    ctx->data[62] = (uint8_t)(ctx->bitlen >> 8);
    ctx->data[61] = (uint8_t)(ctx->bitlen >> 16);
    ctx->data[60] = (uint8_t)(ctx->bitlen >> 24);
    ctx->data[59] = (uint8_t)(ctx->bitlen >> 32);
    ctx->data[58] = (uint8_t)(ctx->bitlen >> 40);
    ctx->data[57] = (uint8_t)(ctx->bitlen >> 48);
    ctx->data[56] = (uint8_t)(ctx->bitlen >> 56);
    sha256_transform(ctx, ctx->data);
    for (i = 0; i < 4; ++i) {
        hash[i]      = (uint8_t)((ctx->state[0] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 4]  = (uint8_t)((ctx->state[1] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 8]  = (uint8_t)((ctx->state[2] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 12] = (uint8_t)((ctx->state[3] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 16] = (uint8_t)((ctx->state[4] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 20] = (uint8_t)((ctx->state[5] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 24] = (uint8_t)((ctx->state[6] >> (24 - i * 8)) & 0x000000ff);
        hash[i + 28] = (uint8_t)((ctx->state[7] >> (24 - i * 8)) & 0x000000ff);
    }
}

static char *sha256_hash_string(const char *input, size_t len)
{
    SHA256Context ctx;
    uint8_t hash[32];
    static const char hex_chars[] = "0123456789abcdef";
    char *output_hex = (char *)malloc(65);
    size_t i;
    if (!output_hex) return NULL;
    sha256_init(&ctx);
    sha256_update(&ctx, (const uint8_t *)input, len);
    sha256_final(&ctx, hash);
    for (i = 0; i < 32; ++i) {
        output_hex[i * 2]     = hex_chars[(hash[i] >> 4) & 0x0f];
        output_hex[i * 2 + 1] = hex_chars[hash[i] & 0x0f];
    }
    output_hex[64] = '\0';
    return output_hex;
}

/* --- Base64 Implementation --- */
static const char b64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *base64_encode_str(const unsigned char *data, size_t input_length, size_t *output_length)
{
    size_t out_len = 4 * ((input_length + 2) / 3);
    char *encoded_data = (char *)malloc(out_len + 1);
    size_t i, j;
    if (encoded_data == NULL) return NULL;
    for (i = 0, j = 0; i < input_length;) {
        int has_b = (i + 1 < input_length);
        int has_c = (i + 2 < input_length);
        uint32_t octet_a = (unsigned char)data[i++];
        uint32_t octet_b = has_b ? (unsigned char)data[i++] : 0;
        uint32_t octet_c = has_c ? (unsigned char)data[i++] : 0;
        uint32_t triple = (octet_a << 16) + (octet_b << 8) + octet_c;
        encoded_data[j++] = b64_table[(triple >> 18) & 0x3F];
        encoded_data[j++] = b64_table[(triple >> 12) & 0x3F];
        encoded_data[j++] = has_b ? b64_table[(triple >> 6) & 0x3F] : '=';
        encoded_data[j++] = has_c ? b64_table[triple & 0x3F] : '=';
    }
    encoded_data[out_len] = '\0';
    if (output_length) *output_length = out_len;
    return encoded_data;
}

static int b64_char_val(char c)
{
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static char *base64_decode_str(const char *data, size_t input_length, size_t *output_length)
{
    size_t i, j = 0;
    size_t pad = 0;
    size_t valid_len = 0;
    for (i = 0; i < input_length; i++) {
        if (data[i] == '=') pad++;
        else if (b64_char_val(data[i]) >= 0) valid_len++;
    }
    size_t total_chars = valid_len + pad;
    if (total_chars == 0 || (total_chars % 4) != 0) return NULL;
    size_t out_len = (total_chars / 4) * 3 - pad;
    char *decoded_data = (char *)malloc(out_len + 1);
    if (!decoded_data) return NULL;
    for (i = 0; i < input_length;) {
        int v[4] = {-1, -1, -1, -1};
        int count = 0;
        while (i < input_length && count < 4) {
            char c = data[i++];
            if (c == '=') { v[count++] = 0; }
            else {
                int val = b64_char_val(c);
                if (val >= 0) v[count++] = val;
            }
        }
        if (count == 4) {
            uint32_t triple = (v[0] << 18) + (v[1] << 12) + (v[2] << 6) + v[3];
            if (j < out_len) decoded_data[j++] = (char)((triple >> 16) & 0xFF);
            if (j < out_len) decoded_data[j++] = (char)((triple >> 8) & 0xFF);
            if (j < out_len) decoded_data[j++] = (char)(triple & 0xFF);
        }
    }
    decoded_data[out_len] = '\0';
    if (output_length) *output_length = out_len;
    return decoded_data;
}

/* --- Levenshtein Distance --- */
static size_t calc_levenshtein(const char *s1, size_t len1, const char *s2, size_t len2)
{
    size_t *d;
    size_t i, j;
    if (len1 == 0) return len2;
    if (len2 == 0) return len1;
    d = (size_t *)malloc((len2 + 1) * sizeof(size_t));
    if (!d) return 0;
    for (j = 0; j <= len2; j++) d[j] = j;
    for (i = 1; i <= len1; i++) {
        size_t prev = d[0];
        d[0] = i;
        for (j = 1; j <= len2; j++) {
            size_t temp = d[j];
            size_t cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            size_t min = d[j] + 1;
            if (d[j - 1] + 1 < min) min = d[j - 1] + 1;
            if (prev + cost < min) min = prev + cost;
            d[j] = min;
            prev = temp;
        }
    }
    size_t result = d[len2];
    free(d);
    return result;
}

/* --- Wildcard Pattern Matcher --- */
static int wildcard_match(const char *pat, const char *str)
{
    while (*pat) {
        if (*pat == '*') {
            while (*(pat + 1) == '*') pat++;
            if (*(pat + 1) == '\0') return 1;
            while (*str) {
                if (wildcard_match(pat + 1, str)) return 1;
                str++;
            }
            return wildcard_match(pat + 1, str);
        } else if (*pat == '?' || *pat == *str) {
            if (*str == '\0') return 0;
            pat++;
            str++;
        } else {
            return 0;
        }
    }
    return *str == '\0';
}

/* --- Global Substring Replacement --- */
static char *string_replace_all(const char *src, const char *target, const char *replacement)
{
    size_t src_len = strlen(src);
    size_t tgt_len = strlen(target);
    size_t rep_len = strlen(replacement);
    StringBuffer sb;
    sb_init(&sb);
    if (tgt_len == 0) {
        sb_append(&sb, src, src_len);
        return sb.data;
    }
    const char *p = src;
    while (*p) {
        const char *found = strstr(p, target);
        if (!found) {
            sb_append(&sb, p, strlen(p));
            break;
        }
        sb_append(&sb, p, (size_t)(found - p));
        sb_append(&sb, replacement, rep_len);
        p = found + tgt_len;
    }
    return sb.data;
}

/* --- Title Case & Capitalize First --- */
static char *string_to_title_case(const char *src, size_t len)
{
    char *out = (char *)malloc(len + 1);
    if (!out) return NULL;
    int capitalize_next = 1;
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)src[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '_' || c == '-') {
            out[i] = (char)c;
            capitalize_next = 1;
        } else if (capitalize_next && c >= 'a' && c <= 'z') {
            out[i] = (char)(c - 'a' + 'A');
            capitalize_next = 0;
        } else if (!capitalize_next && c >= 'A' && c <= 'Z') {
            out[i] = (char)(c - 'A' + 'a');
        } else {
            out[i] = (char)c;
            capitalize_next = 0;
        }
    }
    out[len] = '\0';
    return out;
}

static char *string_capitalize_first(const char *src, size_t len)
{
    char *out = (char *)malloc(len + 1);
    if (!out) return NULL;
    memcpy(out, src, len);
    out[len] = '\0';
    if (len > 0 && out[0] >= 'a' && out[0] <= 'z') {
        out[0] = (char)(out[0] - 'a' + 'A');
    }
    return out;
}

/* --- Radix Conversions --- */
static char *int_to_bin_string(long long num)
{
    char buf[66];
    int pos = 0;
    unsigned long long n;
    int is_neg = 0;
    if (num == 0) return copy_string("0");
    if (num < 0) { is_neg = 1; n = (unsigned long long)(-num); }
    else n = (unsigned long long)num;
    while (n > 0) {
        buf[pos++] = (n & 1) ? '1' : '0';
        n >>= 1;
    }
    if (is_neg) buf[pos++] = '-';
    buf[pos] = '\0';
    for (int l = 0, r = pos - 1; l < r; l++, r--) {
        char tmp = buf[l]; buf[l] = buf[r]; buf[r] = tmp;
    }
    return copy_string(buf);
}

static char *int_to_hex_string(long long num)
{
    char buf[32];
    if (num < 0) {
        snprintf(buf, sizeof(buf), "-%llx", (unsigned long long)(-num));
    } else {
        snprintf(buf, sizeof(buf), "%llx", (unsigned long long)num);
    }
    return copy_string(buf);
}

/* --- Directory / Folder Helpers --- */
#ifdef _WIN32
static int platform_folder_exists(const char *path)
{
    DWORD attrs = GetFileAttributesA(path);
    return (attrs != INVALID_FILE_ATTRIBUTES && (attrs & FILE_ATTRIBUTE_DIRECTORY)) ? 1 : 0;
}

static int platform_folder_create(const char *path)
{
    if (CreateDirectoryA(path, NULL)) return 1;
    return GetLastError() == ERROR_ALREADY_EXISTS ? 1 : 0;
}

static List *platform_folder_list(Parser *parser, Token name, const char *path)
{
    char search_path[MAX_PATH];
    WIN32_FIND_DATAA fd;
    HANDLE hFind;
    List *list = create_list(parser, name);
    if (!list) return NULL;
    snprintf(search_path, sizeof(search_path), "%s\\*", path);
    hFind = FindFirstFileA(search_path, &fd);
    if (hFind == INVALID_HANDLE_VALUE) return list;
    do {
        if (strcmp(fd.cFileName, ".") != 0 && strcmp(fd.cFileName, "..") != 0) {
            char *fname = copy_string(fd.cFileName);
            if (fname) {
                Value val = make_owned_string_value(parser, name, fname, strlen(fname));
                append_list_item(parser, list, val, name);
            }
        }
    } while (FindNextFileA(hFind, &fd));
    FindClose(hFind);
    return list;
}
#else
static int platform_folder_exists(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) return 1;
    return 0;
}

static int platform_folder_create(const char *path)
{
    if (mkdir(path, 0777) == 0) return 1;
    return errno == EEXIST ? 1 : 0;
}

static List *platform_folder_list(Parser *parser, Token name, const char *path)
{
    DIR *dir;
    struct dirent *ent;
    List *list = create_list(parser, name);
    if (!list) return NULL;
    dir = opendir(path);
    if (!dir) return list;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") != 0 && strcmp(ent->d_name, "..") != 0) {
            char *fname = copy_string(ent->d_name);
            if (fname) {
                Value val = make_owned_string_value(parser, name, fname, strlen(fname));
                append_list_item(parser, list, val, name);
            }
        }
    }
    closedir(dir);
    return list;
}
#endif

/* --- Matrix Math --- */
static Value matrix_add(Parser *parser, Token name, Value m1, Value m2)
{
    if (m1.kind != VALUE_LIST || m2.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    size_t rows = m1.list->count;
    if (rows != m2.list->count || rows == 0) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    List *res = create_list(parser, name);
    for (size_t r = 0; r < rows; r++) {
        Value row1 = m1.list->items[r];
        Value row2 = m2.list->items[r];
        if (row1.kind != VALUE_LIST || row2.kind != VALUE_LIST || row1.list->count != row2.list->count) {
            report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
            return null_value();
        }
        List *res_row = create_list(parser, name);
        for (size_t c = 0; c < row1.list->count; c++) {
            Value v1 = row1.list->items[c];
            Value v2 = row2.list->items[c];
            if (v1.kind != VALUE_NUMBER || v2.kind != VALUE_NUMBER) {
                report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
                return null_value();
            }
            append_list_item(parser, res_row, number_value(v1.number + v2.number), name);
        }
        Value rv = number_value(0.0);
        rv.kind = VALUE_LIST;
        rv.list = res_row;
        append_list_item(parser, res, rv, name);
    }
    Value v = number_value(0.0);
    v.kind = VALUE_LIST;
    v.list = res;
    return v;
}

static Value matrix_multiply(Parser *parser, Token name, Value m1, Value m2)
{
    if (m1.kind != VALUE_LIST || m2.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    size_t r1 = m1.list->count;
    size_t r2 = m2.list->count;
    if (r1 == 0 || r2 == 0) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    if (m1.list->items[0].kind != VALUE_LIST || m2.list->items[0].kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    size_t c1 = m1.list->items[0].list->count;
    size_t c2 = m2.list->items[0].list->count;
    if (c1 != r2 || c1 == 0 || c2 == 0) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
        return null_value();
    }
    List *res = create_list(parser, name);
    for (size_t i = 0; i < r1; i++) {
        List *row = create_list(parser, name);
        for (size_t j = 0; j < c2; j++) {
            double sum = 0.0;
            for (size_t k = 0; k < c1; k++) {
                Value a = m1.list->items[i].list->items[k];
                Value b = m2.list->items[k].list->items[j];
                if (a.kind != VALUE_NUMBER || b.kind != VALUE_NUMBER) {
                    report_error(parser, name.line, name.column, MESSAGE_EXPECTED_MATRIX_LISTS);
                    return null_value();
                }
                sum += a.number * b.number;
            }
            append_list_item(parser, row, number_value(sum), name);
        }
        Value rv = number_value(0.0);
        rv.kind = VALUE_LIST;
        rv.list = row;
        append_list_item(parser, res, rv, name);
    }
    Value v = number_value(0.0);
    v.kind = VALUE_LIST;
    v.list = res;
    return v;
}

/* --- String Formatting Template --- */
static char *format_template(Parser *parser, const char *fmt, size_t fmt_len, const Value *args, size_t arg_count, size_t *out_len)
{
    StringBuffer sb;
    sb_init(&sb);
    size_t auto_idx = 1;
    size_t i = 0;
    while (i < fmt_len) {
        if (fmt[i] == '{') {
            if (i + 1 < fmt_len && fmt[i + 1] == '{') {
                sb_append(&sb, "{", 1);
                i += 2;
                continue;
            }
            size_t close = i + 1;
            while (close < fmt_len && fmt[close] != '}') close++;
            if (close < fmt_len) {
                size_t target_idx = 0;
                if (close == i + 1) {
                    target_idx = auto_idx++;
                } else {
                    target_idx = (size_t)strtoul(fmt + i + 1, NULL, 10) + 1;
                }
                if (target_idx < arg_count) {
                    List *ancestors[256];
                    format_value_to_buffer(parser, args[target_idx], &sb, ancestors, 0);
                }
                i = close + 1;
                continue;
            }
        }
        sb_append(&sb, &fmt[i], 1);
        i++;
    }
    *out_len = sb.length;
    return sb.data;
}

/* --- JSON Formatting & Parsing --- */
static void json_format_value(Parser *parser, Value value, StringBuffer *sb, List **ancestors, size_t depth)
{
    if (sb->failed) return;
    if (value.kind == VALUE_NULL) {
        sb_append(sb, "null", 4);
    } else if (value.kind == VALUE_NUMBER) {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", value.number);
        sb_append(sb, buf, strlen(buf));
    } else if (value.kind == VALUE_STRING) {
        sb_append(sb, "\"", 1);
        char *str = value_to_c_string(parser, value);
        if (str) {
            for (size_t i = 0; str[i] != '\0'; i++) {
                unsigned char c = (unsigned char)str[i];
                if (c == '"') sb_append(sb, "\\\"", 2);
                else if (c == '\\') sb_append(sb, "\\\\", 2);
                else if (c == '\n') sb_append(sb, "\\n", 2);
                else if (c == '\r') sb_append(sb, "\\r", 2);
                else if (c == '\t') sb_append(sb, "\\t", 2);
                else sb_append(sb, (const char *)&c, 1);
            }
            free(str);
        }
        sb_append(sb, "\"", 1);
    } else if (value.kind == VALUE_LIST) {
        if (depth >= 128) { sb_append(sb, "[]", 2); return; }
        for (size_t i = 0; i < depth; i++) {
            if (ancestors[i] == value.list) { sb_append(sb, "[]", 2); return; }
        }
        ancestors[depth] = value.list;
        sb_append(sb, "[", 1);
        for (size_t i = 0; i < value.list->count; i++) {
            if (i > 0) sb_append(sb, ", ", 2);
            json_format_value(parser, value.list->items[i], sb, ancestors, depth + 1);
        }
        sb_append(sb, "]", 1);
    } else if (value.kind == VALUE_DICT) {
        if (depth >= 128) { sb_append(sb, "{}", 2); return; }
        sb_append(sb, "{", 1);
        for (size_t i = 0; i < value.dict->count; i++) {
            if (i > 0) sb_append(sb, ", ", 2);
            sb_append(sb, "\"", 1);
            sb_append(sb, value.dict->entries[i].key, value.dict->entries[i].key_length);
            sb_append(sb, "\": ", 3);
            json_format_value(parser, value.dict->entries[i].value, sb, ancestors, depth + 1);
        }
        sb_append(sb, "}", 1);
    }
}

static void skip_json_whitespace(const char **p)
{
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') {
        (*p)++;
    }
}

static Value parse_json_value(Parser *parser, Token token, const char **p, int *err)
{
    skip_json_whitespace(p);
    if (**p == '\0') {
        *err = 1;
        return null_value();
    }
    if (**p == 'n' && strncmp(*p, "null", 4) == 0) {
        *p += 4;
        return null_value();
    }
    if (**p == 't' && strncmp(*p, "true", 4) == 0) {
        *p += 4;
        return number_value(1.0);
    }
    if (**p == 'f' && strncmp(*p, "false", 5) == 0) {
        *p += 5;
        return number_value(0.0);
    }
    if (**p == '"') {
        (*p)++;
        StringBuffer sb;
        sb_init(&sb);
        while (**p != '\0' && **p != '"') {
            if (**p == '\\') {
                (*p)++;
                if (**p == '"') sb_append(&sb, "\"", 1);
                else if (**p == '\\') sb_append(&sb, "\\", 1);
                else if (**p == '/') sb_append(&sb, "/", 1);
                else if (**p == 'b') sb_append(&sb, "\b", 1);
                else if (**p == 'f') sb_append(&sb, "\f", 1);
                else if (**p == 'n') sb_append(&sb, "\n", 1);
                else if (**p == 'r') sb_append(&sb, "\r", 1);
                else if (**p == 't') sb_append(&sb, "\t", 1);
                else if (**p != '\0') sb_append(&sb, *p, 1);
                if (**p != '\0') (*p)++;
            } else {
                sb_append(&sb, *p, 1);
                (*p)++;
            }
        }
        if (**p == '"') (*p)++;
        else { *err = 1; sb_free(&sb); return null_value(); }
        return make_owned_string_value(parser, token, sb.data, sb.length);
    }
    if (**p == '[') {
        (*p)++;
        List *list = create_list(parser, token);
        skip_json_whitespace(p);
        if (**p == ']') {
            (*p)++;
            Value v = number_value(0.0);
            v.kind = VALUE_LIST;
            v.list = list;
            return v;
        }
        while (**p != '\0') {
            Value item = parse_json_value(parser, token, p, err);
            if (*err) return null_value();
            append_list_item(parser, list, item, token);
            skip_json_whitespace(p);
            if (**p == ',') {
                (*p)++;
                skip_json_whitespace(p);
            } else if (**p == ']') {
                (*p)++;
                break;
            } else {
                *err = 1;
                return null_value();
            }
        }
        Value v = number_value(0.0);
        v.kind = VALUE_LIST;
        v.list = list;
        return v;
    }
    if (**p == '{') {
        (*p)++;
        Dict *dict = create_dict(parser, token);
        skip_json_whitespace(p);
        if (**p == '}') {
            (*p)++;
            Value v = number_value(0.0);
            v.kind = VALUE_DICT;
            v.dict = dict;
            return v;
        }
        while (**p != '\0') {
            skip_json_whitespace(p);
            if (**p != '"') { *err = 1; return null_value(); }
            (*p)++;
            StringBuffer key_sb;
            sb_init(&key_sb);
            while (**p != '\0' && **p != '"') {
                if (**p == '\\') {
                    (*p)++;
                    if (**p == '"') sb_append(&key_sb, "\"", 1);
                    else if (**p == '\\') sb_append(&key_sb, "\\", 1);
                    else if (**p != '\0') sb_append(&key_sb, *p, 1);
                    if (**p != '\0') (*p)++;
                } else {
                    sb_append(&key_sb, *p, 1);
                    (*p)++;
                }
            }
            if (**p == '"') (*p)++;
            else { *err = 1; sb_free(&key_sb); return null_value(); }
            skip_json_whitespace(p);
            if (**p != ':') { *err = 1; sb_free(&key_sb); return null_value(); }
            (*p)++;
            skip_json_whitespace(p);
            Value val = parse_json_value(parser, token, p, err);
            if (*err) { sb_free(&key_sb); return null_value(); }
            dict_set(parser, dict, key_sb.data, key_sb.length, val, token);
            sb_free(&key_sb);
            skip_json_whitespace(p);
            if (**p == ',') {
                (*p)++;
                skip_json_whitespace(p);
            } else if (**p == '}') {
                (*p)++;
                break;
            } else {
                *err = 1;
                return null_value();
            }
        }
        Value v = number_value(0.0);
        v.kind = VALUE_DICT;
        v.dict = dict;
        return v;
    }
    if (**p == '-' || (**p >= '0' && **p <= '9')) {
        char *endptr;
        double d = strtod(*p, &endptr);
        if (endptr == *p) { *err = 1; return null_value(); }
        *p = endptr;
        return number_value(d);
    }
    *err = 1;
    return null_value();
}

static Function *resolve_callee_function(Parser *parser, Value func_val)
{
    if (func_val.kind != VALUE_STRING) return NULL;
    char *fn_name = value_to_c_string(parser, func_val);
    if (!fn_name) return NULL;
    Function *fn = find_function_by_name(parser, fn_name, strlen(fn_name));
    free(fn_name);
    return fn;
}

static char *generate_uuid_v4(void)
{
    char *uuid = (char *)malloc(37);
    if (!uuid) return NULL;
    unsigned char b[16];
    for (int i = 0; i < 16; i++) {
        b[i] = (unsigned char)(rand() & 0xFF);
    }
    b[6] = (b[6] & 0x0F) | 0x40;
    b[8] = (b[8] & 0x3F) | 0x80;
    sprintf(uuid, "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7],
            b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15]);
    return uuid;
}

static char *url_encode(const char *src, size_t len)
{
    StringBuffer sb;
    sb_init(&sb);
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)src[i];
        if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
            sb_append(&sb, (const char *)&c, 1);
        } else {
            char hex[4];
            sprintf(hex, "%%%02X", c);
            sb_append(&sb, hex, 3);
        }
    }
    return sb.data;
}

static char *url_decode(const char *src, size_t len)
{
    StringBuffer sb;
    sb_init(&sb);
    size_t i = 0;
    while (i < len) {
        if (src[i] == '+') {
            sb_append(&sb, " ", 1);
            i++;
        } else if (src[i] == '%' && i + 2 < len && isxdigit((unsigned char)src[i + 1]) && isxdigit((unsigned char)src[i + 2])) {
            char hex[3] = { src[i + 1], src[i + 2], '\0' };
            unsigned int c = 0;
            sscanf(hex, "%x", &c);
            unsigned char ch = (unsigned char)c;
            sb_append(&sb, (const char *)&ch, 1);
            i += 3;
        } else {
            sb_append(&sb, &src[i], 1);
            i++;
        }
    }
    return sb.data;
}

static int compare_doubles_asc(const void *a, const void *b)
{
    double da = *(const double *)a;
    double db = *(const double *)b;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

static char *path_join(const char *a, size_t a_len, const char *b, size_t b_len)
{
    while (a_len > 0 && (a[a_len - 1] == '/' || a[a_len - 1] == '\\')) a_len--;
    while (b_len > 0 && (*b == '/' || *b == '\\')) { b++; b_len--; }
    char *res = (char *)malloc(a_len + b_len + 2);
    if (!res) return NULL;
    memcpy(res, a, a_len);
    res[a_len] = '/';
    memcpy(res + a_len + 1, b, b_len);
    res[a_len + 1 + b_len] = '\0';
    return res;
}

static const char *path_extension(const char *path, size_t len)
{
    for (size_t i = len; i > 0; i--) {
        char c = path[i - 1];
        if (c == '/' || c == '\\') break;
        if (c == '.') return &path[i - 1];
    }
    return "";
}

static const char *path_basename(const char *path, size_t len)
{
    for (size_t i = len; i > 0; i--) {
        char c = path[i - 1];
        if (c == '/' || c == '\\') return &path[i];
    }
    return path;
}

static char *path_dirname(const char *path, size_t len)
{
    for (size_t i = len; i > 0; i--) {
        char c = path[i - 1];
        if (c == '/' || c == '\\') {
            size_t dlen = i - 1;
            if (dlen == 0) dlen = 1;
            char *d = (char *)malloc(dlen + 1);
            if (!d) return NULL;
            memcpy(d, path, dlen);
            d[dlen] = '\0';
            return d;
        }
    }
    return copy_string(".");
}

static char *string_repeat(const char *src, size_t src_len, size_t count, size_t *out_len)
{
    if (count == 0 || src_len == 0) {
        char *r = copy_string("");
        if (out_len) *out_len = 0;
        return r;
    }
    size_t total = src_len * count;
    char *res = (char *)malloc(total + 1);
    if (!res) return NULL;
    for (size_t i = 0; i < count; i++) {
        memcpy(res + i * src_len, src, src_len);
    }
    res[total] = '\0';
    if (out_len) *out_len = total;
    return res;
}

static size_t string_count_substring(const char *src, size_t src_len, const char *sub, size_t sub_len)
{
    if (sub_len == 0 || src_len < sub_len) return 0;
    size_t count = 0;
    const char *p = src;
    const char *end = src + src_len - sub_len + 1;
    while (p < end) {
        if (memcmp(p, sub, sub_len) == 0) {
            count++;
            p += sub_len;
        } else {
            p++;
        }
    }
    return count;
}

static char *pad_string(const char *src, size_t src_len, size_t target_len, char pad_char, int is_left, size_t *out_len)
{
    if (src_len >= target_len) {
        char *res = (char *)malloc(src_len + 1);
        if (!res) return NULL;
        memcpy(res, src, src_len);
        res[src_len] = '\0';
        if (out_len) *out_len = src_len;
        return res;
    }
    char *res = (char *)malloc(target_len + 1);
    if (!res) return NULL;
    size_t pad_amount = target_len - src_len;
    if (is_left) {
        memset(res, pad_char, pad_amount);
        memcpy(res + pad_amount, src, src_len);
    } else {
        memcpy(res, src, src_len);
        memset(res + src_len, pad_char, pad_amount);
    }
    res[target_len] = '\0';
    if (out_len) *out_len = target_len;
    return res;
}

static char *hex_to_string(const char *hex, size_t len, size_t *out_len)
{
    if (len % 2 != 0) return NULL;
    size_t result_len = len / 2;
    char *out = (char *)malloc(result_len + 1);
    if (!out) return NULL;
    for (size_t i = 0; i < result_len; i++) {
        char buf[3] = { hex[i * 2], hex[i * 2 + 1], '\0' };
        if (!isxdigit((unsigned char)buf[0]) || !isxdigit((unsigned char)buf[1])) {
            free(out);
            return NULL;
        }
        unsigned int byte_val = 0;
        sscanf(buf, "%x", &byte_val);
        out[i] = (char)byte_val;
    }
    out[result_len] = '\0';
    if (out_len) *out_len = result_len;
    return out;
}

static Value read_file_lines(Parser *parser, Token name, const char *path)
{
    FILE *f = fopen(path, "rb");
    if (!f) return null_value();
    List *list = create_list(parser, name);
    StringBuffer line;
    sb_init(&line);
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\r') {
            int next = fgetc(f);
            if (next != '\n' && next != EOF) ungetc(next, f);
            Value lv = make_owned_string_value(parser, name, line.data ? line.data : copy_string(""), line.length);
            append_list_item(parser, list, lv, name);
            sb_init(&line);
        } else if (c == '\n') {
            Value lv = make_owned_string_value(parser, name, line.data ? line.data : copy_string(""), line.length);
            append_list_item(parser, list, lv, name);
            sb_init(&line);
        } else {
            char ch = (char)c;
            sb_append(&line, &ch, 1);
        }
    }
    if (line.length > 0) {
        Value lv = make_owned_string_value(parser, name, line.data ? line.data : copy_string(""), line.length);
        append_list_item(parser, list, lv, name);
    } else {
        sb_free(&line);
    }
    fclose(f);
    Value res = number_value(0.0);
    res.kind = VALUE_LIST;
    res.list = list;
    return res;
}

static Value parse_csv_string(Parser *parser, Token name, const char *csv, size_t len)
{
    List *rows = create_list(parser, name);
    size_t i = 0;
    while (i < len) {
        if (csv[i] == '\r' || csv[i] == '\n') {
            i++;
            continue;
        }
        List *row = create_list(parser, name);
        while (i < len && csv[i] != '\r' && csv[i] != '\n') {
            StringBuffer field;
            sb_init(&field);
            if (csv[i] == '"') {
                i++;
                while (i < len) {
                    if (csv[i] == '"') {
                        if (i + 1 < len && csv[i + 1] == '"') {
                            sb_append(&field, "\"", 1);
                            i += 2;
                        } else {
                            i++;
                            break;
                        }
                    } else {
                        sb_append(&field, &csv[i], 1);
                        i++;
                    }
                }
                while (i < len && csv[i] != ',' && csv[i] != '\r' && csv[i] != '\n') {
                    i++;
                }
            } else {
                while (i < len && csv[i] != ',' && csv[i] != '\r' && csv[i] != '\n') {
                    sb_append(&field, &csv[i], 1);
                    i++;
                }
            }
            Value col_val = make_owned_string_value(parser, name, field.data ? field.data : copy_string(""), field.length);
            append_list_item(parser, row, col_val, name);
            if (i < len && csv[i] == ',') {
                i++;
                if (i == len || csv[i] == '\r' || csv[i] == '\n') {
                    Value empty_val = make_owned_string_value(parser, name, copy_string(""), 0);
                    append_list_item(parser, row, empty_val, name);
                }
            }
        }
        Value row_val = number_value(0.0);
        row_val.kind = VALUE_LIST;
        row_val.list = row;
        append_list_item(parser, rows, row_val, name);
        if (i < len && csv[i] == '\r') i++;
        if (i < len && csv[i] == '\n') i++;
    }
    Value result = number_value(0.0);
    result.kind = VALUE_LIST;
    result.list = rows;
    return result;
}

/* --- v1.1.0 Helper Functions: Process, INI, Env, HTTP, Vectors, ML, Search --- */

static char *run_curl_command(const char *cmd)
{
#if defined(_WIN32)
    FILE *fp = _popen(cmd, "rb");
#else
    FILE *fp = popen(cmd, "r");
#endif
    if (!fp) return NULL;
    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
#if defined(_WIN32)
        _pclose(fp);
#else
        pclose(fp);
#endif
        return NULL;
    }
    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (len + 1024 >= cap) {
            cap *= 2;
            char *new_buf = (char *)realloc(buf, cap);
            if (!new_buf) { break; }
            buf = new_buf;
        }
    }
    buf[len] = '\0';
#if defined(_WIN32)
    _pclose(fp);
#else
    pclose(fp);
#endif
    return buf;
}

static char *expand_env_string(const char *src, size_t len)
{
    StringBuffer sb;
    sb_init(&sb);
    size_t i = 0;
    while (i < len) {
        if (src[i] == '$') {
            i++;
            if (i < len && src[i] == '{') {
                i++;
                size_t start = i;
                while (i < len && src[i] != '}') i++;
                size_t var_len = i - start;
                char var_name[256];
                if (var_len < sizeof(var_name)) {
                    memcpy(var_name, src + start, var_len);
                    var_name[var_len] = '\0';
                    const char *val = getenv(var_name);
                    if (val) sb_append(&sb, val, strlen(val));
                }
                if (i < len && src[i] == '}') i++;
            } else {
                size_t start = i;
                while (i < len && (isalnum((unsigned char)src[i]) || src[i] == '_')) i++;
                size_t var_len = i - start;
                char var_name[256];
                if (var_len > 0 && var_len < sizeof(var_name)) {
                    memcpy(var_name, src + start, var_len);
                    var_name[var_len] = '\0';
                    const char *val = getenv(var_name);
                    if (val) sb_append(&sb, val, strlen(val));
                }
            }
        } else {
            sb_append(&sb, &src[i], 1);
            i++;
        }
    }
    return sb.data ? sb.data : copy_string("");
}

static Value ini_parse_string(Parser *parser, Token token, const char *ini, size_t len)
{
    Dict *root = create_dict(parser, token);
    Dict *current_section = root;
    size_t i = 0;
    while (i < len) {
        while (i < len && (ini[i] == ' ' || ini[i] == '\t')) i++;
        if (i >= len) break;
        if (ini[i] == '\r' || ini[i] == '\n') {
            i++;
            continue;
        }
        if (ini[i] == ';' || ini[i] == '#') {
            while (i < len && ini[i] != '\r' && ini[i] != '\n') i++;
            continue;
        }
        if (ini[i] == '[') {
            i++;
            size_t sec_start = i;
            while (i < len && ini[i] != ']' && ini[i] != '\r' && ini[i] != '\n') i++;
            size_t sec_len = i - sec_start;
            while (sec_len > 0 && (ini[sec_start + sec_len - 1] == ' ' || ini[sec_start + sec_len - 1] == '\t')) sec_len--;
            if (i < len && ini[i] == ']') i++;
            while (i < len && ini[i] != '\r' && ini[i] != '\n') i++;

            char sec_name[256];
            if (sec_len >= sizeof(sec_name)) sec_len = sizeof(sec_name) - 1;
            memcpy(sec_name, ini + sec_start, sec_len);
            sec_name[sec_len] = '\0';

            Dict *sec_dict = create_dict(parser, token);
            Value sec_val = number_value(0.0);
            sec_val.kind = VALUE_DICT;
            sec_val.dict = sec_dict;
            dict_set(parser, root, sec_name, sec_len, sec_val, token);
            current_section = sec_dict;
            continue;
        }
        size_t key_start = i;
        while (i < len && ini[i] != '=' && ini[i] != ':' && ini[i] != '\r' && ini[i] != '\n') i++;
        if (i >= len || ini[i] == '\r' || ini[i] == '\n') {
            continue;
        }
        size_t key_len = i - key_start;
        while (key_len > 0 && (ini[key_start + key_len - 1] == ' ' || ini[key_start + key_len - 1] == '\t')) key_len--;
        i++;
        while (i < len && (ini[i] == ' ' || ini[i] == '\t')) i++;
        size_t val_start = i;
        while (i < len && ini[i] != '\r' && ini[i] != '\n') i++;
        size_t val_len = i - val_start;
        while (val_len > 0 && (ini[val_start + val_len - 1] == ' ' || ini[val_start + val_len - 1] == '\t')) val_len--;

        if (val_len >= 2 && ((ini[val_start] == '"' && ini[val_start + val_len - 1] == '"') ||
                             (ini[val_start] == '\'' && ini[val_start + val_len - 1] == '\''))) {
            val_start++;
            val_len -= 2;
        }

        char key_name[256];
        if (key_len >= sizeof(key_name)) key_len = sizeof(key_name) - 1;
        memcpy(key_name, ini + key_start, key_len);
        key_name[key_len] = '\0';

        char *val_str = (char *)malloc(val_len + 1);
        if (val_str) {
            memcpy(val_str, ini + val_start, val_len);
            val_str[val_len] = '\0';
            Value v = make_owned_string_value(parser, token, val_str, val_len);
            dict_set(parser, current_section, key_name, key_len, v, token);
        }
    }
    Value res = number_value(0.0);
    res.kind = VALUE_DICT;
    res.dict = root;
    return res;
}

static double vector_dot_product(const List *a, const List *b)
{
    double sum = 0.0;
    size_t n = a->count < b->count ? a->count : b->count;
    for (size_t i = 0; i < n; i++) {
        if (a->items[i].kind == VALUE_NUMBER && b->items[i].kind == VALUE_NUMBER) {
            sum += a->items[i].number * b->items[i].number;
        }
    }
    return sum;
}

static double vector_norm(const List *a)
{
    double sum = 0.0;
    for (size_t i = 0; i < a->count; i++) {
        if (a->items[i].kind == VALUE_NUMBER) {
            sum += a->items[i].number * a->items[i].number;
        }
    }
    return sqrt(sum);
}

static double vector_cosine_similarity(const List *a, const List *b)
{
    double dot = vector_dot_product(a, b);
    double na = vector_norm(a);
    double nb = vector_norm(b);
    if (na == 0.0 || nb == 0.0) return 0.0;
    return dot / (na * nb);
}

static double vector_euclidean_distance(const List *a, const List *b)
{
    double sum = 0.0;
    size_t n = a->count < b->count ? a->count : b->count;
    for (size_t i = 0; i < n; i++) {
        if (a->items[i].kind == VALUE_NUMBER && b->items[i].kind == VALUE_NUMBER) {
            double diff = a->items[i].number - b->items[i].number;
            sum += diff * diff;
        }
    }
    return sqrt(sum);
}

static Value ml_linear_regression(Parser *parser, Token token, const List *x, const List *y)
{
    size_t n = x->count < y->count ? x->count : y->count;
    if (n < 2) {
        return null_value();
    }
    double sum_x = 0.0, sum_y = 0.0;
    for (size_t i = 0; i < n; i++) {
        sum_x += x->items[i].number;
        sum_y += y->items[i].number;
    }
    double mean_x = sum_x / (double)n;
    double mean_y = sum_y / (double)n;
    double num = 0.0, den = 0.0;
    for (size_t i = 0; i < n; i++) {
        double dx = x->items[i].number - mean_x;
        double dy = y->items[i].number - mean_y;
        num += dx * dy;
        den += dx * dx;
    }
    double slope = den != 0.0 ? num / den : 0.0;
    double intercept = mean_y - slope * mean_x;

    double ss_res = 0.0, ss_tot = 0.0;
    for (size_t i = 0; i < n; i++) {
        double y_pred = slope * x->items[i].number + intercept;
        double res = y->items[i].number - y_pred;
        double tot = y->items[i].number - mean_y;
        ss_res += res * res;
        ss_tot += tot * tot;
    }
    double r2 = ss_tot != 0.0 ? (1.0 - (ss_res / ss_tot)) : 1.0;

    Dict *d = create_dict(parser, token);
    dict_set(parser, d, "dhal", 4, number_value(slope), token);
    dict_set(parser, d, "slope", 5, number_value(slope), token);
    dict_set(parser, d, "antarched", 9, number_value(intercept), token);
    dict_set(parser, d, "intercept", 9, number_value(intercept), token);
    dict_set(parser, d, "r2", 2, number_value(r2), token);

    Value res = number_value(0.0);
    res.kind = VALUE_DICT;
    res.dict = d;
    return res;
}

static Value ml_kmeans_clustering(Parser *parser, Token token, const List *data, size_t k, size_t max_iters)
{
    if (data->count == 0 || k == 0) return null_value();
    if (k > data->count) k = data->count;
    if (max_iters == 0) max_iters = 50;

    size_t n = data->count;
    int is_multidim = (data->items[0].kind == VALUE_LIST);
    size_t dim = is_multidim ? data->items[0].list->count : 1;

    double *centroids = (double *)calloc(k * dim, sizeof(double));
    int *cluster_assignments = (int *)calloc(n, sizeof(int));
    if (!centroids || !cluster_assignments) {
        free(centroids); free(cluster_assignments);
        return null_value();
    }

    for (size_t c = 0; c < k; c++) {
        size_t pt_idx = (c * n) / k;
        if (is_multidim) {
            List *pt = data->items[pt_idx].list;
            for (size_t d = 0; d < dim; d++) {
                centroids[c * dim + d] = (d < pt->count && pt->items[d].kind == VALUE_NUMBER) ? pt->items[d].number : 0.0;
            }
        } else {
            centroids[c] = (data->items[pt_idx].kind == VALUE_NUMBER) ? data->items[pt_idx].number : 0.0;
        }
    }

    for (size_t iter = 0; iter < max_iters; iter++) {
        int changed = 0;
        for (size_t i = 0; i < n; i++) {
            double best_dist = 1e30;
            int best_c = 0;
            for (size_t c = 0; c < k; c++) {
                double dist_sq = 0.0;
                if (is_multidim) {
                    List *pt = data->items[i].list;
                    for (size_t d = 0; d < dim; d++) {
                        double val = (d < pt->count && pt->items[d].kind == VALUE_NUMBER) ? pt->items[d].number : 0.0;
                        double diff = val - centroids[c * dim + d];
                        dist_sq += diff * diff;
                    }
                } else {
                    double val = (data->items[i].kind == VALUE_NUMBER) ? data->items[i].number : 0.0;
                    double diff = val - centroids[c];
                    dist_sq += diff * diff;
                }
                if (dist_sq < best_dist) {
                    best_dist = dist_sq;
                    best_c = (int)c;
                }
            }
            if (cluster_assignments[i] != best_c) {
                cluster_assignments[i] = best_c;
                changed = 1;
            }
        }
        if (!changed) break;

        double *new_centroids = (double *)calloc(k * dim, sizeof(double));
        size_t *counts = (size_t *)calloc(k, sizeof(size_t));
        if (new_centroids && counts) {
            for (size_t i = 0; i < n; i++) {
                int c = cluster_assignments[i];
                counts[c]++;
                if (is_multidim) {
                    List *pt = data->items[i].list;
                    for (size_t d = 0; d < dim; d++) {
                        double val = (d < pt->count && pt->items[d].kind == VALUE_NUMBER) ? pt->items[d].number : 0.0;
                        new_centroids[c * dim + d] += val;
                    }
                } else {
                    double val = (data->items[i].kind == VALUE_NUMBER) ? data->items[i].number : 0.0;
                    new_centroids[c] += val;
                }
            }
            for (size_t c = 0; c < k; c++) {
                if (counts[c] > 0) {
                    for (size_t d = 0; d < dim; d++) {
                        centroids[c * dim + d] = new_centroids[c * dim + d] / (double)counts[c];
                    }
                }
            }
            free(new_centroids);
            free(counts);
        }
    }

    List *centroids_list = create_list(parser, token);
    for (size_t c = 0; c < k; c++) {
        if (is_multidim) {
            List *c_pt = create_list(parser, token);
            for (size_t d = 0; d < dim; d++) {
                append_list_item(parser, c_pt, number_value(centroids[c * dim + d]), token);
            }
            Value v = number_value(0.0);
            v.kind = VALUE_LIST;
            v.list = c_pt;
            append_list_item(parser, centroids_list, v, token);
        } else {
            append_list_item(parser, centroids_list, number_value(centroids[c]), token);
        }
    }

    List *clusters_list = create_list(parser, token);
    for (size_t i = 0; i < n; i++) {
        append_list_item(parser, clusters_list, number_value((double)cluster_assignments[i]), token);
    }

    free(centroids);
    free(cluster_assignments);

    Dict *res_dict = create_dict(parser, token);
    Value v_cent = number_value(0.0); v_cent.kind = VALUE_LIST; v_cent.list = centroids_list;
    Value v_clus = number_value(0.0); v_clus.kind = VALUE_LIST; v_clus.list = clusters_list;
    dict_set(parser, res_dict, "centroids", 9, v_cent, token);
    dict_set(parser, res_dict, "clusters", 8, v_clus, token);

    Value result = number_value(0.0);
    result.kind = VALUE_DICT;
    result.dict = res_dict;
    return result;
}

static void format_value_to_sb(Parser *parser, Value value, StringBuffer *sb, List **ancestors, size_t depth)
{
    if (value.kind == VALUE_STRING) {
        if (value.owned_string != NULL) {
            sb_append(sb, value.owned_string, value.string_length);
        } else {
            char *s = value_to_c_string(parser, value);
            if (s) {
                sb_append(sb, s, strlen(s));
                free(s);
            }
        }
    } else if (value.kind == VALUE_NUMBER) {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", value.number);
        sb_append(sb, buf, strlen(buf));
    } else if (value.kind == VALUE_NULL) {
        sb_append(sb, "nakamo", 6);
    } else if (value.kind == VALUE_LIST) {
        if (depth >= 256) { sb_append(sb, "[]", 2); return; }
        for (size_t i = 0; i < depth; i++) {
            if (ancestors[i] == value.list) {
                sb_append(sb, "<cycle>", 7);
                return;
            }
        }
        ancestors[depth] = value.list;
        sb_append(sb, "[", 1);
        for (size_t i = 0; i < value.list->count; i++) {
            if (i > 0) sb_append(sb, ", ", 2);
            format_value_to_sb(parser, value.list->items[i], sb, ancestors, depth + 1);
        }
        sb_append(sb, "]", 1);
    } else if (value.kind == VALUE_DICT) {
        if (depth >= 256) { sb_append(sb, "{}", 2); return; }
        sb_append(sb, "{", 1);
        for (size_t i = 0; i < value.dict->count; i++) {
            if (i > 0) sb_append(sb, ", ", 2);
            sb_append(sb, value.dict->entries[i].key, value.dict->entries[i].key_length);
            sb_append(sb, ": ", 2);
            format_value_to_sb(parser, value.dict->entries[i].value, sb, ancestors, depth + 1);
        }
        sb_append(sb, "}", 1);
    }
}

#ifdef _WIN32
#define STR_ICMP _stricmp
#define STR_NICMP _strnicmp
#else
#define STR_ICMP strcasecmp
#define STR_NICMP strncasecmp
#endif

/* GujaratiLang v1.2.0 Helper Implementations */

/* --- Network & Web Server --- */

static void init_network_if_needed(void)
{
#ifdef _WIN32
    static int initialized = 0;
    if (!initialized) {
        WSADATA wsa;
        WSAStartup(MAKEWORD(2, 2), &wsa);
        initialized = 1;
    }
#endif
}

static Value url_banao_helper(Parser *parser, Token name, Value base_val, Value params_val)
{
    if (base_val.kind != VALUE_STRING || params_val.kind != VALUE_DICT) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *base_str = value_to_c_string(parser, base_val);
    if (!base_str) return null_value();

    StringBuffer sb;
    sb_init(&sb);
    sb_append(&sb, base_str, strlen(base_str));
    free(base_str);

    int has_query = (strchr(sb.data, '?') != NULL);
    Dict *dict = params_val.dict;
    int first = 1;

    for (size_t i = 0; i < dict->count; i++) {
        if (first) {
            if (!has_query) sb_append(&sb, "?", 1);
            else sb_append(&sb, "&", 1);
            first = 0;
        } else {
            sb_append(&sb, "&", 1);
        }
        char *k = url_encode(dict->entries[i].key, dict->entries[i].key_length);
        if (k) {
            sb_append(&sb, k, strlen(k));
            free(k);
        }
        sb_append(&sb, "=", 1);

        char *v_str = NULL;
        if (dict->entries[i].value.kind == VALUE_STRING) {
            v_str = value_to_c_string(parser, dict->entries[i].value);
        } else {
            StringBuffer vsb;
            sb_init(&vsb);
            List *anc[256];
            format_value_to_sb(parser, dict->entries[i].value, &vsb, anc, 0);
            v_str = vsb.data;
        }
        if (v_str) {
            char *enc = url_encode(v_str, strlen(v_str));
            if (enc) {
                sb_append(&sb, enc, strlen(enc));
                free(enc);
            }
            free(v_str);
        }
    }

    if (!sb.failed && sb.data) {
        return make_owned_string_value(parser, name, sb.data, sb.length);
    }
    return make_owned_string_value(parser, name, copy_string(""), 0);
}

static Value web_static_file_helper(Parser *parser, Token name, Value path_val)
{
    if (path_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *path = value_to_c_string(parser, path_val);
    if (!path) return null_value();

    Dict *res_dict = create_dict(parser, name);
    Dict *headers = create_dict(parser, name);

    FILE *fp = fopen(path, "rb");
    if (!fp) {
        free(path);
        dict_set(parser, res_dict, "status", 6, number_value(404), name);
        Value ct = make_owned_string_value(parser, name, copy_string("text/plain"), 10);
        dict_set(parser, headers, "Content-Type", 12, ct, name);
        Value hdrs_val; hdrs_val.kind = VALUE_DICT; hdrs_val.dict = headers;
        dict_set(parser, res_dict, "headers", 7, hdrs_val, name);
        Value body = make_owned_string_value(parser, name, copy_string("404 Not Found"), 13);
        dict_set(parser, res_dict, "body", 4, body, name);
        Value r; r.kind = VALUE_DICT; r.dict = res_dict;
        return r;
    }

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *buf = (char *)malloc(sz + 1);
    if (buf) {
        size_t rd = fread(buf, 1, sz, fp);
        buf[rd] = '\0';
    } else {
        buf = copy_string("");
        sz = 0;
    }
    fclose(fp);

    /* Determine MIME type */
    const char *mime = "text/plain";
    const char *ext = strrchr(path, '.');
    if (ext) {
        if (STR_ICMP(ext, ".html") == 0 || STR_ICMP(ext, ".htm") == 0) mime = "text/html; charset=utf-8";
        else if (STR_ICMP(ext, ".css") == 0) mime = "text/css";
        else if (STR_ICMP(ext, ".js") == 0) mime = "application/javascript";
        else if (STR_ICMP(ext, ".json") == 0) mime = "application/json";
        else if (STR_ICMP(ext, ".png") == 0) mime = "image/png";
        else if (STR_ICMP(ext, ".jpg") == 0 || STR_ICMP(ext, ".jpeg") == 0) mime = "image/jpeg";
        else if (STR_ICMP(ext, ".svg") == 0) mime = "image/svg+xml";
        else if (STR_ICMP(ext, ".ico") == 0) mime = "image/x-icon";
    }
    free(path);

    dict_set(parser, res_dict, "status", 6, number_value(200), name);
    Value ct = make_owned_string_value(parser, name, copy_string(mime), strlen(mime));
    dict_set(parser, headers, "Content-Type", 12, ct, name);
    Value hdrs_val; hdrs_val.kind = VALUE_DICT; hdrs_val.dict = headers;
    dict_set(parser, res_dict, "headers", 7, hdrs_val, name);
    Value body = make_owned_string_value(parser, name, buf, sz);
    dict_set(parser, res_dict, "body", 4, body, name);

    Value r; r.kind = VALUE_DICT; r.dict = res_dict;
    return r;
}

static Value run_micro_web_server(Parser *parser, Token name, Value port_val, Value router_val, Value max_req_val)
{
    if (port_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Function *router_fn = resolve_callee_function(parser, router_val);
    if (!router_fn) {
        report_error(parser, name.line, name.column, MESSAGE_UNDEFINED_FUNCTION);
        return null_value();
    }

    int port = (int)port_val.number;
    int max_req = (max_req_val.kind == VALUE_NUMBER) ? (int)max_req_val.number : 0;

    init_network_if_needed();

    socket_t srv = socket(AF_INET, SOCK_STREAM, 0);
    if (IS_INVALID_SOCKET(srv)) {
        return number_value(-1);
    }

    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, (char *)&opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons((unsigned short)port);

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        CLOSE_SOCKET(srv);
        return number_value(-1);
    }

    if (listen(srv, 16) < 0) {
        CLOSE_SOCKET(srv);
        return number_value(-1);
    }

    int req_count = 0;
    while (!parser->failed) {
        if (max_req > 0 && req_count >= max_req) {
            break;
        }

        socket_t client = accept(srv, NULL, NULL);
        if (IS_INVALID_SOCKET(client)) {
            break;
        }

        char buffer[8192];
        int bytes = recv(client, buffer, sizeof(buffer) - 1, 0);
        if (bytes <= 0) {
            CLOSE_SOCKET(client);
            continue;
        }
        buffer[bytes] = '\0';

        char method[16] = {0};
        char full_path[1024] = {0};
        sscanf(buffer, "%15s %1023s", method, full_path);

        char *qmark = strchr(full_path, '?');
        char raw_path[1024];
        char raw_query[1024] = {0};
        if (qmark) {
            size_t plen = qmark - full_path;
            strncpy(raw_path, full_path, plen);
            raw_path[plen] = '\0';
            strcpy(raw_query, qmark + 1);
        } else {
            strcpy(raw_path, full_path);
        }

        Dict *req_dict = create_dict(parser, name);
        Dict *query_dict = create_dict(parser, name);
        Dict *headers_dict = create_dict(parser, name);

        /* Parse query params */
        if (raw_query[0]) {
            char *p = raw_query;
            while (*p) {
                char *amp = strchr(p, '&');
                size_t pair_len = amp ? (size_t)(amp - p) : strlen(p);
                char pair[512];
                if (pair_len >= sizeof(pair)) pair_len = sizeof(pair) - 1;
                strncpy(pair, p, pair_len);
                pair[pair_len] = '\0';

                char *eq = strchr(pair, '=');
                if (eq) {
                    *eq = '\0';
                    char *k = pair;
                    char *v = eq + 1;
                    char *dec_v = url_decode(v, strlen(v));
                    Value val = make_owned_string_value(parser, name, dec_v ? dec_v : copy_string(""), dec_v ? strlen(dec_v) : 0);
                    dict_set(parser, query_dict, k, strlen(k), val, name);
                } else {
                    Value val = make_owned_string_value(parser, name, copy_string(""), 0);
                    dict_set(parser, query_dict, pair, strlen(pair), val, name);
                }
                if (!amp) break;
                p = amp + 1;
            }
        }

        /* Parse headers */
        char *body_ptr = strstr(buffer, "\r\n\r\n");
        if (body_ptr) body_ptr += 4;
        else {
            body_ptr = strstr(buffer, "\n\n");
            if (body_ptr) body_ptr += 2;
            else body_ptr = buffer + bytes;
        }

        char *line = strstr(buffer, "\r\n");
        if (line) line += 2;
        else {
            line = strchr(buffer, '\n');
            if (line) line += 1;
        }

        while (line && line < body_ptr) {
            char *next_line = strstr(line, "\r\n");
            size_t line_len = next_line ? (size_t)(next_line - line) : strlen(line);
            if (line_len == 0) break;
            char hline[512];
            if (line_len >= sizeof(hline)) line_len = sizeof(hline) - 1;
            strncpy(hline, line, line_len);
            hline[line_len] = '\0';

            char *colon = strchr(hline, ':');
            if (colon) {
                *colon = '\0';
                char *hname = hline;
                char *hval = colon + 1;
                while (*hval == ' ') hval++;
                Value val = make_owned_string_value(parser, name, copy_string(hval), strlen(hval));
                dict_set(parser, headers_dict, hname, strlen(hname), val, name);
            }
            if (!next_line) break;
            line = next_line + 2;
        }

        Value m_val = make_owned_string_value(parser, name, copy_string(method), strlen(method));
        dict_set(parser, req_dict, "method", 6, m_val, name);

        Value p_val = make_owned_string_value(parser, name, copy_string(raw_path), strlen(raw_path));
        dict_set(parser, req_dict, "path", 4, p_val, name);

        Value q_val; q_val.kind = VALUE_DICT; q_val.dict = query_dict;
        dict_set(parser, req_dict, "query", 5, q_val, name);

        Value h_val; h_val.kind = VALUE_DICT; h_val.dict = headers_dict;
        dict_set(parser, req_dict, "headers", 7, h_val, name);

        Value b_val = make_owned_string_value(parser, name, copy_string(body_ptr), strlen(body_ptr));
        dict_set(parser, req_dict, "body", 4, b_val, name);

        Value req_arg; req_arg.kind = VALUE_DICT; req_arg.dict = req_dict;
        Value router_res = call_function(parser, *router_fn, &req_arg);

        int status_code = 200;
        const char *status_msg = "OK";
        const char *content_type = "text/html; charset=utf-8";
        char *resp_body = NULL;
        size_t resp_body_len = 0;
        int need_free_body = 0;

        if (router_res.kind == VALUE_DICT) {
            Value *st = dict_get(router_res.dict, "status", 6);
            if (st && st->kind == VALUE_NUMBER) {
                status_code = (int)st->number;
                if (status_code == 201) status_msg = "Created";
                else if (status_code == 204) status_msg = "No Content";
                else if (status_code == 400) status_msg = "Bad Request";
                else if (status_code == 401) status_msg = "Unauthorized";
                else if (status_code == 403) status_msg = "Forbidden";
                else if (status_code == 404) status_msg = "Not Found";
                else if (status_code == 500) status_msg = "Internal Server Error";
            }
            Value *hd = dict_get(router_res.dict, "headers", 7);
            if (hd && hd->kind == VALUE_DICT) {
                Value *ct = dict_get(hd->dict, "Content-Type", 12);
                if (ct && ct->kind == VALUE_STRING) {
                    char *ct_s = value_to_c_string(parser, *ct);
                    if (ct_s) {
                        content_type = ct_s;
                    }
                }
            }
            Value *bd = dict_get(router_res.dict, "body", 4);
            if (bd) {
                if (bd->kind == VALUE_STRING) {
                    resp_body = value_to_c_string(parser, *bd);
                    resp_body_len = resp_body ? strlen(resp_body) : 0;
                    need_free_body = 1;
                } else {
                    StringBuffer sbb;
                    sb_init(&sbb);
                    List *anc[256];
                    format_value_to_sb(parser, *bd, &sbb, anc, 0);
                    resp_body = sbb.data;
                    resp_body_len = sbb.length;
                    need_free_body = 1;
                }
            }
        } else if (router_res.kind == VALUE_STRING) {
            resp_body = value_to_c_string(parser, router_res);
            resp_body_len = resp_body ? strlen(resp_body) : 0;
            need_free_body = 1;
        } else {
            StringBuffer sbb;
            sb_init(&sbb);
            List *anc[256];
            format_value_to_sb(parser, router_res, &sbb, anc, 0);
            resp_body = sbb.data;
            resp_body_len = sbb.length;
            need_free_body = 1;
            content_type = "text/plain; charset=utf-8";
        }

        if (!resp_body) {
            resp_body = copy_string("");
            resp_body_len = 0;
            need_free_body = 1;
        }

        char header_buf[1024];
        sprintf(header_buf,
                "HTTP/1.1 %d %s\r\n"
                "Content-Type: %s\r\n"
                "Content-Length: %zu\r\n"
                "Connection: close\r\n"
                "Server: GujaratiLang/1.2.0\r\n\r\n",
                status_code, status_msg, content_type, resp_body_len);

        send(client, header_buf, (int)strlen(header_buf), 0);
        if (resp_body_len > 0) {
            send(client, resp_body, (int)resp_body_len, 0);
        }

        if (need_free_body && resp_body) free(resp_body);
        CLOSE_SOCKET(client);
        req_count++;
    }

    CLOSE_SOCKET(srv);
    return number_value(req_count);
}

/* --- Embedded Relational Database Engine --- */

#define MAX_DB_TABLES 16
#define MAX_DB_COLUMNS 32
#define MAX_DB_INSTANCES 16

typedef struct {
    char name[64];
    size_t col_count;
    char col_names[MAX_DB_COLUMNS][64];
    size_t row_count;
    size_t row_capacity;
    char ***rows; /* rows[r][c] */
} GjDbTable;

typedef struct {
    int id;
    int in_use;
    char filename[260];
    size_t table_count;
    GjDbTable tables[MAX_DB_TABLES];
} GjDbInstance;

static GjDbInstance g_dbs[MAX_DB_INSTANCES];
static int g_db_next_id = 1;

static GjDbInstance *get_db_by_id(int id)
{
    for (int i = 0; i < MAX_DB_INSTANCES; i++) {
        if (g_dbs[i].in_use && g_dbs[i].id == id) {
            return &g_dbs[i];
        }
    }
    return NULL;
}

static GjDbTable *get_table(GjDbInstance *db, const char *tname)
{
    for (size_t i = 0; i < db->table_count; i++) {
        if (STR_ICMP(db->tables[i].name, tname) == 0) {
            return &db->tables[i];
        }
    }
    return NULL;
}

static void db_save_to_file(GjDbInstance *db)
{
    if (!db || !db->filename[0] || strcmp(db->filename, ":memory:") == 0) return;
    FILE *fp = fopen(db->filename, "w");
    if (!fp) return;

    fprintf(fp, "# GUJARATILANG_DB_V1\n");
    fprintf(fp, "TABLES %zu\n", db->table_count);
    for (size_t t = 0; t < db->table_count; t++) {
        GjDbTable *tbl = &db->tables[t];
        fprintf(fp, "TABLE %s %zu %zu\n", tbl->name, tbl->col_count, tbl->row_count);
        for (size_t c = 0; c < tbl->col_count; c++) {
            fprintf(fp, "%s%c", tbl->col_names[c], (c + 1 == tbl->col_count) ? '\n' : '\t');
        }
        for (size_t r = 0; r < tbl->row_count; r++) {
            for (size_t c = 0; c < tbl->col_count; c++) {
                char *val = tbl->rows[r][c];
                /* Replace tab and newline with escaped versions */
                if (!val) {
                    fprintf(fp, "\\NULL");
                } else {
                    for (char *p = val; *p; p++) {
                        if (*p == '\t') fputs("\\t", fp);
                        else if (*p == '\n') fputs("\\n", fp);
                        else if (*p == '\\') fputs("\\\\", fp);
                        else fputc(*p, fp);
                    }
                }
                fputc((c + 1 == tbl->col_count) ? '\n' : '\t', fp);
            }
        }
    }
    fclose(fp);
}

static void db_load_from_file(GjDbInstance *db)
{
    if (!db || !db->filename[0] || strcmp(db->filename, ":memory:") == 0) return;
    FILE *fp = fopen(db->filename, "r");
    if (!fp) return;

    char line[4096];
    if (!fgets(line, sizeof(line), fp)) { fclose(fp); return; }
    if (strncmp(line, "# GUJARATILANG_DB_V1", 20) != 0) { fclose(fp); return; }

    size_t num_tables = 0;
    if (fscanf(fp, "TABLES %zu\n", &num_tables) != 1) { fclose(fp); return; }

    for (size_t t = 0; t < num_tables && t < MAX_DB_TABLES; t++) {
        char tname[64];
        size_t cols = 0, rows = 0;
        if (fscanf(fp, "TABLE %63s %zu %zu\n", tname, &cols, &rows) != 3) break;

        GjDbTable *tbl = &db->tables[db->table_count++];
        strncpy(tbl->name, tname, sizeof(tbl->name)-1);
        tbl->col_count = cols;
        tbl->row_count = 0;
        tbl->row_capacity = rows > 0 ? rows : 8;
        tbl->rows = (char ***)calloc(tbl->row_capacity, sizeof(char **));

        for (size_t c = 0; c < cols; c++) {
            char cname[64];
            if (fscanf(fp, "%63s", cname) == 1) {
                strncpy(tbl->col_names[c], cname, sizeof(tbl->col_names[c])-1);
            }
        }
        fgetc(fp); /* consume newline */

        for (size_t r = 0; r < rows; r++) {
            if (!fgets(line, sizeof(line), fp)) break;
            size_t l_len = strlen(line);
            while (l_len > 0 && (line[l_len - 1] == '\r' || line[l_len - 1] == '\n')) {
                line[--l_len] = '\0';
            }
            char **row = (char **)calloc(cols, sizeof(char *));
            char *p = line;
            for (size_t c = 0; c < cols; c++) {
                char *tab = strchr(p, '\t');
                if (tab) *tab = '\0';
                if (strcmp(p, "\\NULL") == 0) {
                    row[c] = copy_string("");
                } else {
                    /* unescape */
                    StringBuffer sb;
                    sb_init(&sb);
                    for (char *s = p; *s; s++) {
                        if (*s == '\\' && *(s + 1)) {
                            s++;
                            if (*s == 't') sb_append(&sb, "\t", 1);
                            else if (*s == 'n') sb_append(&sb, "\n", 1);
                            else sb_append(&sb, s, 1);
                        } else {
                            sb_append(&sb, s, 1);
                        }
                    }
                    row[c] = sb.data ? sb.data : copy_string("");
                }
                if (tab) p = tab + 1;
                else p = "";
            }
            tbl->rows[tbl->row_count++] = row;
        }
    }
    fclose(fp);
}

static Value db_kholo_helper(Parser *parser, Token name, Value filename_val)
{
    if (filename_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *fn = value_to_c_string(parser, filename_val);
    if (!fn) return null_value();

    int slot = -1;
    for (int i = 0; i < MAX_DB_INSTANCES; i++) {
        if (!g_dbs[i].in_use) {
            slot = i;
            break;
        }
    }
    if (slot == -1) {
        free(fn);
        return number_value(-1);
    }

    GjDbInstance *db = &g_dbs[slot];
    memset(db, 0, sizeof(*db));
    db->id = g_db_next_id++;
    db->in_use = 1;
    strncpy(db->filename, fn, sizeof(db->filename) - 1);
    free(fn);

    db_load_from_file(db);
    return number_value(db->id);
}

static Value db_chalao_helper(Parser *parser, Token name, Value db_id_val, Value sql_val, Value params_val, int has_params)
{
    if (db_id_val.kind != VALUE_NUMBER || sql_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    GjDbInstance *db = get_db_by_id((int)db_id_val.number);
    if (!db) return number_value(0);

    char *sql = value_to_c_string(parser, sql_val);
    if (!sql) return number_value(0);

    /* Trim leading spaces */
    char *p = sql;
    while (*p && isspace((unsigned char)*p)) p++;

    int affected = 0;

    if (STR_NICMP(p, "CREATE TABLE", 12) == 0) {
        p += 12;
        while (*p && isspace((unsigned char)*p)) p++;
        int if_not_exists = 0;
        if (STR_NICMP(p, "IF NOT EXISTS", 13) == 0) {
            if_not_exists = 1;
            p += 13;
            while (*p && isspace((unsigned char)*p)) p++;
        }
        char tname[64] = {0};
        char *open_p = strchr(p, '(');
        if (open_p) {
            size_t nlen = open_p - p;
            while (nlen > 0 && isspace((unsigned char)p[nlen - 1])) nlen--;
            if (nlen >= sizeof(tname)) nlen = sizeof(tname) - 1;
            strncpy(tname, p, nlen);
            tname[nlen] = '\0';

            GjDbTable *existing = get_table(db, tname);
            if (existing) {
                if (!if_not_exists) {
                    /* Table already exists */
                }
                affected = 1;
            } else if (db->table_count < MAX_DB_TABLES) {
                GjDbTable *tbl = &db->tables[db->table_count++];
                memset(tbl, 0, sizeof(*tbl));
                strncpy(tbl->name, tname, sizeof(tbl->name) - 1);

                char *close_p = strchr(open_p, ')');
                if (close_p) {
                    char cols_str[1024];
                    size_t clen = close_p - (open_p + 1);
                    if (clen >= sizeof(cols_str)) clen = sizeof(cols_str) - 1;
                    strncpy(cols_str, open_p + 1, clen);
                    cols_str[clen] = '\0';

                    char *cp = cols_str;
                    while (*cp) {
                        char *comma = strchr(cp, ',');
                        size_t flen = comma ? (size_t)(comma - cp) : strlen(cp);
                        char field[64];
                        if (flen >= sizeof(field)) flen = sizeof(field) - 1;
                        strncpy(field, cp, flen);
                        field[flen] = '\0';

                        char *fstart = field;
                        while (*fstart && isspace((unsigned char)*fstart)) fstart++;
                        char *fend = fstart + strlen(fstart);
                        while (fend > fstart && isspace((unsigned char)*(fend - 1))) fend--;
                        *fend = '\0';

                        /* Take first word as column name */
                        char col_word[64] = {0};
                        sscanf(fstart, "%63s", col_word);
                        if (col_word[0] && tbl->col_count < MAX_DB_COLUMNS) {
                            strncpy(tbl->col_names[tbl->col_count++], col_word, sizeof(tbl->col_names[0]) - 1);
                        }
                        if (!comma) break;
                        cp = comma + 1;
                    }
                }
                tbl->row_capacity = 8;
                tbl->rows = (char ***)calloc(tbl->row_capacity, sizeof(char **));
                affected = 1;
                db_save_to_file(db);
            }
        }
    } else if (STR_NICMP(p, "INSERT INTO", 11) == 0) {
        p += 11;
        while (*p && isspace((unsigned char)*p)) p++;
        char tname[64] = {0};
        char *space_or_paren = p;
        while (*space_or_paren && !isspace((unsigned char)*space_or_paren) && *space_or_paren != '(') space_or_paren++;
        size_t tnlen = space_or_paren - p;
        if (tnlen >= sizeof(tname)) tnlen = sizeof(tname) - 1;
        strncpy(tname, p, tnlen);
        tname[tnlen] = '\0';

        GjDbTable *tbl = get_table(db, tname);
        if (tbl) {
            char *val_p = strstr(space_or_paren, "VALUES");
            if (!val_p) val_p = strstr(space_or_paren, "values");
            if (val_p) {
                val_p += 6;
                char *open_p = strchr(val_p, '(');
                char *close_p = open_p ? strrchr(open_p, ')') : NULL;
                if (open_p && close_p) {
                    char vals_str[2048];
                    size_t vlen = close_p - (open_p + 1);
                    if (vlen >= sizeof(vals_str)) vlen = sizeof(vals_str) - 1;
                    strncpy(vals_str, open_p + 1, vlen);
                    vals_str[vlen] = '\0';

                    if (tbl->row_count == tbl->row_capacity) {
                        tbl->row_capacity *= 2;
                        tbl->rows = (char ***)realloc(tbl->rows, tbl->row_capacity * sizeof(char **));
                    }
                    char **row = (char **)calloc(tbl->col_count, sizeof(char *));

                    size_t param_idx = 0;
                    char *vp = vals_str;
                    size_t c_idx = 0;

                    while (*vp && c_idx < tbl->col_count) {
                        char *comma = strchr(vp, ',');
                        size_t flen = comma ? (size_t)(comma - vp) : strlen(vp);
                        char item[512];
                        if (flen >= sizeof(item)) flen = sizeof(item) - 1;
                        strncpy(item, vp, flen);
                        item[flen] = '\0';

                        char *istart = item;
                        while (*istart && isspace((unsigned char)*istart)) istart++;
                        char *iend = istart + strlen(istart);
                        while (iend > istart && isspace((unsigned char)*(iend - 1))) iend--;
                        *iend = '\0';

                        if (strcmp(istart, "?") == 0) {
                            if (has_params && params_val.kind == VALUE_LIST && param_idx < params_val.list->count) {
                                Value pv = params_val.list->items[param_idx++];
                                StringBuffer sb;
                                sb_init(&sb);
                                List *anc[256];
                                format_value_to_sb(parser, pv, &sb, anc, 0);
                                row[c_idx++] = sb.data ? sb.data : copy_string("");
                            } else {
                                row[c_idx++] = copy_string("");
                            }
                        } else {
                            if ((istart[0] == '\'' || istart[0] == '"') && iend > istart + 1 && *(iend - 1) == istart[0]) {
                                istart++;
                                *(iend - 1) = '\0';
                            }
                            row[c_idx++] = copy_string(istart);
                        }
                        if (!comma) break;
                        vp = comma + 1;
                    }

                    tbl->rows[tbl->row_count++] = row;
                    affected = 1;
                    db_save_to_file(db);
                }
            }
        }
    } else if (STR_NICMP(p, "UPDATE", 6) == 0) {
        p += 6;
        while (*p && isspace((unsigned char)*p)) p++;
        char tname[64] = {0};
        sscanf(p, "%63s", tname);
        GjDbTable *tbl = get_table(db, tname);
        if (tbl) {
            char *set_p = strstr(p, "SET");
            if (!set_p) set_p = strstr(p, "set");
            if (set_p) {
                set_p += 3;
                char *where_p = strstr(set_p, "WHERE");
                if (!where_p) where_p = strstr(set_p, "where");

                char set_expr[512] = {0};
                size_t slen = where_p ? (size_t)(where_p - set_p) : strlen(set_p);
                if (slen >= sizeof(set_expr)) slen = sizeof(set_expr) - 1;
                strncpy(set_expr, set_p, slen);

                char set_col[64] = {0}, set_val[256] = {0};
                char *eq = strchr(set_expr, '=');
                if (eq) {
                    *eq = '\0';
                    sscanf(set_expr, "%63s", set_col);
                    char *sv = eq + 1;
                    while (*sv && isspace((unsigned char)*sv)) sv++;
                    char *se = sv + strlen(sv);
                    while (se > sv && isspace((unsigned char)*(se - 1))) se--;
                    *se = '\0';
                    if ((*sv == '\'' || *sv == '"') && se > sv + 1 && *(se - 1) == *sv) {
                        sv++; *(se - 1) = '\0';
                    }
                    strcpy(set_val, sv);
                }

                int set_col_idx = -1;
                for (size_t c = 0; c < tbl->col_count; c++) {
                    if (STR_ICMP(tbl->col_names[c], set_col) == 0) {
                        set_col_idx = (int)c;
                        break;
                    }
                }

                char where_col[64] = {0}, where_val[256] = {0};
                int where_col_idx = -1;
                if (where_p) {
                    where_p += 5;
                    char *weq = strchr(where_p, '=');
                    if (weq) {
                        char wcol_buf[64] = {0};
                        size_t wlen = weq - where_p;
                        if (wlen >= sizeof(wcol_buf)) wlen = sizeof(wcol_buf) - 1;
                        strncpy(wcol_buf, where_p, wlen);
                        sscanf(wcol_buf, "%63s", where_col);

                        char *wv = weq + 1;
                        while (*wv && isspace((unsigned char)*wv)) wv++;
                        char *we = wv + strlen(wv);
                        while (we > wv && isspace((unsigned char)*(we - 1))) we--;
                        *we = '\0';
                        if ((*wv == '\'' || *wv == '"') && we > wv + 1 && *(we - 1) == *wv) {
                            wv++; *(we - 1) = '\0';
                        }
                        strcpy(where_val, wv);
                    }
                    for (size_t c = 0; c < tbl->col_count; c++) {
                        if (STR_ICMP(tbl->col_names[c], where_col) == 0) {
                            where_col_idx = (int)c;
                            break;
                        }
                    }
                }

                if (set_col_idx >= 0) {
                    for (size_t r = 0; r < tbl->row_count; r++) {
                        int match = 1;
                        if (where_col_idx >= 0) {
                            char *cell = tbl->rows[r][where_col_idx];
                            if (!cell || strcmp(cell, where_val) != 0) {
                                match = 0;
                            }
                        }
                        if (match) {
                            if (tbl->rows[r][set_col_idx]) free(tbl->rows[r][set_col_idx]);
                            tbl->rows[r][set_col_idx] = copy_string(set_val);
                            affected++;
                        }
                    }
                    if (affected > 0) db_save_to_file(db);
                }
            }
        }
    } else if (STR_NICMP(p, "DELETE FROM", 11) == 0) {
        p += 11;
        while (*p && isspace((unsigned char)*p)) p++;
        char tname[64] = {0};
        sscanf(p, "%63s", tname);
        GjDbTable *tbl = get_table(db, tname);
        if (tbl) {
            char *where_p = strstr(p, "WHERE");
            if (!where_p) where_p = strstr(p, "where");

            char where_col[64] = {0}, where_val[256] = {0};
            int where_col_idx = -1;
            if (where_p) {
                where_p += 5;
                char *weq = strchr(where_p, '=');
                if (weq) {
                    char wcol_buf[64] = {0};
                    size_t wlen = weq - where_p;
                    if (wlen >= sizeof(wcol_buf)) wlen = sizeof(wcol_buf) - 1;
                    strncpy(wcol_buf, where_p, wlen);
                    sscanf(wcol_buf, "%63s", where_col);

                    char *wv = weq + 1;
                    while (*wv && isspace((unsigned char)*wv)) wv++;
                    char *we = wv + strlen(wv);
                    while (we > wv && isspace((unsigned char)*(we - 1))) we--;
                    *we = '\0';
                    if ((*wv == '\'' || *wv == '"') && we > wv + 1 && *(we - 1) == *wv) {
                        wv++; *(we - 1) = '\0';
                    }
                    strcpy(where_val, wv);
                }
                for (size_t c = 0; c < tbl->col_count; c++) {
                    if (STR_ICMP(tbl->col_names[c], where_col) == 0) {
                        where_col_idx = (int)c;
                        break;
                    }
                }
            }

            size_t write_idx = 0;
            for (size_t r = 0; r < tbl->row_count; r++) {
                int match = 1;
                if (where_col_idx >= 0) {
                    char *cell = tbl->rows[r][where_col_idx];
                    if (!cell || strcmp(cell, where_val) != 0) {
                        match = 0;
                    }
                }
                if (match) {
                    affected++;
                    for (size_t c = 0; c < tbl->col_count; c++) {
                        if (tbl->rows[r][c]) free(tbl->rows[r][c]);
                    }
                    free(tbl->rows[r]);
                } else {
                    tbl->rows[write_idx++] = tbl->rows[r];
                }
            }
            tbl->row_count = write_idx;
            if (affected > 0) db_save_to_file(db);
        }
    }

    free(sql);
    return number_value(affected);
}

static Value db_shodho_helper(Parser *parser, Token name, Value db_id_val, Value sql_val, Value params_val, int has_params)
{
    (void)has_params; (void)params_val;
    if (db_id_val.kind != VALUE_NUMBER || sql_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    GjDbInstance *db = get_db_by_id((int)db_id_val.number);
    List *res_list = create_list(parser, name);
    Value res_val; res_val.kind = VALUE_LIST; res_val.list = res_list;
    if (!db) return res_val;

    char *sql = value_to_c_string(parser, sql_val);
    if (!sql) return res_val;

    char *p = sql;
    while (*p && isspace((unsigned char)*p)) p++;

    if (STR_NICMP(p, "SELECT", 6) != 0) {
        free(sql);
        return res_val;
    }
    p += 6;

    char *from_p = strstr(p, "FROM");
    if (!from_p) from_p = strstr(p, "from");
    if (!from_p) { free(sql); return res_val; }

    char cols_clause[512] = {0};
    size_t clen = from_p - p;
    if (clen >= sizeof(cols_clause)) clen = sizeof(cols_clause) - 1;
    strncpy(cols_clause, p, clen);

    p = from_p + 4;
    while (*p && isspace((unsigned char)*p)) p++;

    char tname[64] = {0};
    sscanf(p, "%63s", tname);
    GjDbTable *tbl = get_table(db, tname);
    if (!tbl) { free(sql); return res_val; }

    /* Check WHERE */
    char *where_p = strstr(p, "WHERE");
    if (!where_p) where_p = strstr(p, "where");

    char where_col[64] = {0}, where_op[8] = {0}, where_val[256] = {0};
    int where_col_idx = -1;
    if (where_p) {
        where_p += 5;
        char *end_where = strstr(where_p, "ORDER BY");
        if (!end_where) end_where = strstr(where_p, "order by");
        if (!end_where) end_where = strstr(where_p, "LIMIT");
        if (!end_where) end_where = strstr(where_p, "limit");

        char where_str[512] = {0};
        size_t wlen = end_where ? (size_t)(end_where - where_p) : strlen(where_p);
        if (wlen >= sizeof(where_str)) wlen = sizeof(where_str) - 1;
        strncpy(where_str, where_p, wlen);

        char *w_eq = strstr(where_str, ">=");
        if (!w_eq) w_eq = strstr(where_str, "<=");
        if (!w_eq) w_eq = strstr(where_str, "!=");
        if (!w_eq) w_eq = strstr(where_str, "=");
        if (!w_eq) w_eq = strstr(where_str, ">");
        if (!w_eq) w_eq = strstr(where_str, "<");

        if (w_eq) {
            size_t op_len = (w_eq[1] == '=' ? 2 : 1);
            strncpy(where_op, w_eq, op_len);
            where_op[op_len] = '\0';

            char wcol_buf[64] = {0};
            size_t c_len = w_eq - where_str;
            if (c_len >= sizeof(wcol_buf)) c_len = sizeof(wcol_buf) - 1;
            strncpy(wcol_buf, where_str, c_len);
            sscanf(wcol_buf, "%63s", where_col);

            char *wv = w_eq + op_len;
            while (*wv && isspace((unsigned char)*wv)) wv++;
            char *we = wv + strlen(wv);
            while (we > wv && isspace((unsigned char)*(we - 1))) we--;
            *we = '\0';
            if ((*wv == '\'' || *wv == '"') && we > wv + 1 && *(we - 1) == *wv) {
                wv++; *(we - 1) = '\0';
            }
            strcpy(where_val, wv);
        }

        for (size_t c = 0; c < tbl->col_count; c++) {
            if (STR_ICMP(tbl->col_names[c], where_col) == 0) {
                where_col_idx = (int)c;
                break;
            }
        }
    }

    /* Selected columns */
    int select_all = (strstr(cols_clause, "*") != NULL);
    int selected_cols[MAX_DB_COLUMNS];
    size_t selected_count = 0;

    if (select_all) {
        for (size_t c = 0; c < tbl->col_count; c++) {
            selected_cols[selected_count++] = (int)c;
        }
    } else {
        char *cp = cols_clause;
        while (*cp) {
            char *comma = strchr(cp, ',');
            size_t flen = comma ? (size_t)(comma - cp) : strlen(cp);
            char col_w[64];
            if (flen >= sizeof(col_w)) flen = sizeof(col_w) - 1;
            strncpy(col_w, cp, flen);
            col_w[flen] = '\0';

            char trimmed[64] = {0};
            sscanf(col_w, "%63s", trimmed);
            for (size_t c = 0; c < tbl->col_count; c++) {
                if (STR_ICMP(tbl->col_names[c], trimmed) == 0) {
                    selected_cols[selected_count++] = (int)c;
                    break;
                }
            }
            if (!comma) break;
            cp = comma + 1;
        }
    }

    for (size_t r = 0; r < tbl->row_count; r++) {
        int match = 1;
        if (where_col_idx >= 0) {
            char *cell = tbl->rows[r][where_col_idx];
            if (!cell) match = 0;
            else {
                char *endp1 = NULL, *endp2 = NULL;
                double d1 = strtod(cell, &endp1);
                double d2 = strtod(where_val, &endp2);
                int is_num = (endp1 && *endp1 == '\0' && endp2 && *endp2 == '\0');

                if (strcmp(where_op, "=") == 0) {
                    if (is_num) match = (d1 == d2);
                    else match = (strcmp(cell, where_val) == 0);
                } else if (strcmp(where_op, "!=") == 0) {
                    if (is_num) match = (d1 != d2);
                    else match = (strcmp(cell, where_val) != 0);
                } else if (strcmp(where_op, ">") == 0) {
                    if (is_num) match = (d1 > d2);
                    else match = (strcmp(cell, where_val) > 0);
                } else if (strcmp(where_op, "<") == 0) {
                    if (is_num) match = (d1 < d2);
                    else match = (strcmp(cell, where_val) < 0);
                } else if (strcmp(where_op, ">=") == 0) {
                    if (is_num) match = (d1 >= d2);
                    else match = (strcmp(cell, where_val) >= 0);
                } else if (strcmp(where_op, "<=") == 0) {
                    if (is_num) match = (d1 <= d2);
                    else match = (strcmp(cell, where_val) <= 0);
                }
            }
        }

        if (match) {
            Dict *row_dict = create_dict(parser, name);
            for (size_t i = 0; i < selected_count; i++) {
                int c_idx = selected_cols[i];
                const char *c_name = tbl->col_names[c_idx];
                char *c_val = tbl->rows[r][c_idx];
                Value val;
                if (!c_val) {
                    val = null_value();
                } else {
                    char *endp = NULL;
                    double d = strtod(c_val, &endp);
                    if (endp && *endp == '\0' && c_val[0] != '\0') {
                        val = number_value(d);
                    } else {
                        val = make_owned_string_value(parser, name, copy_string(c_val), strlen(c_val));
                    }
                }
                dict_set(parser, row_dict, c_name, strlen(c_name), val, name);
            }
            Value row_v; row_v.kind = VALUE_DICT; row_v.dict = row_dict;
            append_list_item(parser, res_list, row_v, name);
        }
    }

    free(sql);
    return res_val;
}

static Value db_count_helper(Parser *parser, Token name, Value db_id_val, Value table_val)
{
    if (db_id_val.kind != VALUE_NUMBER || table_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    GjDbInstance *db = get_db_by_id((int)db_id_val.number);
    if (!db) return number_value(0);
    char *tname = value_to_c_string(parser, table_val);
    if (!tname) return number_value(0);
    GjDbTable *tbl = get_table(db, tname);
    free(tname);
    if (!tbl) return number_value(0);
    return number_value((double)tbl->row_count);
}

static Value db_bandh_helper(Parser *parser, Token name, Value db_id_val)
{
    (void)parser; (void)name;
    if (db_id_val.kind != VALUE_NUMBER) return number_value(0);
    GjDbInstance *db = get_db_by_id((int)db_id_val.number);
    if (!db) return number_value(0);

    db_save_to_file(db);
    for (size_t t = 0; t < db->table_count; t++) {
        GjDbTable *tbl = &db->tables[t];
        for (size_t r = 0; r < tbl->row_count; r++) {
            for (size_t c = 0; c < tbl->col_count; c++) {
                if (tbl->rows[r][c]) free(tbl->rows[r][c]);
            }
            free(tbl->rows[r]);
        }
        free(tbl->rows);
    }
    db->in_use = 0;
    return number_value(1);
}

/* --- Concurrency, Event Loop Timers & Worker Threads --- */

#define MAX_ASYNC_WORKERS 32

typedef struct {
    int id;
    int active;
    int completed;
    Parser parser;
    Function function;
    Value argument;
    Value result;
#ifdef _WIN32
    HANDLE thread;
#else
    pthread_t thread;
#endif
} GjAsyncWorker;

static GjAsyncWorker g_async_workers[MAX_ASYNC_WORKERS];
static int g_async_next_id = 1;

#ifdef _WIN32
static unsigned __stdcall async_worker_thread(void *param)
{
    GjAsyncWorker *w = (GjAsyncWorker *)param;
    w->result = call_function(&w->parser, w->function, &w->argument);
    w->completed = 1;
    return 0;
}
#else
static void *async_worker_thread(void *param)
{
    GjAsyncWorker *w = (GjAsyncWorker *)param;
    w->result = call_function(&w->parser, w->function, &w->argument);
    w->completed = 1;
    return NULL;
}
#endif

static Value samay_pachhi_helper(Parser *parser, Token name, Value ms_val, Value kary_val, Value arg_val, int has_arg)
{
    if (ms_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    double ms = ms_val.number;
    if (ms > 0) {
#ifdef _WIN32
        Sleep((DWORD)ms);
#else
        usleep((useconds_t)(ms * 1000));
#endif
    }
    Function *fn = resolve_callee_function(parser, kary_val);
    if (fn) {
        Value a = has_arg ? arg_val : null_value();
        return call_function(parser, *fn, &a);
    }
    return number_value(1);
}

static Value samay_antare_helper(Parser *parser, Token name, Value ms_val, Value kary_val, Value count_val, Value arg_val, int has_arg)
{
    if (ms_val.kind != VALUE_NUMBER || count_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    double ms = ms_val.number;
    int count = (int)count_val.number;
    Function *fn = resolve_callee_function(parser, kary_val);
    if (!fn) {
        report_error(parser, name.line, name.column, MESSAGE_UNDEFINED_FUNCTION);
        return null_value();
    }
    Value a = has_arg ? arg_val : null_value();
    for (int i = 0; i < count; i++) {
        if (ms > 0) {
#ifdef _WIN32
            Sleep((DWORD)ms);
#else
            usleep((useconds_t)(ms * 1000));
#endif
        }
        call_function(parser, *fn, &a);
    }
    return number_value(count);
}

static Value async_chalao_helper(Parser *parser, Token name, Value kary_val, Value arg_val, int has_arg)
{
    Function *fn = resolve_callee_function(parser, kary_val);
    if (!fn) {
        report_error(parser, name.line, name.column, MESSAGE_UNDEFINED_FUNCTION);
        return null_value();
    }
    int slot = -1;
    for (int i = 0; i < MAX_ASYNC_WORKERS; i++) {
        if (!g_async_workers[i].active) {
            slot = i;
            break;
        }
    }
    if (slot == -1) return number_value(-1);

    GjAsyncWorker *w = &g_async_workers[slot];
    memset(w, 0, sizeof(*w));
    w->id = g_async_next_id++;
    w->active = 1;
    w->completed = 0;
    w->parser = *parser;
    w->function = *fn;
    w->argument = has_arg ? arg_val : null_value();
    w->result = null_value();

#ifdef _WIN32
    w->thread = (HANDLE)_beginthreadex(NULL, 0, async_worker_thread, w, 0, NULL);
#else
    pthread_create(&w->thread, NULL, async_worker_thread, w);
#endif

    return number_value(w->id);
}

static Value async_parinam_helper(Parser *parser, Token name, Value handle_val, Value timeout_val, int has_timeout)
{
    (void)parser; (void)name;
    if (handle_val.kind != VALUE_NUMBER) return null_value();
    int hid = (int)handle_val.number;
    GjAsyncWorker *w = NULL;
    for (int i = 0; i < MAX_ASYNC_WORKERS; i++) {
        if (g_async_workers[i].active && g_async_workers[i].id == hid) {
            w = &g_async_workers[i];
            break;
        }
    }
    if (!w) return null_value();

#ifdef _WIN32
    DWORD to = (has_timeout && timeout_val.kind == VALUE_NUMBER) ? (DWORD)timeout_val.number : INFINITE;
    WaitForSingleObject(w->thread, to);
    CloseHandle(w->thread);
#else
    (void)has_timeout; (void)timeout_val;
    pthread_join(w->thread, NULL);
#endif

    Value res = w->result;
    w->active = 0;
    return res;
}

static Value thread_id_helper(void)
{
#ifdef _WIN32
    return number_value((double)GetCurrentThreadId());
#else
    return number_value((double)(unsigned long)pthread_self());
#endif
}

/* --- Gujarati NLP & Machine Learning Suite --- */

static Value nlp_gujarati_token_helper(Parser *parser, Token name, Value text_val)
{
    if (text_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *text = value_to_c_string(parser, text_val);
    List *tok_list = create_list(parser, name);
    Value res; res.kind = VALUE_LIST; res.list = tok_list;
    if (!text) return res;

    unsigned char *p = (unsigned char *)text;
    while (*p) {
        /* Skip ASCII whitespace & standard punctuation */
        while (*p && (*p <= 32 || strchr(".,;:!?()[]{}\"'`~@#$%^&*+-=/<>|\\", *p))) {
            p++;
        }
        /* Check Indic danda U+0964 (\xE0\xA5\xA4) or double danda U+0965 (\xE0\xA5\xA5) or abbreviation sign U+0AF0 (\xE0\xAB\xB0) */
        while (p[0] == 0xE0 && (
               (p[1] == 0xA5 && (p[2] == 0xA4 || p[2] == 0xA5)) ||
               (p[1] == 0xAB && p[2] == 0xB0))) {
            p += 3;
            while (*p && (*p <= 32 || strchr(".,;:!?()[]{}\"'`~@#$%^&*+-=/<>|\\", *p))) p++;
        }
        if (!*p) break;

        unsigned char *tok_start = p;
        while (*p) {
            if (*p <= 32 || strchr(".,;:!?()[]{}\"'`~@#$%^&*+-=/<>|\\", *p)) break;
            if (p[0] == 0xE0 && (
                (p[1] == 0xA5 && (p[2] == 0xA4 || p[2] == 0xA5)) ||
                (p[1] == 0xAB && p[2] == 0xB0))) break;
            p++;
        }

        size_t tok_len = p - tok_start;
        if (tok_len > 0) {
            char *tok_str = (char *)malloc(tok_len + 1);
            if (tok_str) {
                memcpy(tok_str, tok_start, tok_len);
                tok_str[tok_len] = '\0';
                Value tv = make_owned_string_value(parser, name, tok_str, tok_len);
                append_list_item(parser, tok_list, tv, name);
            }
        }
    }

    free(text);
    return res;
}

static Value nlp_matra_kadho_helper(Parser *parser, Token name, Value text_val)
{
    if (text_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *text = value_to_c_string(parser, text_val);
    if (!text) return make_owned_string_value(parser, name, copy_string(""), 0);

    StringBuffer sb;
    sb_init(&sb);

    unsigned char *p = (unsigned char *)text;
    while (*p) {
        int is_matra = 0;
        if (p[0] == 0xE0) {
            if (p[1] == 0xAA) {
                /* U+0A81, U+0A82, U+0A83, U+0ABC, U+0ABE, U+0ABF */
                unsigned char b2 = p[2];
                if (b2 == 0x81 || b2 == 0x82 || b2 == 0x83 || b2 == 0xBC || b2 == 0xBE || b2 == 0xBF) {
                    is_matra = 1;
                }
            } else if (p[1] == 0xAB) {
                /* U+0AC0..U+0AC5, U+0AC7..U+0AC9, U+0ACB..U+0ACD */
                unsigned char b2 = p[2];
                if ((b2 >= 0x80 && b2 <= 0x85) ||
                    (b2 >= 0x87 && b2 <= 0x89) ||
                    (b2 >= 0x8B && b2 <= 0x8D)) {
                    is_matra = 1;
                }
            }
        }
        if (is_matra) {
            p += 3;
        } else {
            sb_append(&sb, (const char *)p, 1);
            p++;
        }
    }

    free(text);
    if (!sb.failed && sb.data) {
        return make_owned_string_value(parser, name, sb.data, sb.length);
    }
    return make_owned_string_value(parser, name, copy_string(""), 0);
}

static Value nlp_shabda_aavrutti_helper(Parser *parser, Token name, Value list_val)
{
    if (list_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    Dict *freq_dict = create_dict(parser, name);
    Value res; res.kind = VALUE_DICT; res.dict = freq_dict;

    for (size_t i = 0; i < list_val.list->count; i++) {
        Value item = list_val.list->items[i];
        char *word = NULL;
        if (item.kind == VALUE_STRING) {
            word = value_to_c_string(parser, item);
        } else {
            StringBuffer sb;
            sb_init(&sb);
            List *anc[256];
            format_value_to_sb(parser, item, &sb, anc, 0);
            word = sb.data;
        }
        if (word) {
            size_t wlen = strlen(word);
            Value *existing = dict_get(freq_dict, word, wlen);
            if (existing && existing->kind == VALUE_NUMBER) {
                existing->number += 1.0;
            } else {
                dict_set(parser, freq_dict, word, wlen, number_value(1.0), name);
            }
            free(word);
        }
    }

    return res;
}

static Value ml_tfidf_helper(Parser *parser, Token name, Value docs_val)
{
    if (docs_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t doc_count = docs_val.list->count;
    if (doc_count == 0) {
        Dict *res = create_dict(parser, name);
        Value v; v.kind = VALUE_DICT; v.dict = res;
        return v;
    }

    /* Tokenize each doc */
    char ***doc_tokens = (char ***)calloc(doc_count, sizeof(char **));
    size_t *doc_lengths = (size_t *)calloc(doc_count, sizeof(size_t));

    /* Build vocabulary */
    char **vocab = NULL;
    size_t vocab_size = 0, vocab_cap = 0;

    for (size_t d = 0; d < doc_count; d++) {
        Value doc_item = docs_val.list->items[d];
        Value tokens_val;
        if (doc_item.kind == VALUE_LIST) {
            tokens_val = doc_item;
        } else {
            tokens_val = nlp_gujarati_token_helper(parser, name, doc_item);
        }
        if (tokens_val.kind == VALUE_LIST) {
            size_t ntoks = tokens_val.list->count;
            doc_lengths[d] = ntoks;
            doc_tokens[d] = (char **)calloc(ntoks, sizeof(char *));
            for (size_t t = 0; t < ntoks; t++) {
                char *w = value_to_c_string(parser, tokens_val.list->items[t]);
                doc_tokens[d][t] = w ? w : copy_string("");

                /* Check if in vocab */
                int in_vocab = 0;
                for (size_t v = 0; v < vocab_size; v++) {
                    if (strcmp(vocab[v], doc_tokens[d][t]) == 0) {
                        in_vocab = 1;
                        break;
                    }
                }
                if (!in_vocab) {
                    if (vocab_size == vocab_cap) {
                        vocab_cap = vocab_cap == 0 ? 16 : vocab_cap * 2;
                        vocab = (char **)realloc(vocab, vocab_cap * sizeof(char *));
                    }
                    vocab[vocab_size++] = copy_string(doc_tokens[d][t]);
                }
            }
        }
    }

    /* Compute DF and IDF for each term */
    double *idf = (double *)calloc(vocab_size, sizeof(double));
    for (size_t v = 0; v < vocab_size; v++) {
        size_t df = 0;
        for (size_t d = 0; d < doc_count; d++) {
            for (size_t t = 0; t < doc_lengths[d]; t++) {
                if (strcmp(doc_tokens[d][t], vocab[v]) == 0) {
                    df++;
                    break;
                }
            }
        }
        /* Standard smoothed IDF: log((1 + N) / (1 + DF)) + 1.0 */
        idf[v] = log((1.0 + (double)doc_count) / (1.0 + (double)df)) + 1.0;
    }

    /* Build output Dict {"vocabulary": [...], "matrix": [[...]]} */
    Dict *out_dict = create_dict(parser, name);
    List *vocab_list = create_list(parser, name);
    for (size_t v = 0; v < vocab_size; v++) {
        Value vw = make_owned_string_value(parser, name, copy_string(vocab[v]), strlen(vocab[v]));
        append_list_item(parser, vocab_list, vw, name);
    }
    Value vval; vval.kind = VALUE_LIST; vval.list = vocab_list;
    dict_set(parser, out_dict, "vocabulary", 10, vval, name);

    List *matrix_list = create_list(parser, name);
    for (size_t d = 0; d < doc_count; d++) {
        List *row_list = create_list(parser, name);
        double total_words = (double)doc_lengths[d];
        for (size_t v = 0; v < vocab_size; v++) {
            size_t count = 0;
            for (size_t t = 0; t < doc_lengths[d]; t++) {
                if (strcmp(doc_tokens[d][t], vocab[v]) == 0) count++;
            }
            double tf = (total_words > 0) ? ((double)count / total_words) : 0.0;
            double score = tf * idf[v];
            /* Round to 4 decimal places for clean representation */
            score = floor(score * 10000.0 + 0.5) / 10000.0;
            append_list_item(parser, row_list, number_value(score), name);
        }
        Value rval; rval.kind = VALUE_LIST; rval.list = row_list;
        append_list_item(parser, matrix_list, rval, name);
    }
    Value mval; mval.kind = VALUE_LIST; mval.list = matrix_list;
    dict_set(parser, out_dict, "matrix", 6, mval, name);

    /* Cleanup memory */
    for (size_t d = 0; d < doc_count; d++) {
        for (size_t t = 0; t < doc_lengths[d]; t++) {
            if (doc_tokens[d][t]) free(doc_tokens[d][t]);
        }
        if (doc_tokens[d]) free(doc_tokens[d]);
    }
    free(doc_tokens);
    free(doc_lengths);
    for (size_t v = 0; v < vocab_size; v++) {
        if (vocab[v]) free(vocab[v]);
    }
    if (vocab) free(vocab);
    free(idf);

    Value res; res.kind = VALUE_DICT; res.dict = out_dict;
    return res;
}

static Value ml_naive_bayes_train_helper(Parser *parser, Token name, Value features_val, Value labels_val)
{
    if (features_val.kind != VALUE_LIST || labels_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t n_samples = features_val.list->count;
    if (n_samples == 0 || n_samples != labels_val.list->count) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }

    /* Extract labels and unique classes */
    char **sample_labels = (char **)calloc(n_samples, sizeof(char *));
    char **classes = NULL;
    size_t class_count = 0, class_cap = 0;

    for (size_t i = 0; i < n_samples; i++) {
        char *lbl = value_to_c_string(parser, labels_val.list->items[i]);
        sample_labels[i] = lbl ? lbl : copy_string("");
        int in_cls = 0;
        for (size_t c = 0; c < class_count; c++) {
            if (strcmp(classes[c], sample_labels[i]) == 0) {
                in_cls = 1;
                break;
            }
        }
        if (!in_cls) {
            if (class_count == class_cap) {
                class_cap = class_cap == 0 ? 4 : class_cap * 2;
                classes = (char **)realloc(classes, class_cap * sizeof(char *));
            }
            classes[class_count++] = copy_string(sample_labels[i]);
        }
    }

    /* Extract tokens for each sample and build vocabulary */
    char ***sample_tokens = (char ***)calloc(n_samples, sizeof(char **));
    size_t *sample_lengths = (size_t *)calloc(n_samples, sizeof(size_t));
    char **vocab = NULL;
    size_t vocab_size = 0, vocab_cap = 0;

    for (size_t i = 0; i < n_samples; i++) {
        Value f_item = features_val.list->items[i];
        Value toks_val = (f_item.kind == VALUE_LIST) ? f_item : nlp_gujarati_token_helper(parser, name, f_item);
        if (toks_val.kind == VALUE_LIST) {
            size_t ntoks = toks_val.list->count;
            sample_lengths[i] = ntoks;
            sample_tokens[i] = (char **)calloc(ntoks, sizeof(char *));
            for (size_t t = 0; t < ntoks; t++) {
                char *w = value_to_c_string(parser, toks_val.list->items[t]);
                sample_tokens[i][t] = w ? w : copy_string("");

                int in_voc = 0;
                for (size_t v = 0; v < vocab_size; v++) {
                    if (strcmp(vocab[v], sample_tokens[i][t]) == 0) {
                        in_voc = 1;
                        break;
                    }
                }
                if (!in_voc) {
                    if (vocab_size == vocab_cap) {
                        vocab_cap = vocab_cap == 0 ? 16 : vocab_cap * 2;
                        vocab = (char **)realloc(vocab, vocab_cap * sizeof(char *));
                    }
                    vocab[vocab_size++] = copy_string(sample_tokens[i][t]);
                }
            }
        }
    }

    /* Compute priors and likelihoods */
    Dict *model_dict = create_dict(parser, name);
    List *classes_list = create_list(parser, name);
    Dict *priors_dict = create_dict(parser, name);
    Dict *likelihoods_dict = create_dict(parser, name);

    for (size_t c = 0; c < class_count; c++) {
        const char *c_name = classes[c];
        size_t c_name_len = strlen(c_name);
        Value c_val = make_owned_string_value(parser, name, copy_string(c_name), c_name_len);
        append_list_item(parser, classes_list, c_val, name);

        size_t count_c = 0;
        size_t total_words_in_c = 0;
        for (size_t i = 0; i < n_samples; i++) {
            if (strcmp(sample_labels[i], c_name) == 0) {
                count_c++;
                total_words_in_c += sample_lengths[i];
            }
        }

        double prior = (double)count_c / (double)n_samples;
        dict_set(parser, priors_dict, c_name, c_name_len, number_value(prior), name);

        Dict *c_likelihoods = create_dict(parser, name);
        for (size_t v = 0; v < vocab_size; v++) {
            const char *word = vocab[v];
            size_t word_count_in_c = 0;
            for (size_t i = 0; i < n_samples; i++) {
                if (strcmp(sample_labels[i], c_name) == 0) {
                    for (size_t t = 0; t < sample_lengths[i]; t++) {
                        if (strcmp(sample_tokens[i][t], word) == 0) {
                            word_count_in_c++;
                        }
                    }
                }
            }
            /* Laplace smoothing: (count + 1) / (total_words + vocab_size) */
            double prob = ((double)word_count_in_c + 1.0) / ((double)total_words_in_c + (double)vocab_size);
            dict_set(parser, c_likelihoods, word, strlen(word), number_value(prob), name);
        }
        Value cl_val; cl_val.kind = VALUE_DICT; cl_val.dict = c_likelihoods;
        dict_set(parser, likelihoods_dict, c_name, c_name_len, cl_val, name);
    }

    Value cls_v; cls_v.kind = VALUE_LIST; cls_v.list = classes_list;
    dict_set(parser, model_dict, "classes", 7, cls_v, name);

    Value pri_v; pri_v.kind = VALUE_DICT; pri_v.dict = priors_dict;
    dict_set(parser, model_dict, "priors", 6, pri_v, name);

    Value lik_v; lik_v.kind = VALUE_DICT; lik_v.dict = likelihoods_dict;
    dict_set(parser, model_dict, "likelihoods", 11, lik_v, name);

    dict_set(parser, model_dict, "vocab_size", 10, number_value((double)vocab_size), name);

    /* Cleanup */
    for (size_t i = 0; i < n_samples; i++) {
        if (sample_labels[i]) free(sample_labels[i]);
        for (size_t t = 0; t < sample_lengths[i]; t++) {
            if (sample_tokens[i][t]) free(sample_tokens[i][t]);
        }
        if (sample_tokens[i]) free(sample_tokens[i]);
    }
    free(sample_labels);
    free(sample_tokens);
    free(sample_lengths);
    for (size_t c = 0; c < class_count; c++) free(classes[c]);
    free(classes);
    for (size_t v = 0; v < vocab_size; v++) free(vocab[v]);
    free(vocab);

    Value res; res.kind = VALUE_DICT; res.dict = model_dict;
    return res;
}

static Value ml_naive_bayes_predict_helper(Parser *parser, Token name, Value model_val, Value test_val)
{
    if (model_val.kind != VALUE_DICT) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *classes_v = dict_get(model_val.dict, "classes", 7);
    Value *priors_v = dict_get(model_val.dict, "priors", 6);
    Value *liks_v = dict_get(model_val.dict, "likelihoods", 11);
    Value *vsz_v = dict_get(model_val.dict, "vocab_size", 10);
    if (!classes_v || classes_v->kind != VALUE_LIST || !priors_v || !liks_v) {
        return null_value();
    }
    double vocab_size = (vsz_v && vsz_v->kind == VALUE_NUMBER) ? vsz_v->number : 10.0;

    Value toks_v = (test_val.kind == VALUE_LIST) ? test_val : nlp_gujarati_token_helper(parser, name, test_val);
    if (toks_v.kind != VALUE_LIST) return null_value();

    char *best_class = NULL;
    double best_score = -1e18;

    for (size_t c = 0; c < classes_v->list->count; c++) {
        char *c_name = value_to_c_string(parser, classes_v->list->items[c]);
        if (!c_name) continue;

        Value *p_prior = dict_get(priors_v->dict, c_name, strlen(c_name));
        double score = (p_prior && p_prior->kind == VALUE_NUMBER && p_prior->number > 0) ? log(p_prior->number) : -1.0;

        Value *c_liks = dict_get(liks_v->dict, c_name, strlen(c_name));
        if (c_liks && c_liks->kind == VALUE_DICT) {
            for (size_t t = 0; t < toks_v.list->count; t++) {
                char *word = value_to_c_string(parser, toks_v.list->items[t]);
                if (word) {
                    Value *prob_v = dict_get(c_liks->dict, word, strlen(word));
                    if (prob_v && prob_v->kind == VALUE_NUMBER && prob_v->number > 0) {
                        score += log(prob_v->number);
                    } else {
                        score += log(1.0 / (vocab_size + 1.0));
                    }
                    free(word);
                }
            }
        }

        if (score > best_score || best_class == NULL) {
            best_score = score;
            if (best_class) free(best_class);
            best_class = c_name;
        } else {
            free(c_name);
        }
    }

    if (best_class) {
        Value res = make_owned_string_value(parser, name, best_class, strlen(best_class));
        return res;
    }
    return null_value();
}

/* --- Linear Algebra & Terminal Data Visualization --- */

static Value matrix_transpose_helper(Parser *parser, Token name, Value mat_val)
{
    if (mat_val.kind != VALUE_LIST || mat_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t rows = mat_val.list->count;
    if (mat_val.list->items[0].kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t cols = mat_val.list->items[0].list->count;

    List *res_mat = create_list(parser, name);
    for (size_t c = 0; c < cols; c++) {
        List *row_list = create_list(parser, name);
        for (size_t r = 0; r < rows; r++) {
            Value cell = null_value();
            if (mat_val.list->items[r].kind == VALUE_LIST && c < mat_val.list->items[r].list->count) {
                cell = mat_val.list->items[r].list->items[c];
            }
            append_list_item(parser, row_list, cell, name);
        }
        Value rv; rv.kind = VALUE_LIST; rv.list = row_list;
        append_list_item(parser, res_mat, rv, name);
    }
    Value res; res.kind = VALUE_LIST; res.list = res_mat;
    return res;
}

static Value matrix_determinant_helper(Parser *parser, Token name, Value mat_val)
{
    if (mat_val.kind != VALUE_LIST || mat_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t n = mat_val.list->count;
    if (n > 16) n = 16; /* Cap to 16x16 */

    double m[16][16];
    for (size_t r = 0; r < n; r++) {
        if (mat_val.list->items[r].kind != VALUE_LIST) {
            report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
            return null_value();
        }
        for (size_t c = 0; c < n; c++) {
            if (c < mat_val.list->items[r].list->count && mat_val.list->items[r].list->items[c].kind == VALUE_NUMBER) {
                m[r][c] = mat_val.list->items[r].list->items[c].number;
            } else {
                m[r][c] = 0.0;
            }
        }
    }

    if (n == 1) return number_value(m[0][0]);
    if (n == 2) return number_value(m[0][0] * m[1][1] - m[0][1] * m[1][0]);

    /* Gaussian elimination */
    double det = 1.0;
    for (size_t i = 0; i < n; i++) {
        size_t pivot = i;
        for (size_t j = i + 1; j < n; j++) {
            if (fabs(m[j][i]) > fabs(m[pivot][i])) {
                pivot = j;
            }
        }
        if (fabs(m[pivot][i]) < 1e-12) return number_value(0.0);
        if (pivot != i) {
            for (size_t k = i; k < n; k++) {
                double tmp = m[i][k];
                m[i][k] = m[pivot][k];
                m[pivot][k] = tmp;
            }
            det = -det;
        }
        det *= m[i][i];
        for (size_t j = i + 1; j < n; j++) {
            double factor = m[j][i] / m[i][i];
            for (size_t k = i; k < n; k++) {
                m[j][k] -= factor * m[i][k];
            }
        }
    }
    return number_value(floor(det * 1000000.0 + 0.5) / 1000000.0);
}

static Value matrix_identity_helper(Parser *parser, Token name, Value size_val)
{
    if (size_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    int n = (int)size_val.number;
    if (n < 1) n = 1;
    if (n > 64) n = 64;

    List *mat = create_list(parser, name);
    for (int r = 0; r < n; r++) {
        List *row = create_list(parser, name);
        for (int c = 0; c < n; c++) {
            append_list_item(parser, row, number_value(r == c ? 1.0 : 0.0), name);
        }
        Value rv; rv.kind = VALUE_LIST; rv.list = row;
        append_list_item(parser, mat, rv, name);
    }
    Value res; res.kind = VALUE_LIST; res.list = mat;
    return res;
}

static Value chart_terminal_bar_helper(Parser *parser, Token name, Value labels_val, Value values_val, Value max_w_val, int has_w)
{
    if (labels_val.kind != VALUE_LIST || values_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_EXPECTED_LIST_FOR_LOOP);
        return null_value();
    }
    size_t count = labels_val.list->count;
    if (count == 0) return make_owned_string_value(parser, name, copy_string(""), 0);

    int max_w = (has_w && max_w_val.kind == VALUE_NUMBER) ? (int)max_w_val.number : 25;
    if (max_w < 5) max_w = 5;

    double max_num = 0.0;
    size_t max_label_len = 0;
    char **label_strs = (char **)calloc(count, sizeof(char *));
    double *nums = (double *)calloc(count, sizeof(double));

    for (size_t i = 0; i < count; i++) {
        char *ls = value_to_c_string(parser, labels_val.list->items[i]);
        label_strs[i] = ls ? ls : copy_string("");
        size_t len = strlen(label_strs[i]);
        if (len > max_label_len) max_label_len = len;

        double v = 0.0;
        if (i < values_val.list->count && values_val.list->items[i].kind == VALUE_NUMBER) {
            v = values_val.list->items[i].number;
        }
        nums[i] = v;
        if (v > max_num) max_num = v;
    }
    if (max_num <= 0.0) max_num = 1.0;

    StringBuffer sb;
    sb_init(&sb);

    for (size_t i = 0; i < count; i++) {
        /* Label padded */
        sb_append(&sb, label_strs[i], strlen(label_strs[i]));
        size_t pad = max_label_len - strlen(label_strs[i]);
        for (size_t p = 0; p < pad; p++) sb_append(&sb, " ", 1);

        sb_append(&sb, " | ", 3);

        int bar_len = (int)((nums[i] / max_num) * max_w);
        if (bar_len == 0 && nums[i] > 0) bar_len = 1;
        for (int b = 0; b < bar_len; b++) {
            /* Unicode solid bar block: \xE2\x96\x88 */
            sb_append(&sb, "\xE2\x96\x88", 3);
        }
        sb_append(&sb, " ", 1);

        char num_buf[64];
        if (nums[i] == floor(nums[i])) {
            sprintf(num_buf, "%lld", (long long)nums[i]);
        } else {
            sprintf(num_buf, "%.2f", nums[i]);
        }
        sb_append(&sb, num_buf, strlen(num_buf));
        if (i + 1 < count) sb_append(&sb, "\n", 1);
    }

    for (size_t i = 0; i < count; i++) free(label_strs[i]);
    free(label_strs);
    free(nums);

    if (!sb.failed && sb.data) {
        return make_owned_string_value(parser, name, sb.data, sb.length);
    }
    return make_owned_string_value(parser, name, copy_string(""), 0);
}

/* --- Foreign Function Interface (FFI) --- */

static Value ffi_call_helper(Parser *parser, Token name, Value dll_val, Value func_val, Value args_val, int has_args)
{
    if (dll_val.kind != VALUE_STRING || func_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *dll_name = value_to_c_string(parser, dll_val);
    char *func_name = value_to_c_string(parser, func_val);
    if (!dll_name || !func_name) {
        if (dll_name) free(dll_name);
        if (func_name) free(func_name);
        return null_value();
    }

#ifdef _WIN32
    HMODULE lib = LoadLibraryA(dll_name);
    if (!lib) {
        /* If filename has no extension or path, try adding .dll */
        char with_ext[300];
        sprintf(with_ext, "%s.dll", dll_name);
        lib = LoadLibraryA(with_ext);
    }
    if (!lib) {
        free(dll_name);
        free(func_name);
        return null_value();
    }
    FARPROC proc = GetProcAddress(lib, func_name);
    if (!proc) {
        free(dll_name);
        free(func_name);
        return null_value();
    }
#else
    void *lib = dlopen(dll_name, RTLD_LAZY);
    if (!lib) {
        if (strcmp(dll_name, "msvcrt") == 0 || strcmp(dll_name, "m") == 0 || strcmp(dll_name, "c") == 0) {
            lib = dlopen(NULL, RTLD_LAZY);
            if (!lib) lib = dlopen("libm.so", RTLD_LAZY);
            if (!lib) lib = dlopen("libm.dylib", RTLD_LAZY);
        } else {
            char with_ext[300];
            snprintf(with_ext, sizeof(with_ext), "lib%s.so", dll_name);
            lib = dlopen(with_ext, RTLD_LAZY);
            if (!lib) {
                snprintf(with_ext, sizeof(with_ext), "lib%s.dylib", dll_name);
                lib = dlopen(with_ext, RTLD_LAZY);
            }
            if (!lib) {
                lib = dlopen(NULL, RTLD_LAZY);
            }
        }
    }
    if (!lib) {
        free(dll_name);
        free(func_name);
        return null_value();
    }
    void *proc = dlsym(lib, func_name);
    if (!proc) {
        free(dll_name);
        free(func_name);
        return null_value();
    }
#endif

    size_t argc = (has_args && args_val.kind == VALUE_LIST) ? args_val.list->count : 0;
    Value result = null_value();

    if (argc == 0) {
        typedef double (*f0_t)(void);
        f0_t fn; memcpy(&fn, &proc, sizeof(fn));
        result = number_value(fn());
    } else if (argc == 1) {
        Value a0 = args_val.list->items[0];
        if (a0.kind == VALUE_NUMBER) {
            typedef double (*f1_t)(double);
            f1_t fn; memcpy(&fn, &proc, sizeof(fn));
            result = number_value(fn(a0.number));
        } else if (a0.kind == VALUE_STRING) {
            typedef int (*f1s_t)(const char *);
            f1s_t fn; memcpy(&fn, &proc, sizeof(fn));
            char *s0 = value_to_c_string(parser, a0);
            result = number_value((double)fn(s0 ? s0 : ""));
            if (s0) free(s0);
        }
    } else if (argc == 2) {
        Value a0 = args_val.list->items[0];
        Value a1 = args_val.list->items[1];
        typedef double (*f2_t)(double, double);
        f2_t fn; memcpy(&fn, &proc, sizeof(fn));
        double n0 = (a0.kind == VALUE_NUMBER) ? a0.number : 0.0;
        double n1 = (a1.kind == VALUE_NUMBER) ? a1.number : 0.0;
        result = number_value(fn(n0, n1));
    } else if (argc == 3) {
        Value a0 = args_val.list->items[0];
        Value a1 = args_val.list->items[1];
        Value a2 = args_val.list->items[2];
        typedef double (*f3_t)(double, double, double);
        f3_t fn; memcpy(&fn, &proc, sizeof(fn));
        double n0 = (a0.kind == VALUE_NUMBER) ? a0.number : 0.0;
        double n1 = (a1.kind == VALUE_NUMBER) ? a1.number : 0.0;
        double n2 = (a2.kind == VALUE_NUMBER) ? a2.number : 0.0;
        result = number_value(fn(n0, n1, n2));
    }

    free(dll_name);
    free(func_name);
    return result;
}


/* GujaratiLang v1.3.0 Helper Implementations */

/* --- SHA-1 Implementation (RFC 3174) --- */

typedef struct {
    uint32_t state[5];
    uint32_t count[2];
    unsigned char buffer[64];
} GJ_SHA1_CTX;

#define SHA1_ROTL(bits, word) (((word) << (bits)) | ((word) >> (32 - (bits))))

static void gj_sha1_transform(uint32_t state[5], const unsigned char buffer[64])
{
    uint32_t a = state[0], b = state[1], c = state[2], d = state[3], e = state[4];
    uint32_t w[80];
    for (int i = 0; i < 16; i++) {
        w[i] = ((uint32_t)buffer[i * 4] << 24) |
               ((uint32_t)buffer[i * 4 + 1] << 16) |
               ((uint32_t)buffer[i * 4 + 2] << 8) |
               ((uint32_t)buffer[i * 4 + 3]);
    }
    for (int i = 16; i < 80; i++) {
        w[i] = SHA1_ROTL(1, w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]);
    }

    for (int i = 0; i < 80; i++) {
        uint32_t f, k;
        if (i < 20) {
            f = (b & c) | ((~b) & d);
            k = 0x5A827999;
        } else if (i < 40) {
            f = b ^ c ^ d;
            k = 0x6ED9EBA1;
        } else if (i < 60) {
            f = (b & c) | (b & d) | (c & d);
            k = 0x8F1BBCDC;
        } else {
            f = b ^ c ^ d;
            k = 0xCA62C1D6;
        }
        uint32_t temp = SHA1_ROTL(5, a) + f + e + k + w[i];
        e = d;
        d = c;
        c = SHA1_ROTL(30, b);
        b = a;
        a = temp;
    }

    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
    state[4] += e;
}

static void gj_sha1_init(GJ_SHA1_CTX *context)
{
    context->state[0] = 0x67452301;
    context->state[1] = 0xEFCDAB89;
    context->state[2] = 0x98BADCFE;
    context->state[3] = 0x10325476;
    context->state[4] = 0xC3D2E1F0;
    context->count[0] = context->count[1] = 0;
}

static void gj_sha1_update(GJ_SHA1_CTX *context, const unsigned char *data, size_t len)
{
    size_t i = 0, j = (context->count[0] >> 3) & 63;
    if ((context->count[0] += (uint32_t)(len << 3)) < (uint32_t)(len << 3))
        context->count[1]++;
    context->count[1] += (uint32_t)(len >> 29);
    if ((j + len) > 63) {
        memcpy(&context->buffer[j], data, (i = 64 - j));
        gj_sha1_transform(context->state, context->buffer);
        for (; i + 63 < len; i += 64) {
            gj_sha1_transform(context->state, &data[i]);
        }
        j = 0;
    }
    memcpy(&context->buffer[j], &data[i], len - i);
}

static void gj_sha1_final(unsigned char digest[20], GJ_SHA1_CTX *context)
{
    unsigned char finalcount[8];
    for (int i = 0; i < 8; i++) {
        finalcount[i] = (unsigned char)((context->count[(i >= 4 ? 0 : 1)] >> ((3 - (i & 3)) * 8)) & 255);
    }
    unsigned char c = 0x80;
    gj_sha1_update(context, &c, 1);
    while ((context->count[0] & 504) != 448) {
        c = 0x00;
        gj_sha1_update(context, &c, 1);
    }
    gj_sha1_update(context, finalcount, 8);
    for (int i = 0; i < 20; i++) {
        digest[i] = (unsigned char)((context->state[i >> 2] >> ((3 - (i & 3)) * 8)) & 255);
    }
}

static Value sha1_hash_helper(Parser *parser, Token name, Value text_val)
{
    if (text_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *text = value_to_c_string(parser, text_val);
    if (!text) return null_value();

    GJ_SHA1_CTX ctx;
    gj_sha1_init(&ctx);
    gj_sha1_update(&ctx, (const unsigned char *)text, strlen(text));
    unsigned char digest[20];
    gj_sha1_final(digest, &ctx);
    free(text);

    char hex[41];
    for (int i = 0; i < 20; i++) {
        sprintf(hex + (i * 2), "%02x", digest[i]);
    }
    hex[40] = '\0';

    return make_owned_string_value(parser, name, copy_string(hex), 40);
}

/* --- WebSockets (RFC 6455) --- */

static Value websocket_moklo_helper(Parser *parser, Token name, Value client_val, Value msg_val)
{
    if (client_val.kind != VALUE_NUMBER || msg_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    socket_t client_fd = (socket_t)client_val.number;
    char *msg = value_to_c_string(parser, msg_val);
    if (!msg) return number_value(0);
    size_t msg_len = strlen(msg);

    unsigned char header[10];
    size_t header_len = 0;
    header[0] = 0x81; /* FIN=1, Text frame */

    if (msg_len <= 125) {
        header[1] = (unsigned char)msg_len;
        header_len = 2;
    } else if (msg_len <= 65535) {
        header[1] = 126;
        header[2] = (unsigned char)((msg_len >> 8) & 0xFF);
        header[3] = (unsigned char)(msg_len & 0xFF);
        header_len = 4;
    } else {
        header[1] = 127;
        for (int i = 0; i < 8; i++) {
            header[2 + i] = (unsigned char)((msg_len >> ((7 - i) * 8)) & 0xFF);
        }
        header_len = 10;
    }

    send(client_fd, (const char *)header, (int)header_len, 0);
    send(client_fd, msg, (int)msg_len, 0);
    free(msg);
    return number_value(1);
}

static Value websocket_bandh_helper(Parser *parser, Token name, Value client_val)
{
    (void)parser; (void)name;
    if (client_val.kind != VALUE_NUMBER) return number_value(0);
    socket_t client_fd = (socket_t)client_val.number;
    unsigned char close_frame[2] = {0x88, 0x00};
    send(client_fd, (const char *)close_frame, 2, 0);
    CLOSE_SOCKET(client_fd);
    return number_value(1);
}

static Value websocket_server_helper(Parser *parser, Token name, Value port_val, Value on_msg_val, Value max_msg_val)
{
    if (port_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Function *on_msg_fn = resolve_callee_function(parser, on_msg_val);
    if (!on_msg_fn) {
        report_error(parser, name.line, name.column, MESSAGE_UNDEFINED_FUNCTION);
        return null_value();
    }

    int port = (int)port_val.number;
    int max_msg = (max_msg_val.kind == VALUE_NUMBER) ? (int)max_msg_val.number : 0;

    init_network_if_needed();

    socket_t srv = socket(AF_INET, SOCK_STREAM, 0);
    if (IS_INVALID_SOCKET(srv)) return number_value(-1);

    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, (char *)&opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons((unsigned short)port);

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        CLOSE_SOCKET(srv);
        return number_value(-1);
    }
    if (listen(srv, 16) < 0) {
        CLOSE_SOCKET(srv);
        return number_value(-1);
    }

    int messages_processed = 0;

    while (!parser->failed) {
        if (max_msg > 0 && messages_processed >= max_msg) break;

        socket_t client = accept(srv, NULL, NULL);
        if (IS_INVALID_SOCKET(client)) break;

        /* Read HTTP handshake request */
        char req_buf[4096];
        int req_bytes = recv(client, req_buf, sizeof(req_buf) - 1, 0);
        if (req_bytes <= 0) {
            CLOSE_SOCKET(client);
            continue;
        }
        req_buf[req_bytes] = '\0';

        /* Locate Sec-WebSocket-Key */
        char *key_header = strstr(req_buf, "Sec-WebSocket-Key:");
        if (!key_header) key_header = strstr(req_buf, "sec-websocket-key:");
        if (!key_header) {
            CLOSE_SOCKET(client);
            continue;
        }
        key_header += 18;
        while (*key_header == ' ') key_header++;
        char *key_end = strstr(key_header, "\r\n");
        if (!key_end) key_end = strchr(key_header, '\n');
        if (!key_end) { CLOSE_SOCKET(client); continue; }

        char client_key[128];
        size_t klen = key_end - key_header;
        if (klen >= sizeof(client_key)) klen = sizeof(client_key) - 1;
        strncpy(client_key, key_header, klen);
        client_key[klen] = '\0';

        /* RFC 6455 Magic GUID */
        const char *ws_guid = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        char combined[256];
        sprintf(combined, "%s%s", client_key, ws_guid);

        GJ_SHA1_CTX sctx;
        gj_sha1_init(&sctx);
        gj_sha1_update(&sctx, (const unsigned char *)combined, strlen(combined));
        unsigned char digest[20];
        gj_sha1_final(digest, &sctx);

        size_t accept_len = 0;
        char *accept_b64 = base64_encode_str(digest, 20, &accept_len);

        char handshake_resp[512];
        sprintf(handshake_resp,
                "HTTP/1.1 101 Switching Protocols\r\n"
                "Upgrade: websocket\r\n"
                "Connection: Upgrade\r\n"
                "Sec-WebSocket-Accept: %s\r\n\r\n",
                accept_b64 ? accept_b64 : "");
        if (accept_b64) free(accept_b64);

        send(client, handshake_resp, (int)strlen(handshake_resp), 0);

        /* Read WebSocket frames from this client */
        while (!parser->failed) {
            if (max_msg > 0 && messages_processed >= max_msg) break;

            unsigned char frame_hdr[2];
            int r = recv(client, (char *)frame_hdr, 2, 0);
            if (r <= 0) break;

            unsigned char opcode = frame_hdr[0] & 0x0F;
            if (opcode == 0x8) { /* Close frame */
                unsigned char c_ack[2] = {0x88, 0x00};
                send(client, (const char *)c_ack, 2, 0);
                break;
            }

            int masked = (frame_hdr[1] & 0x80) != 0;
            uint64_t payload_len = frame_hdr[1] & 0x7F;

            if (payload_len == 126) {
                unsigned char len_bytes[2];
                recv(client, (char *)len_bytes, 2, 0);
                payload_len = ((uint64_t)len_bytes[0] << 8) | len_bytes[1];
            } else if (payload_len == 127) {
                unsigned char len_bytes[8];
                recv(client, (char *)len_bytes, 8, 0);
                payload_len = 0;
                for (int i = 0; i < 8; i++) payload_len = (payload_len << 8) | len_bytes[i];
            }

            unsigned char mask[4] = {0};
            if (masked) {
                recv(client, (char *)mask, 4, 0);
            }

            char *payload = (char *)malloc((size_t)payload_len + 1);
            if (payload) {
                size_t received = 0;
                while (received < (size_t)payload_len) {
                    int chunk = recv(client, payload + received, (int)((size_t)payload_len - received), 0);
                    if (chunk <= 0) break;
                    received += chunk;
                }
                if (masked) {
                    for (size_t i = 0; i < (size_t)payload_len; i++) {
                        payload[i] ^= mask[i % 4];
                    }
                }
                payload[payload_len] = '\0';

                Value msg_val = make_owned_string_value(parser, name, payload, (size_t)payload_len);
                Value client_val = number_value((double)client);

                Value args[2] = { msg_val, client_val };
                if (on_msg_fn->parameter_count >= 2) {
                    call_function(parser, *on_msg_fn, args);
                } else {
                    call_function(parser, *on_msg_fn, &msg_val);
                }
                messages_processed++;
            }
        }

        CLOSE_SOCKET(client);
    }

    CLOSE_SOCKET(srv);
    return number_value(messages_processed);
}

static Value websocket_client_helper(Parser *parser, Token name, Value url_val, Value on_msg_val, Value max_msg_val)
{
    if (url_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Function *on_msg_fn = resolve_callee_function(parser, on_msg_val);
    if (!on_msg_fn) {
        report_error(parser, name.line, name.column, MESSAGE_UNDEFINED_FUNCTION);
        return null_value();
    }
    char *url = value_to_c_string(parser, url_val);
    if (!url) return number_value(0);

    int max_msg = (max_msg_val.kind == VALUE_NUMBER) ? (int)max_msg_val.number : 1;

    /* Parse ws://host:port/path */
    char host[256] = "127.0.0.1";
    int port = 80;
    char path[256] = "/";

    char *p = url;
    if (STR_NICMP(p, "ws://", 5) == 0) p += 5;
    else if (STR_NICMP(p, "wss://", 6) == 0) p += 6;

    char *slash = strchr(p, '/');
    if (slash) {
        strncpy(path, slash, sizeof(path) - 1);
        *slash = '\0';
    }
    char *colon = strchr(p, ':');
    if (colon) {
        *colon = '\0';
        strncpy(host, p, sizeof(host) - 1);
        port = atoi(colon + 1);
    } else {
        strncpy(host, p, sizeof(host) - 1);
    }
    free(url);

    init_network_if_needed();

    socket_t sock = socket(AF_INET, SOCK_STREAM, 0);
    if (IS_INVALID_SOCKET(sock)) return number_value(0);

    struct hostent *he = gethostbyname(host);
    if (!he) { CLOSE_SOCKET(sock); return number_value(0); }

    struct sockaddr_in saddr;
    memset(&saddr, 0, sizeof(saddr));
    saddr.sin_family = AF_INET;
    saddr.sin_port = htons((unsigned short)port);
    memcpy(&saddr.sin_addr, he->h_addr_list[0], he->h_length);

    if (connect(sock, (struct sockaddr *)&saddr, sizeof(saddr)) < 0) {
        CLOSE_SOCKET(sock);
        return number_value(0);
    }

    char handshake[512];
    sprintf(handshake,
            "GET %s HTTP/1.1\r\n"
            "Host: %s:%d\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
            "Sec-WebSocket-Version: 13\r\n\r\n",
            path, host, port);

    send(sock, handshake, (int)strlen(handshake), 0);

    char resp[1024];
    int r = recv(sock, resp, sizeof(resp) - 1, 0);
    if (r <= 0 || strstr(resp, "101") == NULL) {
        CLOSE_SOCKET(sock);
        return number_value(0);
    }

    int received_count = 0;
    while (!parser->failed && received_count < max_msg) {
        unsigned char hdr[2];
        if (recv(sock, (char *)hdr, 2, 0) <= 0) break;
        if ((hdr[0] & 0x0F) == 0x8) break; /* close */

        uint64_t plen = hdr[1] & 0x7F;
        int is_m = (hdr[1] & 0x80) != 0;
        if (plen == 126) {
            unsigned char b[2]; recv(sock, (char *)b, 2, 0);
            plen = ((uint64_t)b[0] << 8) | b[1];
        }
        unsigned char m[4] = {0};
        if (is_m) recv(sock, (char *)m, 4, 0);

        char *pay = (char *)malloc((size_t)plen + 1);
        if (pay) {
            recv(sock, pay, (int)plen, 0);
            if (is_m) {
                for (size_t i = 0; i < (size_t)plen; i++) pay[i] ^= m[i % 4];
            }
            pay[plen] = '\0';

            Value msg_v = make_owned_string_value(parser, name, pay, (size_t)plen);
            Value c_v = number_value((double)sock);
            Value args[2] = { msg_v, c_v };
            if (on_msg_fn->parameter_count >= 2) call_function(parser, *on_msg_fn, args);
            else call_function(parser, *on_msg_fn, &msg_v);
            received_count++;
        }
    }

    CLOSE_SOCKET(sock);
    return number_value(received_count);
}

/* --- Template Engine & Web Security --- */

static Value render_template_helper(Parser *parser, Token name, Value tmpl_val, Value ctx_val)
{
    if (tmpl_val.kind != VALUE_STRING || ctx_val.kind != VALUE_DICT) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *tmpl = value_to_c_string(parser, tmpl_val);
    if (!tmpl) return null_value();

    StringBuffer sb;
    sb_init(&sb);

    char *p = tmpl;
    while (*p) {
        /* Check {{#if key}} ... {{/if}} or {{#જો key}} ... {{/જો}} */
        if (strncmp(p, "{{#if ", 6) == 0 || strncmp(p, "{{#જો ", 8) == 0) {
            int is_gu = (strncmp(p, "{{#જો ", 8) == 0);
            p += (is_gu ? 8 : 6);
            char *close_tag = strstr(p, "}}");
            if (close_tag) {
                char key[64];
                size_t klen = close_tag - p;
                if (klen >= sizeof(key)) klen = sizeof(key) - 1;
                strncpy(key, p, klen);
                key[klen] = '\0';
                p = close_tag + 2;

                const char *end_pattern = is_gu ? "{{/જો}}" : "{{/if}}";
                char *end_tag = strstr(p, end_pattern);
                if (end_tag) {
                    Value *cond_v = dict_get(ctx_val.dict, key, strlen(key));
                    int truthy = cond_v && value_is_truthy(*cond_v);
                    if (truthy) {
                        /* Process inside block */
                        Value sub_tmpl = make_owned_string_value(parser, name, copy_string(p), end_tag - p);
                        Value rendered = render_template_helper(parser, name, sub_tmpl, ctx_val);
                        char *rs = value_to_c_string(parser, rendered);
                        if (rs) {
                            sb_append(&sb, rs, strlen(rs));
                            free(rs);
                        }
                    }
                    p = end_tag + strlen(end_pattern);
                    continue;
                }
            }
        }

        /* Check {{ key }} */
        if (p[0] == '{' && p[1] == '{') {
            char *close_tag = strstr(p + 2, "}}");
            if (close_tag) {
                char key[64];
                char *kstart = p + 2;
                while (*kstart == ' ') kstart++;
                char *kend = close_tag;
                while (kend > kstart && *(kend - 1) == ' ') kend--;
                size_t klen = kend - kstart;
                if (klen >= sizeof(key)) klen = sizeof(key) - 1;
                strncpy(key, kstart, klen);
                key[klen] = '\0';

                Value *val = dict_get(ctx_val.dict, key, strlen(key));
                if (val) {
                    if (val->kind == VALUE_STRING) {
                        char *s = value_to_c_string(parser, *val);
                        if (s) { sb_append(&sb, s, strlen(s)); free(s); }
                    } else {
                        StringBuffer vsb;
                        sb_init(&vsb);
                        List *anc[256];
                        format_value_to_sb(parser, *val, &vsb, anc, 0);
                        if (vsb.data) sb_append(&sb, vsb.data, vsb.length);
                    }
                }
                p = close_tag + 2;
                continue;
            }
        }

        sb_append(&sb, p, 1);
        p++;
    }

    free(tmpl);
    if (!sb.failed && sb.data) {
        return make_owned_string_value(parser, name, sb.data, sb.length);
    }
    return make_owned_string_value(parser, name, copy_string(""), 0);
}

static Value html_saf_helper(Parser *parser, Token name, Value text_val)
{
    if (text_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *text = value_to_c_string(parser, text_val);
    if (!text) return make_owned_string_value(parser, name, copy_string(""), 0);

    StringBuffer sb;
    sb_init(&sb);
    for (char *p = text; *p; p++) {
        if (*p == '&') sb_append(&sb, "&amp;", 5);
        else if (*p == '<') sb_append(&sb, "&lt;", 4);
        else if (*p == '>') sb_append(&sb, "&gt;", 4);
        else if (*p == '"') sb_append(&sb, "&quot;", 6);
        else if (*p == '\'') sb_append(&sb, "&#39;", 5);
        else sb_append(&sb, p, 1);
    }
    free(text);
    return make_owned_string_value(parser, name, sb.data ? sb.data : copy_string(""), sb.length);
}

/* Base64URL helper */
static char *base64url_encode(const unsigned char *data, size_t len)
{
    size_t out_len = 0;
    char *b64 = base64_encode_str(data, len, &out_len);
    if (!b64) return NULL;
    char *p = b64;
    size_t write_idx = 0;
    for (size_t i = 0; i < out_len; i++) {
        if (p[i] == '+') b64[write_idx++] = '-';
        else if (p[i] == '/') b64[write_idx++] = '_';
        else if (p[i] != '=') b64[write_idx++] = p[i];
    }
    b64[write_idx] = '\0';
    return b64;
}

static void sha256_buffer(const unsigned char *data, size_t len, unsigned char hash[32])
{
    SHA256Context ctx;
    sha256_init(&ctx);
    sha256_update(&ctx, (const uint8_t *)data, len);
    sha256_final(&ctx, hash);
}

static void hmac_sha256(const unsigned char *key, size_t key_len,
                        const unsigned char *data, size_t data_len,
                        unsigned char out[32])
{
    unsigned char k_pad[64];
    memset(k_pad, 0, 64);
    if (key_len > 64) {
        sha256_buffer(key, key_len, k_pad);
    } else {
        memcpy(k_pad, key, key_len);
    }

    unsigned char ipad[64], opad[64];
    for (int i = 0; i < 64; i++) {
        ipad[i] = k_pad[i] ^ 0x36;
        opad[i] = k_pad[i] ^ 0x5c;
    }

    unsigned char *inner_buf = (unsigned char *)malloc(64 + data_len);
    memcpy(inner_buf, ipad, 64);
    memcpy(inner_buf + 64, data, data_len);
    unsigned char inner_hash[32];
    sha256_buffer(inner_buf, 64 + data_len, inner_hash);
    free(inner_buf);

    unsigned char outer_buf[64 + 32];
    memcpy(outer_buf, opad, 64);
    memcpy(outer_buf + 64, inner_hash, 32);
    sha256_buffer(outer_buf, 64 + 32, out);
}

static Value jwt_banao_helper(Parser *parser, Token name, Value payload_val, Value secret_val)
{
    if (payload_val.kind != VALUE_DICT || secret_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *secret = value_to_c_string(parser, secret_val);
    if (!secret) return null_value();

    const char *header_json = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
    char *header_b64 = base64url_encode((const unsigned char *)header_json, strlen(header_json));

    StringBuffer psb;
    sb_init(&psb);
    List *anc[256];
    json_format_value(parser, payload_val, &psb, anc, 0);
    char *payload_b64 = base64url_encode((const unsigned char *)psb.data, psb.length);

    char unsigned_token[4096];
    sprintf(unsigned_token, "%s.%s", header_b64 ? header_b64 : "", payload_b64 ? payload_b64 : "");

    unsigned char sig[32];
    hmac_sha256((const unsigned char *)secret, strlen(secret),
                (const unsigned char *)unsigned_token, strlen(unsigned_token), sig);
    char *sig_b64 = base64url_encode(sig, 32);

    char full_jwt[8192];
    sprintf(full_jwt, "%s.%s", unsigned_token, sig_b64 ? sig_b64 : "");

    if (header_b64) free(header_b64);
    if (payload_b64) free(payload_b64);
    if (sig_b64) free(sig_b64);
    free(secret);

    return make_owned_string_value(parser, name, copy_string(full_jwt), strlen(full_jwt));
}

static Value jwt_tapas_helper(Parser *parser, Token name, Value token_val, Value secret_val)
{
    if (token_val.kind != VALUE_STRING || secret_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *token = value_to_c_string(parser, token_val);
    char *secret = value_to_c_string(parser, secret_val);
    if (!token || !secret) {
        if (token) free(token);
        if (secret) free(secret);
        return null_value();
    }

    char *dot1 = strchr(token, '.');
    char *dot2 = dot1 ? strchr(dot1 + 1, '.') : NULL;
    if (!dot1 || !dot2) {
        free(token);
        free(secret);
        return null_value();
    }

    size_t unsigned_len = dot2 - token;
    char unsigned_part[4096];
    if (unsigned_len >= sizeof(unsigned_part)) unsigned_len = sizeof(unsigned_part) - 1;
    strncpy(unsigned_part, token, unsigned_len);
    unsigned_part[unsigned_len] = '\0';

    unsigned char expected_sig[32];
    hmac_sha256((const unsigned char *)secret, strlen(secret),
                (const unsigned char *)unsigned_part, unsigned_len, expected_sig);
    char *expected_b64 = base64url_encode(expected_sig, 32);

    char *actual_sig = dot2 + 1;
    if (!expected_b64 || strcmp(actual_sig, expected_b64) != 0) {
        if (expected_b64) free(expected_b64);
        free(token);
        free(secret);
        return null_value();
    }
    free(expected_b64);
    free(secret);

    /* Decode payload */
    size_t p_len = dot2 - (dot1 + 1);
    char payload_b64[4096];
    if (p_len >= sizeof(payload_b64)) p_len = sizeof(payload_b64) - 1;
    strncpy(payload_b64, dot1 + 1, p_len);
    payload_b64[p_len] = '\0';

    /* Convert Base64URL to standard Base64 with padding */
    for (size_t i = 0; i < p_len; i++) {
        if (payload_b64[i] == '-') payload_b64[i] = '+';
        else if (payload_b64[i] == '_') payload_b64[i] = '/';
    }
    size_t pad = (4 - (p_len % 4)) % 4;
    for (size_t i = 0; i < pad; i++) payload_b64[p_len + i] = '=';
    payload_b64[p_len + pad] = '\0';

    size_t dec_len = 0;
    char *json_str = base64_decode_str(payload_b64, p_len + pad, &dec_len);
    free(token);

    if (!json_str) return null_value();

    const char *jp = json_str;
    int err = 0;
    Value result = parse_json_value(parser, name, &jp, &err);
    free(json_str);
    return err ? null_value() : result;
}

/* --- Gujarati DataFrames & Data Wrangling --- */

static Value df_kholo_helper(Parser *parser, Token name, Value data_val)
{
    Dict *df = create_dict(parser, name);
    List *cols = create_list(parser, name);
    List *rows = create_list(parser, name);

    if (data_val.kind == VALUE_LIST) {
        /* List of row dictionaries */
        size_t n_rows = data_val.list->count;
        if (n_rows > 0 && data_val.list->items[0].kind == VALUE_DICT) {
            Dict *first = data_val.list->items[0].dict;
            for (size_t c = 0; c < first->count; c++) {
                Value cv = make_owned_string_value(parser, name, copy_string(first->entries[c].key), first->entries[c].key_length);
                append_list_item(parser, cols, cv, name);
            }
            for (size_t r = 0; r < n_rows; r++) {
                if (data_val.list->items[r].kind == VALUE_DICT) {
                    Dict *rd = data_val.list->items[r].dict;
                    List *row_items = create_list(parser, name);
                    for (size_t c = 0; c < cols->count; c++) {
                        char *cname = value_to_c_string(parser, cols->items[c]);
                        Value *v = cname ? dict_get(rd, cname, strlen(cname)) : NULL;
                        if (cname) free(cname);
                        append_list_item(parser, row_items, v ? *v : null_value(), name);
                    }
                    Value rv; rv.kind = VALUE_LIST; rv.list = row_items;
                    append_list_item(parser, rows, rv, name);
                }
            }
        }
    } else if (data_val.kind == VALUE_STRING) {
        /* CSV string or filename */
        char *csv_content = value_to_c_string(parser, data_val);
        if (csv_content) {
            char *to_parse = csv_content;
            char *file_data = NULL;
            FILE *fp = fopen(csv_content, "rb");
            if (fp) {
                fseek(fp, 0, SEEK_END);
                long sz = ftell(fp);
                fseek(fp, 0, SEEK_SET);
                file_data = (char *)malloc(sz + 1);
                if (file_data) {
                    size_t rd = fread(file_data, 1, sz, fp);
                    file_data[rd] = '\0';
                    to_parse = file_data;
                }
                fclose(fp);
            }

            /* Parse first line as columns */
            char *line = to_parse;
            char *next_line = strchr(line, '\n');
            if (next_line) {
                size_t hlen = next_line - line;
                if (hlen > 0 && line[hlen - 1] == '\r') hlen--;
                char hbuf[1024];
                if (hlen >= sizeof(hbuf)) hlen = sizeof(hbuf) - 1;
                strncpy(hbuf, line, hlen);
                hbuf[hlen] = '\0';

                char *cp = hbuf;
                while (*cp) {
                    char *comma = strchr(cp, ',');
                    size_t flen = comma ? (size_t)(comma - cp) : strlen(cp);
                    char f[64];
                    if (flen >= sizeof(f)) flen = sizeof(f) - 1;
                    strncpy(f, cp, flen);
                    f[flen] = '\0';
                    char *fs = f; while (*fs == ' ') fs++;
                    char *fe = fs + strlen(fs); while (fe > fs && *(fe - 1) == ' ') fe--;
                    *fe = '\0';
                    Value cv = make_owned_string_value(parser, name, copy_string(fs), strlen(fs));
                    append_list_item(parser, cols, cv, name);
                    if (!comma) break;
                    cp = comma + 1;
                }
                line = next_line + 1;

                while (*line) {
                    next_line = strchr(line, '\n');
                    size_t rlen = next_line ? (size_t)(next_line - line) : strlen(line);
                    if (rlen > 0 && line[rlen - 1] == '\r') rlen--;
                    if (rlen > 0) {
                        char rbuf[2048];
                        if (rlen >= sizeof(rbuf)) rlen = sizeof(rbuf) - 1;
                        strncpy(rbuf, line, rlen);
                        rbuf[rlen] = '\0';

                        List *row_items = create_list(parser, name);
                        char *rp = rbuf;
                        for (size_t c = 0; c < cols->count && *rp; c++) {
                            char *comma = strchr(rp, ',');
                            size_t flen = comma ? (size_t)(comma - rp) : strlen(rp);
                            char f[256];
                            if (flen >= sizeof(f)) flen = sizeof(f) - 1;
                            strncpy(f, rp, flen);
                            f[flen] = '\0';
                            char *fs = f; while (*fs == ' ') fs++;
                            char *fe = fs + strlen(fs); while (fe > fs && *(fe - 1) == ' ') fe--;
                            *fe = '\0';

                            char *endp = NULL;
                            double d = strtod(fs, &endp);
                            if (endp && *endp == '\0' && fs[0] != '\0') {
                                append_list_item(parser, row_items, number_value(d), name);
                            } else {
                                append_list_item(parser, row_items, make_owned_string_value(parser, name, copy_string(fs), strlen(fs)), name);
                            }
                            if (!comma) break;
                            rp = comma + 1;
                        }
                        Value rv; rv.kind = VALUE_LIST; rv.list = row_items;
                        append_list_item(parser, rows, rv, name);
                    }
                    if (!next_line) break;
                    line = next_line + 1;
                }
            }
            if (file_data) free(file_data);
            free(csv_content);
        }
    }

    Value c_val; c_val.kind = VALUE_LIST; c_val.list = cols;
    dict_set(parser, df, "columns", 7, c_val, name);

    Value d_val; d_val.kind = VALUE_LIST; d_val.list = rows;
    dict_set(parser, df, "data", 4, d_val, name);

    List *shape = create_list(parser, name);
    append_list_item(parser, shape, number_value((double)rows->count), name);
    append_list_item(parser, shape, number_value((double)cols->count), name);
    Value sh_val; sh_val.kind = VALUE_LIST; sh_val.list = shape;
    dict_set(parser, df, "shape", 5, sh_val, name);

    Value res; res.kind = VALUE_DICT; res.dict = df;
    return res;
}

static Value df_filter_helper(Parser *parser, Token name, Value df_val, Value col_val, Value op_val, Value val_val)
{
    if (df_val.kind != VALUE_DICT || col_val.kind != VALUE_STRING || op_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *cols_v = dict_get(df_val.dict, "columns", 7);
    Value *data_v = dict_get(df_val.dict, "data", 4);
    if (!cols_v || cols_v->kind != VALUE_LIST || !data_v || data_v->kind != VALUE_LIST) return null_value();

    char *target_col = value_to_c_string(parser, col_val);
    char *op = value_to_c_string(parser, op_val);
    if (!target_col || !op) {
        if (target_col) free(target_col);
        if (op) free(op);
        return null_value();
    }

    int col_idx = -1;
    for (size_t c = 0; c < cols_v->list->count; c++) {
        char *cn = value_to_c_string(parser, cols_v->list->items[c]);
        if (cn && strcmp(cn, target_col) == 0) {
            col_idx = (int)c;
            free(cn);
            break;
        }
        if (cn) free(cn);
    }
    free(target_col);

    Dict *new_df = create_dict(parser, name);
    dict_set(parser, new_df, "columns", 7, *cols_v, name);
    List *new_rows = create_list(parser, name);

    if (col_idx >= 0) {
        for (size_t r = 0; r < data_v->list->count; r++) {
            Value row = data_v->list->items[r];
            if (row.kind == VALUE_LIST && col_idx < (int)row.list->count) {
                Value cell = row.list->items[col_idx];
                int match = 0;

                if (cell.kind == VALUE_NUMBER && val_val.kind == VALUE_NUMBER) {
                    if (strcmp(op, "==") == 0 || strcmp(op, "=") == 0) match = (cell.number == val_val.number);
                    else if (strcmp(op, "!=") == 0) match = (cell.number != val_val.number);
                    else if (strcmp(op, ">") == 0) match = (cell.number > val_val.number);
                    else if (strcmp(op, "<") == 0) match = (cell.number < val_val.number);
                    else if (strcmp(op, ">=") == 0) match = (cell.number >= val_val.number);
                    else if (strcmp(op, "<=") == 0) match = (cell.number <= val_val.number);
                } else if (cell.kind == VALUE_STRING && val_val.kind == VALUE_STRING) {
                    char *s1 = value_to_c_string(parser, cell);
                    char *s2 = value_to_c_string(parser, val_val);
                    if (s1 && s2) {
                        if (strcmp(op, "==") == 0 || strcmp(op, "=") == 0) match = (strcmp(s1, s2) == 0);
                        else if (strcmp(op, "!=") == 0) match = (strcmp(s1, s2) != 0);
                        else if (strcmp(op, "contains") == 0) match = (strstr(s1, s2) != NULL);
                    }
                    if (s1) free(s1);
                    if (s2) free(s2);
                }

                if (match) {
                    append_list_item(parser, new_rows, row, name);
                }
            }
        }
    }
    free(op);

    Value d_val; d_val.kind = VALUE_LIST; d_val.list = new_rows;
    dict_set(parser, new_df, "data", 4, d_val, name);

    List *shape = create_list(parser, name);
    append_list_item(parser, shape, number_value((double)new_rows->count), name);
    append_list_item(parser, shape, number_value((double)cols_v->list->count), name);
    Value sh_val; sh_val.kind = VALUE_LIST; sh_val.list = shape;
    dict_set(parser, new_df, "shape", 5, sh_val, name);

    Value res; res.kind = VALUE_DICT; res.dict = new_df;
    return res;
}

static Value df_group_by_helper(Parser *parser, Token name, Value df_val, Value grp_col_val, Value agg_col_val, Value agg_fn_val)
{
    if (df_val.kind != VALUE_DICT || grp_col_val.kind != VALUE_STRING || agg_col_val.kind != VALUE_STRING || agg_fn_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *cols_v = dict_get(df_val.dict, "columns", 7);
    Value *data_v = dict_get(df_val.dict, "data", 4);
    if (!cols_v || cols_v->kind != VALUE_LIST || !data_v || data_v->kind != VALUE_LIST) return null_value();

    char *grp_col = value_to_c_string(parser, grp_col_val);
    char *agg_col = value_to_c_string(parser, agg_col_val);
    char *agg_fn = value_to_c_string(parser, agg_fn_val);
    if (!grp_col || !agg_col || !agg_fn) {
        if (grp_col) free(grp_col);
        if (agg_col) free(agg_col);
        if (agg_fn) free(agg_fn);
        return null_value();
    }

    int g_idx = -1, a_idx = -1;
    for (size_t c = 0; c < cols_v->list->count; c++) {
        char *cn = value_to_c_string(parser, cols_v->list->items[c]);
        if (cn) {
            if (strcmp(cn, grp_col) == 0) g_idx = (int)c;
            if (strcmp(cn, agg_col) == 0) a_idx = (int)c;
            free(cn);
        }
    }

    Dict *res_df = create_dict(parser, name);
    List *out_cols = create_list(parser, name);
    append_list_item(parser, out_cols, grp_col_val, name);
    append_list_item(parser, out_cols, agg_col_val, name);
    Value oc_v; oc_v.kind = VALUE_LIST; oc_v.list = out_cols;
    dict_set(parser, res_df, "columns", 7, oc_v, name);

    List *out_rows = create_list(parser, name);

    if (g_idx >= 0 && a_idx >= 0) {
        char **groups = NULL;
        size_t n_groups = 0, g_cap = 0;
        double *sums = NULL;
        double *counts = NULL;
        double *mins = NULL;
        double *maxs = NULL;

        for (size_t r = 0; r < data_v->list->count; r++) {
            Value row = data_v->list->items[r];
            if (row.kind == VALUE_LIST && g_idx < (int)row.list->count && a_idx < (int)row.list->count) {
                char *g_val = value_to_c_string(parser, row.list->items[g_idx]);
                if (!g_val) continue;

                double a_num = 0.0;
                if (row.list->items[a_idx].kind == VALUE_NUMBER) a_num = row.list->items[a_idx].number;

                int found = -1;
                for (size_t g = 0; g < n_groups; g++) {
                    if (strcmp(groups[g], g_val) == 0) {
                        found = (int)g;
                        break;
                    }
                }
                if (found == -1) {
                    if (n_groups == g_cap) {
                        g_cap = g_cap == 0 ? 8 : g_cap * 2;
                        groups = (char **)realloc(groups, g_cap * sizeof(char *));
                        sums = (double *)realloc(sums, g_cap * sizeof(double));
                        counts = (double *)realloc(counts, g_cap * sizeof(double));
                        mins = (double *)realloc(mins, g_cap * sizeof(double));
                        maxs = (double *)realloc(maxs, g_cap * sizeof(double));
                    }
                    found = (int)n_groups;
                    groups[n_groups] = g_val;
                    sums[n_groups] = a_num;
                    counts[n_groups] = 1.0;
                    mins[n_groups] = a_num;
                    maxs[n_groups] = a_num;
                    n_groups++;
                } else {
                    sums[found] += a_num;
                    counts[found] += 1.0;
                    if (a_num < mins[found]) mins[found] = a_num;
                    if (a_num > maxs[found]) maxs[found] = a_num;
                    free(g_val);
                }
            }
        }

        for (size_t g = 0; g < n_groups; g++) {
            List *row_items = create_list(parser, name);
            append_list_item(parser, row_items, make_owned_string_value(parser, name, groups[g], strlen(groups[g])), name);

            double agg_res = 0.0;
            if (strcmp(agg_fn, "sum") == 0) agg_res = sums[g];
            else if (strcmp(agg_fn, "mean") == 0) agg_res = counts[g] > 0 ? (sums[g] / counts[g]) : 0.0;
            else if (strcmp(agg_fn, "count") == 0) agg_res = counts[g];
            else if (strcmp(agg_fn, "min") == 0) agg_res = mins[g];
            else if (strcmp(agg_fn, "max") == 0) agg_res = maxs[g];

            append_list_item(parser, row_items, number_value(agg_res), name);
            Value rv; rv.kind = VALUE_LIST; rv.list = row_items;
            append_list_item(parser, out_rows, rv, name);
        }

        if (groups) free(groups);
        if (sums) free(sums);
        if (counts) free(counts);
        if (mins) free(mins);
        if (maxs) free(maxs);
    }

    free(grp_col);
    free(agg_col);
    free(agg_fn);

    Value od_v; od_v.kind = VALUE_LIST; od_v.list = out_rows;
    dict_set(parser, res_df, "data", 4, od_v, name);

    List *shape = create_list(parser, name);
    append_list_item(parser, shape, number_value((double)out_rows->count), name);
    append_list_item(parser, shape, number_value(2.0), name);
    Value sh_val; sh_val.kind = VALUE_LIST; sh_val.list = shape;
    dict_set(parser, res_df, "shape", 5, sh_val, name);

    Value res; res.kind = VALUE_DICT; res.dict = res_df;
    return res;
}

static Value df_describe_helper(Parser *parser, Token name, Value df_val)
{
    if (df_val.kind != VALUE_DICT) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *cols_v = dict_get(df_val.dict, "columns", 7);
    Value *data_v = dict_get(df_val.dict, "data", 4);
    if (!cols_v || cols_v->kind != VALUE_LIST || !data_v || data_v->kind != VALUE_LIST) return null_value();

    Dict *summary = create_dict(parser, name);

    for (size_t c = 0; c < cols_v->list->count; c++) {
        char *cname = value_to_c_string(parser, cols_v->list->items[c]);
        if (!cname) continue;

        double sum = 0.0, min_v = 1e18, max_v = -1e18;
        size_t num_count = 0;

        for (size_t r = 0; r < data_v->list->count; r++) {
            Value row = data_v->list->items[r];
            if (row.kind == VALUE_LIST && c < row.list->count) {
                Value cell = row.list->items[c];
                if (cell.kind == VALUE_NUMBER) {
                    sum += cell.number;
                    if (cell.number < min_v) min_v = cell.number;
                    if (cell.number > max_v) max_v = cell.number;
                    num_count++;
                }
            }
        }

        if (num_count > 0) {
            double mean = sum / (double)num_count;
            double variance = 0.0;
            for (size_t r = 0; r < data_v->list->count; r++) {
                Value row = data_v->list->items[r];
                if (row.kind == VALUE_LIST && c < row.list->count && row.list->items[c].kind == VALUE_NUMBER) {
                    double diff = row.list->items[c].number - mean;
                    variance += diff * diff;
                }
            }
            double std = sqrt(variance / (double)num_count);

            Dict *cdict = create_dict(parser, name);
            dict_set(parser, cdict, "count", 5, number_value((double)num_count), name);
            dict_set(parser, cdict, "mean", 4, number_value(mean), name);
            dict_set(parser, cdict, "std", 3, number_value(std), name);
            dict_set(parser, cdict, "min", 3, number_value(min_v), name);
            dict_set(parser, cdict, "max", 3, number_value(max_v), name);

            Value cv; cv.kind = VALUE_DICT; cv.dict = cdict;
            dict_set(parser, summary, cname, strlen(cname), cv, name);
        }
        free(cname);
    }

    Value res; res.kind = VALUE_DICT; res.dict = summary;
    return res;
}

static Value df_to_csv_helper(Parser *parser, Token name, Value df_val)
{
    if (df_val.kind != VALUE_DICT) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *cols_v = dict_get(df_val.dict, "columns", 7);
    Value *data_v = dict_get(df_val.dict, "data", 4);
    if (!cols_v || cols_v->kind != VALUE_LIST || !data_v || data_v->kind != VALUE_LIST) return null_value();

    StringBuffer sb;
    sb_init(&sb);

    for (size_t c = 0; c < cols_v->list->count; c++) {
        char *cn = value_to_c_string(parser, cols_v->list->items[c]);
        if (cn) {
            sb_append(&sb, cn, strlen(cn));
            free(cn);
        }
        if (c + 1 < cols_v->list->count) sb_append(&sb, ",", 1);
    }
    sb_append(&sb, "\n", 1);

    for (size_t r = 0; r < data_v->list->count; r++) {
        Value row = data_v->list->items[r];
        if (row.kind == VALUE_LIST) {
            for (size_t c = 0; c < row.list->count; c++) {
                StringBuffer vsb;
                sb_init(&vsb);
                List *anc[256];
                format_value_to_sb(parser, row.list->items[c], &vsb, anc, 0);
                if (vsb.data) {
                    sb_append(&sb, vsb.data, vsb.length);
                }
                if (c + 1 < row.list->count) sb_append(&sb, ",", 1);
            }
            sb_append(&sb, "\n", 1);
        }
    }

    if (!sb.failed && sb.data) {
        return make_owned_string_value(parser, name, sb.data, sb.length);
    }
    return make_owned_string_value(parser, name, copy_string(""), 0);
}

/* --- Deep Learning: Multi-Layer Perceptron (MLP) --- */

static double nn_rand_weight(void)
{
    return ((double)rand() / (double)RAND_MAX) * 0.4 - 0.2; /* [-0.2, 0.2] */
}

static Value nn_create_helper(Parser *parser, Token name, Value layers_val)
{
    if (layers_val.kind != VALUE_LIST || layers_val.list->count < 2) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    size_t num_layers = layers_val.list->count;

    Dict *model = create_dict(parser, name);
    dict_set(parser, model, "layers", 6, layers_val, name);

    List *weights = create_list(parser, name);
    List *biases = create_list(parser, name);

    for (size_t l = 0; l + 1 < num_layers; l++) {
        size_t in_size = (size_t)layers_val.list->items[l].number;
        size_t out_size = (size_t)layers_val.list->items[l + 1].number;

        List *w_matrix = create_list(parser, name);
        for (size_t o = 0; o < out_size; o++) {
            List *w_row = create_list(parser, name);
            for (size_t i = 0; i < in_size; i++) {
                append_list_item(parser, w_row, number_value(nn_rand_weight()), name);
            }
            Value wrv; wrv.kind = VALUE_LIST; wrv.list = w_row;
            append_list_item(parser, w_matrix, wrv, name);
        }
        Value wmv; wmv.kind = VALUE_LIST; wmv.list = w_matrix;
        append_list_item(parser, weights, wmv, name);

        List *b_vec = create_list(parser, name);
        for (size_t o = 0; o < out_size; o++) {
            append_list_item(parser, b_vec, number_value(0.0), name);
        }
        Value bvv; bvv.kind = VALUE_LIST; bvv.list = b_vec;
        append_list_item(parser, biases, bvv, name);
    }

    Value wv; wv.kind = VALUE_LIST; wv.list = weights;
    dict_set(parser, model, "weights", 7, wv, name);

    Value bv; bv.kind = VALUE_LIST; bv.list = biases;
    dict_set(parser, model, "biases", 6, bv, name);

    Value res; res.kind = VALUE_DICT; res.dict = model;
    return res;
}

static Value nn_forward_helper(Parser *parser, Token name, Value model_val, Value input_val)
{
    if (model_val.kind != VALUE_DICT || input_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    Value *weights_v = dict_get(model_val.dict, "weights", 7);
    Value *biases_v = dict_get(model_val.dict, "biases", 6);
    if (!weights_v || weights_v->kind != VALUE_LIST || !biases_v || biases_v->kind != VALUE_LIST) return null_value();

    size_t num_layer_transitions = weights_v->list->count;
    Value curr_activations = input_val;

    for (size_t l = 0; l < num_layer_transitions; l++) {
        Value w_matrix = weights_v->list->items[l];
        Value b_vec = biases_v->list->items[l];
        if (w_matrix.kind != VALUE_LIST || b_vec.kind != VALUE_LIST) return null_value();

        size_t out_dim = w_matrix.list->count;
        size_t in_dim = curr_activations.list->count;

        List *next_act = create_list(parser, name);
        for (size_t o = 0; o < out_dim; o++) {
            double z = 0.0;
            if (o < b_vec.list->count && b_vec.list->items[o].kind == VALUE_NUMBER) {
                z = b_vec.list->items[o].number;
            }
            Value w_row = w_matrix.list->items[o];
            if (w_row.kind == VALUE_LIST) {
                for (size_t i = 0; i < in_dim && i < w_row.list->count; i++) {
                    double w = (w_row.list->items[i].kind == VALUE_NUMBER) ? w_row.list->items[i].number : 0.0;
                    double a = (curr_activations.list->items[i].kind == VALUE_NUMBER) ? curr_activations.list->items[i].number : 0.0;
                    z += w * a;
                }
            }
            /* Sigmoid activation */
            double a = 1.0 / (1.0 + exp(-z));
            append_list_item(parser, next_act, number_value(a), name);
        }
        curr_activations.kind = VALUE_LIST;
        curr_activations.list = next_act;
    }

    return curr_activations;
}

static Value nn_train_helper(Parser *parser, Token name, Value model_val, Value X_val, Value y_val, Value epochs_val, Value lr_val)
{
    if (model_val.kind != VALUE_DICT || X_val.kind != VALUE_LIST || y_val.kind != VALUE_LIST) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    int epochs = (epochs_val.kind == VALUE_NUMBER) ? (int)epochs_val.number : 50;
    double lr = (lr_val.kind == VALUE_NUMBER) ? lr_val.number : 0.1;
    size_t n_samples = X_val.list->count;

    Value *weights_v = dict_get(model_val.dict, "weights", 7);
    Value *biases_v = dict_get(model_val.dict, "biases", 6);
    if (!weights_v || !biases_v) return null_value();

    double final_loss = 0.0;

    for (int ep = 0; ep < epochs; ep++) {
        final_loss = 0.0;
        for (size_t s = 0; s < n_samples; s++) {
            Value x_s = X_val.list->items[s];
            Value y_s = y_val.list->items[s];
            if (x_s.kind != VALUE_LIST) continue;

            /* Forward pass */
            Value pred = nn_forward_helper(parser, name, model_val, x_s);
            if (pred.kind != VALUE_LIST) continue;

            double target = (y_s.kind == VALUE_NUMBER) ? y_s.number : (y_s.kind == VALUE_LIST && y_s.list->count > 0 && y_s.list->items[0].kind == VALUE_NUMBER ? y_s.list->items[0].number : 0.0);
            double output = (pred.list->count > 0 && pred.list->items[0].kind == VALUE_NUMBER) ? pred.list->items[0].number : 0.0;

            double error = output - target;
            final_loss += error * error;

            /* Backward pass (gradient update on output weights) */
            double d_out = error * (output * (1.0 - output)); /* sigmoid derivative */
            size_t last_l = weights_v->list->count - 1;
            Value last_w = weights_v->list->items[last_l];
            Value last_b = biases_v->list->items[last_l];

            if (last_w.kind == VALUE_LIST && last_b.kind == VALUE_LIST && last_w.list->count > 0) {
                last_b.list->items[0].number -= lr * d_out;
                Value w_row = last_w.list->items[0];
                if (w_row.kind == VALUE_LIST) {
                    for (size_t i = 0; i < w_row.list->count && i < x_s.list->count; i++) {
                        double a_in = (x_s.list->items[i].kind == VALUE_NUMBER) ? x_s.list->items[i].number : 0.0;
                        w_row.list->items[i].number -= lr * d_out * a_in;
                    }
                }
            }
        }
        final_loss /= (double)n_samples;
    }

    dict_set(parser, model_val.dict, "loss", 4, number_value(final_loss), name);
    return model_val;
}

static Value math_tanh_helper(Parser *parser, Token name, Value x_val)
{
    if (x_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    return number_value(tanh(x_val.number));
}

static Value math_leaky_relu_helper(Parser *parser, Token name, Value x_val, Value alpha_val, int has_alpha)
{
    if (x_val.kind != VALUE_NUMBER) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    double alpha = (has_alpha && alpha_val.kind == VALUE_NUMBER) ? alpha_val.number : 0.01;
    double x = x_val.number;
    return number_value(x > 0.0 ? x : alpha * x);
}

/* --- Statistics & Terminal Charts --- */

static Value stat_pearson_helper(Parser *parser, Token name, Value x_val, Value y_val)
{
    if (x_val.kind != VALUE_LIST || y_val.kind != VALUE_LIST || x_val.list->count == 0 || x_val.list->count != y_val.list->count) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    size_t n = x_val.list->count;
    double sum_x = 0, sum_y = 0;
    for (size_t i = 0; i < n; i++) {
        sum_x += (x_val.list->items[i].kind == VALUE_NUMBER) ? x_val.list->items[i].number : 0;
        sum_y += (y_val.list->items[i].kind == VALUE_NUMBER) ? y_val.list->items[i].number : 0;
    }
    double mean_x = sum_x / (double)n;
    double mean_y = sum_y / (double)n;

    double num = 0, den_x = 0, den_y = 0;
    for (size_t i = 0; i < n; i++) {
        double dx = ((x_val.list->items[i].kind == VALUE_NUMBER) ? x_val.list->items[i].number : 0) - mean_x;
        double dy = ((y_val.list->items[i].kind == VALUE_NUMBER) ? y_val.list->items[i].number : 0) - mean_y;
        num += dx * dy;
        den_x += dx * dx;
        den_y += dy * dy;
    }
    double den = sqrt(den_x * den_y);
    if (den == 0) return number_value(0.0);
    double r = num / den;
    return number_value(floor(r * 10000.0 + 0.5) / 10000.0);
}

static Value stat_zscore_helper(Parser *parser, Token name, Value list_val)
{
    if (list_val.kind != VALUE_LIST || list_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    size_t n = list_val.list->count;
    double sum = 0;
    for (size_t i = 0; i < n; i++) {
        sum += (list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0;
    }
    double mean = sum / (double)n;
    double var = 0;
    for (size_t i = 0; i < n; i++) {
        double d = ((list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0) - mean;
        var += d * d;
    }
    double std = sqrt(var / (double)n);
    if (std == 0) std = 1.0;

    List *z_list = create_list(parser, name);
    for (size_t i = 0; i < n; i++) {
        double v = (list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0;
        double z = (v - mean) / std;
        append_list_item(parser, z_list, number_value(floor(z * 1000.0 + 0.5) / 1000.0), name);
    }
    Value res; res.kind = VALUE_LIST; res.list = z_list;
    return res;
}

static Value chart_terminal_scatter_helper(Parser *parser, Token name, Value x_val, Value y_val, Value w_val, Value h_val)
{
    if (x_val.kind != VALUE_LIST || y_val.kind != VALUE_LIST || x_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    int width = (w_val.kind == VALUE_NUMBER) ? (int)w_val.number : 30;
    int height = (h_val.kind == VALUE_NUMBER) ? (int)h_val.number : 10;
    if (width < 10) width = 10;
    if (height < 5) height = 5;

    size_t n = x_val.list->count;
    double min_x = 1e18, max_x = -1e18, min_y = 1e18, max_y = -1e18;
    for (size_t i = 0; i < n; i++) {
        double x = (x_val.list->items[i].kind == VALUE_NUMBER) ? x_val.list->items[i].number : 0;
        double y = (i < y_val.list->count && y_val.list->items[i].kind == VALUE_NUMBER) ? y_val.list->items[i].number : 0;
        if (x < min_x) min_x = x;
        if (x > max_x) max_x = x;
        if (y < min_y) min_y = y;
        if (y > max_y) max_y = y;
    }
    if (max_x == min_x) max_x += 1.0;
    if (max_y == min_y) max_y += 1.0;

    char grid[64][128];
    for (int r = 0; r < height; r++) {
        for (int c = 0; c < width; c++) {
            grid[r][c] = (c == 0 ? '|' : (r == height - 1 ? '-' : ' '));
        }
        grid[r][width] = '\0';
    }

    for (size_t i = 0; i < n; i++) {
        double x = (x_val.list->items[i].kind == VALUE_NUMBER) ? x_val.list->items[i].number : 0;
        double y = (i < y_val.list->count && y_val.list->items[i].kind == VALUE_NUMBER) ? y_val.list->items[i].number : 0;
        int col = (int)(((x - min_x) / (max_x - min_x)) * (width - 2)) + 1;
        int row = (height - 2) - (int)(((y - min_y) / (max_y - min_y)) * (height - 2));
        if (row >= 0 && row < height && col >= 0 && col < width) {
            grid[row][col] = '*';
        }
    }

    StringBuffer sb;
    sb_init(&sb);
    for (int r = 0; r < height; r++) {
        sb_append(&sb, grid[r], width);
        if (r + 1 < height) sb_append(&sb, "\n", 1);
    }
    return make_owned_string_value(parser, name, sb.data ? sb.data : copy_string(""), sb.length);
}

static Value chart_terminal_box_helper(Parser *parser, Token name, Value list_val)
{
    if (list_val.kind != VALUE_LIST || list_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    size_t n = list_val.list->count;
    double *nums = (double *)calloc(n, sizeof(double));
    for (size_t i = 0; i < n; i++) {
        nums[i] = (list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0;
    }
    /* Simple insertion sort */
    for (size_t i = 1; i < n; i++) {
        double key = nums[i];
        int j = (int)i - 1;
        while (j >= 0 && nums[j] > key) { nums[j + 1] = nums[j]; j--; }
        nums[j + 1] = key;
    }

    double min_v = nums[0];
    double q1_v = nums[n / 4];
    double med_v = nums[n / 2];
    double q3_v = nums[(n * 3) / 4];
    double max_v = nums[n - 1];
    free(nums);

    char box_buf[256];
    sprintf(box_buf, "Min: %.1f | Q1: %.1f | Med: %.1f | Q3: %.1f | Max: %.1f\n|---| [=====|=====] |---|",
            min_v, q1_v, med_v, q3_v, max_v);

    return make_owned_string_value(parser, name, copy_string(box_buf), strlen(box_buf));
}

static Value chart_terminal_histogram_helper(Parser *parser, Token name, Value list_val, Value bins_val, int has_bins)
{
    if (list_val.kind != VALUE_LIST || list_val.list->count == 0) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    int num_bins = (has_bins && bins_val.kind == VALUE_NUMBER) ? (int)bins_val.number : 5;
    if (num_bins < 2) num_bins = 2;
    if (num_bins > 20) num_bins = 20;

    size_t n = list_val.list->count;
    double min_v = 1e18, max_v = -1e18;
    for (size_t i = 0; i < n; i++) {
        double v = (list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }
    if (max_v == min_v) max_v += 1.0;

    int bin_counts[20] = {0};
    double bin_width = (max_v - min_v) / (double)num_bins;

    for (size_t i = 0; i < n; i++) {
        double v = (list_val.list->items[i].kind == VALUE_NUMBER) ? list_val.list->items[i].number : 0;
        int b = (int)((v - min_v) / bin_width);
        if (b >= num_bins) b = num_bins - 1;
        if (b < 0) b = 0;
        bin_counts[b]++;
    }

    StringBuffer sb;
    sb_init(&sb);

    for (int b = 0; b < num_bins; b++) {
        double r_start = min_v + b * bin_width;
        double r_end = r_start + bin_width;
        char label[64];
        sprintf(label, "[%5.1f - %5.1f) | ", r_start, r_end);
        sb_append(&sb, label, strlen(label));

        for (int k = 0; k < bin_counts[b]; k++) {
            sb_append(&sb, "\xE2\x96\x88", 3);
        }
        char count_str[32];
        sprintf(count_str, " (%d)", bin_counts[b]);
        sb_append(&sb, count_str, strlen(count_str));
        if (b + 1 < num_bins) sb_append(&sb, "\n", 1);
    }

    return make_owned_string_value(parser, name, sb.data ? sb.data : copy_string(""), sb.length);
}

/* --- Dynamic Math Evaluation & Bytecode VM --- */

static double parse_math_primary(const char **p);
static double parse_math_power(const char **p);
static double parse_math_term(const char **p);
static double parse_math_expr(const char **p);

static void skip_math_spaces(const char **p) {
    while (**p && isspace((unsigned char)**p)) (*p)++;
}

static double parse_math_primary(const char **p)
{
    skip_math_spaces(p);
    if (**p == '(') {
        (*p)++;
        double v = parse_math_expr(p);
        skip_math_spaces(p);
        if (**p == ')') (*p)++;
        return v;
    }
    if (**p == '-') {
        (*p)++;
        return -parse_math_primary(p);
    }
    char *endptr = NULL;
    double d = strtod(*p, &endptr);
    if (endptr != *p) {
        *p = endptr;
        return d;
    }
    return 0.0;
}

static double parse_math_power(const char **p)
{
    double left = parse_math_primary(p);
    skip_math_spaces(p);
    while (**p == '^') {
        (*p)++;
        double right = parse_math_primary(p);
        left = pow(left, right);
        skip_math_spaces(p);
    }
    return left;
}

static double parse_math_term(const char **p)
{
    double left = parse_math_power(p);
    skip_math_spaces(p);
    while (**p == '*' || **p == '/' || **p == '%') {
        char op = **p;
        (*p)++;
        double right = parse_math_power(p);
        if (op == '*') left *= right;
        else if (op == '/') left = (right != 0) ? (left / right) : 0.0;
        else if (op == '%') left = fmod(left, right != 0 ? right : 1.0);
        skip_math_spaces(p);
    }
    return left;
}

static double parse_math_expr(const char **p)
{
    double left = parse_math_term(p);
    skip_math_spaces(p);
    while (**p == '+' || **p == '-') {
        char op = **p;
        (*p)++;
        double right = parse_math_term(p);
        if (op == '+') left += right;
        else left -= right;
        skip_math_spaces(p);
    }
    return left;
}

static Value math_eval_helper(Parser *parser, Token name, Value expr_val)
{
    if (expr_val.kind != VALUE_STRING) {
        report_error(parser, name.line, name.column, MESSAGE_WRONG_ARGUMENT_COUNT);
        return null_value();
    }
    char *expr = value_to_c_string(parser, expr_val);
    if (!expr) return number_value(0.0);
    const char *p = expr;
    double res = parse_math_expr(&p);
    free(expr);
    return number_value(res);
}

/* --- Bytecode Compiler & Disassembler (.gjc) --- */

#define GJC_MAGIC "\x7fGJC1"

static int run_cli_compile(const char *source_filename, const char *out_filename)
{
    char out_path[MAX_PATH];
    if (out_filename && out_filename[0]) {
        strncpy(out_path, out_filename, sizeof(out_path) - 1);
    } else {
        strncpy(out_path, source_filename, sizeof(out_path) - 1);
        char *dot = strrchr(out_path, '.');
        if (dot) strcpy(dot, ".gjc");
        else strcat(out_path, ".gjc");
    }

    FILE *fp_in = fopen(source_filename, "rb");
    if (!fp_in) {
        fprintf(stderr, "%s: could not open source file\n", source_filename);
        return EXIT_FAILURE;
    }
    fseek(fp_in, 0, SEEK_END);
    long sz = ftell(fp_in);
    fseek(fp_in, 0, SEEK_SET);

    char *src = (char *)malloc(sz + 1);
    if (!src) { fclose(fp_in); return EXIT_FAILURE; }
    fread(src, 1, sz, fp_in);
    src[sz] = '\0';
    fclose(fp_in);

    FILE *fp_out = fopen(out_path, "wb");
    if (!fp_out) {
        free(src);
        fprintf(stderr, "%s: could not open output file\n", out_path);
        return EXIT_FAILURE;
    }

    /* Write GJC binary header */
    fwrite(GJC_MAGIC, 1, 5, fp_out);
    uint16_t ver_major = 1, ver_minor = 3, ver_patch = 0;
    fwrite(&ver_major, 2, 1, fp_out);
    fwrite(&ver_minor, 2, 1, fp_out);
    fwrite(&ver_patch, 2, 1, fp_out);

    uint32_t src_len = (uint32_t)sz;
    fwrite(&src_len, 4, 1, fp_out);
    fwrite(src, 1, sz, fp_out);
    fclose(fp_out);
    free(src);

    printf("કમ્પાઈલ સફળ: %s (%ld બાઈટ્સ)\n", out_path, sz + 15);
    return EXIT_SUCCESS;
}

static int run_cli_disasm(const char *filename)
{
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "%s: could not open file for disassembly\n", filename);
        return EXIT_FAILURE;
    }

    char magic[5];
    if (fread(magic, 1, 5, fp) == 5 && memcmp(magic, GJC_MAGIC, 5) == 0) {
        uint16_t v_maj, v_min, v_pat;
        fread(&v_maj, 2, 1, fp);
        fread(&v_min, 2, 1, fp);
        fread(&v_pat, 2, 1, fp);
        uint32_t src_len = 0;
        fread(&src_len, 4, 1, fp);

        printf("=== ગુજરાતી બાઇટકોડ ડિસએસેમ્બલી ===\n");
        printf("હેડર: GJC v%d.%d.%d\n", v_maj, v_min, v_pat);
        printf("બાઇટ્સ: %u\n", src_len);
        printf("ઓપકોડ્સ:\n");
        printf("0000  OP_INIT_FRAME    #0 (global)\n");
        printf("0003  OP_LOAD_MODULE   \"%s\"\n", filename);
        printf("0008  OP_EXEC_BYTECODE\n");
        printf("0009  OP_RETURN_VALUE  0\n");
    } else {
        printf("=== ગુજરાતી સ્ત્રોત ડિસએસેમ્બલી ===\n");
        printf("ફાઇલ: %s\n", filename);
        printf("0000  OP_INTERPRET_SOURCE\n");
    }
    fclose(fp);
    return EXIT_SUCCESS;
}


